  function persistenceReplacer(key, value) {
    if (value instanceof Map) return { __tdsType: 'Map', value: [...value.entries()] };
    if (value instanceof Set) return { __tdsType: 'Set', value: [...value.values()] };
    return value;
  }

  function persistenceReviver(key, value) {
    if (!value || typeof value !== 'object') return value;
    if (value.__tdsType === 'Map' && Array.isArray(value.value)) return new Map(value.value);
    if (value.__tdsType === 'Set' && Array.isArray(value.value)) return new Set(value.value);
    return value;
  }

  function setupPersistenceSnapshot() {
    return {
      simulationName: document.getElementById('simulationName')?.value || 'Camp Wawanakwa',
      participantCount: elements.participantCount?.value || '16',
      mergeAt: elements.mergeAt?.value || '9',
      endingFormat: elements.endingFormat?.value || 'final-two-race',
      teamCount: document.querySelector('input[name="teamCount"]:checked')?.value || '2',
      options: readSeasonOptionsFromSetup(),
      lateEntrantId: elements.lateEntrantSelect?.value || state.lateEntrantId || ''
    };
  }

  function applySetupPersistenceSnapshot(snapshot) {
    if (!snapshot || typeof snapshot !== 'object') return;
    const name = document.getElementById('simulationName');
    if (name && typeof snapshot.simulationName === 'string') name.value = snapshot.simulationName;
    if (elements.participantCount && snapshot.participantCount != null) elements.participantCount.value = String(snapshot.participantCount);
    if (elements.mergeAt && snapshot.mergeAt != null) elements.mergeAt.value = String(snapshot.mergeAt);
    if (elements.endingFormat && snapshot.endingFormat) elements.endingFormat.value = snapshot.endingFormat;
    const teamRadio = document.querySelector(`input[name="teamCount"][value="${snapshot.teamCount || '2'}"]`);
    if (teamRadio) teamRadio.checked = true;
    Object.entries(snapshot.options || {}).forEach(([key, checked]) => {
      const input = document.querySelector(`[data-season-option="${key}"]`);
      if (input) input.checked = Boolean(checked);
    });
    state.lateEntrantId = snapshot.lateEntrantId || '';
    refreshLateEntrantPicker();
    if (elements.lateEntrantSelect && state.lateEntrantId) elements.lateEntrantSelect.value = state.lateEntrantId;
  }

  function serializableSimulatorState() {
    const snapshot = {};
    Object.entries(state).forEach(([key, value]) => {
      if (!PERSISTENCE_OMIT_KEYS.has(key)) snapshot[key] = value;
    });
    return snapshot;
  }

  function compactSerializableSimulatorState() {
    const keep = new Set([
      'customContestants', 'selectedIds', 'selectedShows', 'selectedSeasons',
      'profilesById', 'relationships', 'teams', 'teamSetupSignature', 'activeIds',
      'directionalRelationships', 'contestantRuntime', 'alliances', 'usedAllianceNames',
      'currentChallenge', 'usedChallengeIds', 'usedIndividualChallengeIds',
      'challengeResult', 'challengeRevealed', 'voteResult', 'voteRevealIndex',
      'voteCeremonyFinished', 'episodeNumber', 'merged', 'mergedTeamName',
      'usedTeamNames', 'statusSnapshot', 'episodes', 'currentEpisodeIndex',
      'isHistoricalView', 'seasonStarted', 'finaleFormat', 'episodeType',
      'mergeOpening', 'automaticEliminatedId', 'juryResult', 'juryRevealIndex',
      'juryRevealed', 'returnChallengeRevealed', 'seasonWinnerId', 'seasonComplete',
      'finalPlacements', 'seasonOptions', 'lateEntrantId', 'twistState',
      'episodeOutcome', 'pendingExile', 'idolState'
    ]);
    const snapshot = {};
    keep.forEach(key => { if (Object.hasOwn(state, key)) snapshot[key] = state[key]; });
    return snapshot;
  }

  function persistSimulatorState() {
    if (!persistenceReady || persistenceDisabledByQuota) return;
    if (state.seasonStarted && state.episodes.length) syncCurrentEpisodeRecord();

    const makePayload = compact => ({
      version: PERSISTENCE_VERSION,
      savedAt: Date.now(),
      storageMode: compact ? 'compact' : 'full',
      setup: setupPersistenceSnapshot(),
      ui: {
        activeScreenId,
        activeEpisodePanel,
        activeStatsPanel,
        scrollY: Math.max(0, Math.round(window.scrollY || 0))
      },
      state: compact ? compactSerializableSimulatorState() : serializableSimulatorState()
    });

    try {
      const payload = makePayload(persistenceCompactMode);
      localStorage.setItem(PERSISTENCE_KEY, JSON.stringify(payload, persistenceReplacer));
      return;
    } catch (error) {
      if (error?.name !== 'QuotaExceededError' || persistenceCompactMode) {
        if (error?.name === 'QuotaExceededError') {
          persistenceDisabledByQuota = true;
          clearTimeout(persistenceTimer);
          console.warn('Simulator auto-save is disabled for this session because even the compact save exceeds browser storage. The season itself can continue normally.');
          showToast('Auto-save is off: browser storage is full.', 'warning');
          return;
        }
        console.warn('The simulator state could not be saved.', error);
        return;
      }
    }

    try {
      const compactPayload = makePayload(true);
      localStorage.setItem(PERSISTENCE_KEY, JSON.stringify(compactPayload, persistenceReplacer));
      persistenceCompactMode = true;
      console.warn('Simulator auto-save switched to compact mode because the full runtime exceeded browser storage.');
    } catch (compactError) {
      persistenceDisabledByQuota = true;
      clearTimeout(persistenceTimer);
      console.warn('Simulator auto-save is disabled for this session because browser storage is full.', compactError);
      showToast('Auto-save is off: browser storage is full.', 'warning');
    }
  }

  function scheduleSimulatorPersistence() {
    if (!persistenceReady || persistenceDisabledByQuota || seasonPreparationRunning) return;
    clearTimeout(persistenceTimer);
    persistenceTimer = window.setTimeout(persistSimulatorState, 80);
  }

  function restorePersistedSimulatorState() {
    let payload;
    try {
      const raw = localStorage.getItem(PERSISTENCE_KEY);
      if (!raw) return null;
      payload = JSON.parse(raw, persistenceReviver);
    } catch (error) {
      console.warn('The saved simulator state could not be read.', error);
      return null;
    }
    if (!payload || payload.version !== PERSISTENCE_VERSION || !payload.state) return null;

    applySetupPersistenceSnapshot(payload.setup);
    Object.entries(payload.state).forEach(([key, value]) => {
      if (Object.hasOwn(state, key) && !PERSISTENCE_OMIT_KEYS.has(key)) state[key] = value;
    });
    state.customContestants = Array.isArray(state.customContestants) ? state.customContestants.filter(item => item && item.id) : [];
    rebuildContestantIndex();

    state.selectedIds = (state.selectedIds || []).filter(id => state.contestantById.has(id));
    state.activeIds = (state.activeIds || []).filter(id => state.contestantById.has(id));
    state.selectedShows = state.selectedShows instanceof Set ? state.selectedShows : new Set(state.selectedShows || []);
    state.selectedSeasons = state.selectedSeasons instanceof Set ? state.selectedSeasons : new Set(state.selectedSeasons || []);
    state.profilesById = state.profilesById instanceof Map ? state.profilesById : new Map(state.profilesById || []);
    state.relationships = state.relationships instanceof Map ? state.relationships : new Map(state.relationships || []);
    state.directionalRelationships = state.directionalRelationships instanceof Map ? state.directionalRelationships : new Map(state.directionalRelationships || []);
    state.trust = state.trust instanceof Map ? state.trust : new Map(state.trust || []);
    state.suspicion = state.suspicion instanceof Map ? state.suspicion : new Map(state.suspicion || []);
    state.irritation = state.irritation instanceof Map ? state.irritation : new Map(state.irritation || []);
    state.grudges = state.grudges instanceof Map ? state.grudges : new Map(state.grudges || []);
    state.targetPriority = state.targetPriority instanceof Map ? state.targetPriority : new Map(state.targetPriority || []);
    state.voteCommitment = state.voteCommitment instanceof Map ? state.voteCommitment : new Map(state.voteCommitment || []);
    state.votePlans = state.votePlans instanceof Map ? state.votePlans : new Map(state.votePlans || []);
    state.contestantRuntime = state.contestantRuntime instanceof Map ? state.contestantRuntime : new Map(state.contestantRuntime || []);
    state.teamRuntime = state.teamRuntime instanceof Map ? state.teamRuntime : new Map(state.teamRuntime || []);
    state.relationshipControls = new Map();
    state.activeEditId = null;
    state.autoSimulating = false;
    state.eventSnapshots = { preChallenge: null, preVote: null };
    state.sectionCheckpoints = { episodeStart: null, afterPreChallenge: null, afterChallenge: null, afterPreVote: null, afterVote: null };
    state.challengeSnapshot = null;
    state.liveMergeState = null;
    state.juryRevealActive = false;
    if (state.voteResult) state.voteResult.autoRevealActive = false;

    return payload.ui || {};
  }

  function activateStatsPanel(targetId = 'stats-voting') {
    const validTarget = document.getElementById(targetId) ? targetId : 'stats-voting';
    activeStatsPanel = validTarget;
    document.querySelectorAll('.stats-tab').forEach(tab => tab.classList.toggle('is-active', tab.dataset.statsTarget === validTarget));
    document.querySelectorAll('.stats-panel').forEach(panel => panel.classList.toggle('is-active', panel.id === validTarget));
    scheduleSimulatorPersistence();
  }

  function restorePersistedInterface(ui = {}) {
    renderAllFilters();
    updateSetup();

    if (state.seasonStarted && state.episodes.length) {
      state.currentEpisodeIndex = Math.max(0, Math.min(Number(state.currentEpisodeIndex) || 0, state.episodes.length - 1));
      updateRoundSelect();
      renderEpisodeRecord();
    }

    const validScreens = new Set(['setup-screen', 'participants-screen', 'simulation-screen', 'statistics-screen']);
    let screenId = validScreens.has(ui.activeScreenId) ? ui.activeScreenId : (state.seasonStarted ? 'simulation-screen' : 'participants-screen');
    if (!state.seasonStarted && (screenId === 'simulation-screen' || screenId === 'statistics-screen')) screenId = 'participants-screen';

    activeScreenId = screenId;
    activeEpisodePanel = typeof ui.activeEpisodePanel === 'string' ? ui.activeEpisodePanel : 'overview';
    activeStatsPanel = typeof ui.activeStatsPanel === 'string' ? ui.activeStatsPanel : 'stats-voting';
    showScreen(screenId);
    activateStatsPanel(activeStatsPanel);
    if (state.seasonStarted && screenId === 'simulation-screen') openEpisodePanel(activeEpisodePanel);

    const scrollY = Math.max(0, Number(ui.scrollY) || 0);
    requestAnimationFrame(() => requestAnimationFrame(() => window.scrollTo({ top: scrollY, behavior: 'auto' })));
  }

  function clamp(value, min = 1, max = 15) {
    return Math.max(min, Math.min(max, Math.round(Number(value) || DEFAULT_STAT)));
  }

  function naturalCompare(a, b) {
    return String(a || '').localeCompare(String(b || ''), undefined, { numeric: true, sensitivity: 'base' });
  }

  function showPriority(show) {
    const normalized = String(show || '').trim().toLowerCase();
    if (normalized === CUSTOM_SHOW.toLowerCase()) return -1;
    return normalized.startsWith('total drama') || normalized === 'the ridonculous race' ? 0 : 1;
  }

  function sortedShows() {
    const values = new Set([CUSTOM_SHOW]);
    state.contestants.forEach(contestant => (contestant.shows || []).forEach(show => values.add(show)));
    return [...values].sort((a, b) => showPriority(a) - showPriority(b) || naturalCompare(a, b));
  }

  function seasonsForShow(show) {
    const values = new Set();
    state.contestants.forEach(contestant => {
      (contestant.seasonsByShow?.[show] || []).forEach(season => values.add(String(season)));
    });
    return [...values].sort(naturalCompare);
  }

  function seasonKey(show, season) {
    return `${show}\u0000${season}`;
  }

  function splitSeasonKey(key) {
    const index = key.indexOf('\u0000');
    return [key.slice(0, index), key.slice(index + 1)];
  }

  function baselineSkills() {
    return Object.fromEntries(ALL_SKILLS.map(([key]) => [key, DEFAULT_STAT]));
  }

  function randomSkillValue() {
    return clamp(1 + Math.round((Math.random() + Math.random()) * 7));
  }

  function randomSkills() {
    return Object.fromEntries(ALL_SKILLS.map(([key]) => [key, randomSkillValue()]));
  }

  function makeSeed() {
    return Object.fromEntries(HIDDEN_TRAIT_KEYS.map(key => [key, Math.random() * 4 - 2]));
  }

  function ensureHiddenSeed(profile) {
    if (!profile.seed || typeof profile.seed !== 'object') profile.seed = {};
    HIDDEN_TRAIT_KEYS.forEach(key => {
      if (!Number.isFinite(Number(profile.seed[key]))) profile.seed[key] = Math.random() * 4 - 2;
    });
    return profile.seed;
  }

  function archetypePreset(name) {
    const archetype = ARCHETYPE_BY_NAME.get(name);
    if (!archetype) return baselineSkills();
    return Object.fromEntries(ALL_SKILLS.map(([key]) => [
      key,
      clamp(archetype.skills?.[key] ?? DEFAULT_STAT)
    ]));
  }

  function archetypeHiddenPreset(name) {
    const archetype = ARCHETYPE_BY_NAME.get(name);
    if (!archetype) return null;
    return Object.fromEntries(HIDDEN_TRAIT_KEYS.map(key => [
      key,
      clamp(archetype.hidden?.[key] ?? DEFAULT_STAT)
    ]));
  }

  function deriveHidden(profile) {
    const preset = archetypeHiddenPreset(profile.archetype);
    if (preset) return preset;

    const skills = profile.skills;
    const seed = ensureHiddenSeed(profile);
    return Object.fromEntries(HIDDEN_TRAIT_KEYS.map(key => {
      const formula = HIDDEN_TRAIT_FORMULAS[key];
      const skillDerived = typeof formula === 'function' ? Number(formula(skills) || 0) : 0;
      return [key, clamp(8 + skillDerived + Number(seed[key] || 0))];
    }));
  }

  function getProfile(id) {
    if (!state.profilesById.has(id)) {
      const contestant = state.contestantById.get(id);
      const storedSkills = contestant?.isCustom && contestant.skills && typeof contestant.skills === 'object'
        ? Object.fromEntries(ALL_SKILLS.map(([key]) => [key, clamp(contestant.skills[key] ?? DEFAULT_STAT)]))
        : baselineSkills();
      const profile = { archetype: '', skills: storedSkills, randomizedArchetypeMods: {}, archetypePresetVersion: 0, seed: makeSeed(), hidden: {} };
      profile.hidden = deriveHidden(profile);
      state.profilesById.set(id, profile);
    }

    const profile = state.profilesById.get(id);
    if (ARCHETYPE_BY_NAME.has(profile.archetype) && Number(profile.archetypePresetVersion || 0) < ARCHETYPE_PRESET_VERSION) {
      profile.skills = archetypePreset(profile.archetype);
      profile.hidden = archetypeHiddenPreset(profile.archetype);
      profile.archetypePresetVersion = ARCHETYPE_PRESET_VERSION;
      profile.randomizedArchetypeMods = {};
    }
    const skillsAreIncomplete = !profile.skills
      || typeof profile.skills !== 'object'
      || ALL_SKILLS.some(([key]) => !Number.isFinite(Number(profile.skills[key])));
    if (skillsAreIncomplete) {
      profile.skills = Object.fromEntries(ALL_SKILLS.map(([key]) => [key, clamp(profile.skills?.[key] ?? DEFAULT_STAT)]));
    }
    profile.randomizedArchetypeMods ||= {};
    if (!Number.isFinite(Number(profile.archetypePresetVersion))) profile.archetypePresetVersion = 0;
    const hiddenIsIncomplete = !profile.hidden || HIDDEN_TRAIT_KEYS.some(key => !Number.isFinite(Number(profile.hidden[key])));
    const seedIsIncomplete = !profile.seed || HIDDEN_TRAIT_KEYS.some(key => !Number.isFinite(Number(profile.seed[key])));
    if (hiddenIsIncomplete || seedIsIncomplete) profile.hidden = deriveHidden(profile);
    return profile;
  }

  function refreshHidden(profile) {
    profile.hidden = deriveHidden(profile);
  }

  function teamCount() {
    return Number(document.querySelector('input[name="teamCount"]:checked')?.value || 2);
  }

  function teamDistribution(cast, teams) {
    const base = Math.floor(cast / teams);
    const remainder = cast % teams;
    return Array.from({ length: teams }, (_, index) => base + (index < remainder ? 1 : 0));
  }

  function castLimit() {
    return Number(elements.participantCount?.value || 16);
  }

  function finaleLabel() {
    return elements.endingFormat?.options[elements.endingFormat.selectedIndex]?.text || 'Final Two Race';
  }

  function selectedFinaleFormat() {
    const value = elements.endingFormat?.value || 'final-two-race';
    const supported = new Set([
      'final-two-race', 'final-two-jury', 'final-three-race', 'final-three-jury', 'final-four-showdown'
    ]);
    return supported.has(value) ? value : 'final-two-race';
  }

  function finaleTargetCount(format = state.finaleFormat) {
    if (format === 'final-three-race' || format === 'final-three-jury') return 3;
    if (format === 'final-four-showdown') return 4;
    return 3;
  }

  function isJuryFinale(format = state.finaleFormat) {
    return format === 'final-two-jury' || format === 'final-three-jury';
  }

  function isRaceFinale(format = state.finaleFormat) {
    return format === 'final-two-race' || format === 'final-three-race' || format === 'final-four-showdown';
  }

  function episodeHasJuryFinale() {
    return Boolean(state.juryResult);
  }

  function episodeIsRaceFinale() {
    return state.episodeType === 'finale-race';
  }

  function episodeUsesSoleVote() {
    return state.episodeType === 'semifinal-sole-vote' || state.episodeType === 'final-four-showdown';
  }

  function readSeasonOptionsFromSetup() {
    return Object.fromEntries(
      [...document.querySelectorAll('[data-season-option]')]
        .map(input => [input.dataset.seasonOption, Boolean(input.checked)])
    );
  }

  function seasonOptionEnabled(key) {
    return Boolean(state.seasonOptions?.[key]);
  }

  function lateEntrantOptionEnabled() {
    return Boolean(document.querySelector('[data-season-option="lateEntrant"]')?.checked);
  }

  function refreshLateEntrantPicker() {
    if (!elements.lateEntrantSelect) return;
    const enabled = lateEntrantOptionEnabled();
    const previous = elements.lateEntrantSelect.value || state.lateEntrantId || '';
    const eligible = state.selectedIds
      .map(id => state.contestantById.get(id))
      .filter(Boolean)
      .sort((first, second) => naturalCompare(first.fullName || first.nickname, second.fullName || second.nickname));
    elements.lateEntrantSelect.replaceChildren();
    const placeholder = document.createElement('option');
    placeholder.value = '';
    placeholder.textContent = 'Choose a contestant from the selected cast…';
    elements.lateEntrantSelect.append(placeholder);
    eligible.forEach(contestant => {
      const option = document.createElement('option');
      option.value = contestant.id;
      option.textContent = contestant.fullName || contestant.nickname || 'Unnamed contestant';
      elements.lateEntrantSelect.append(option);
    });
    const validPrevious = enabled && eligible.some(item => item.id === previous) ? previous : '';
    elements.lateEntrantSelect.value = validPrevious;
    state.lateEntrantId = validPrevious;
    if (elements.lateEntrantMessage) {
      elements.lateEntrantMessage.hidden = true;
      elements.lateEntrantMessage.textContent = '';
    }
  }

  function startingCastIds() {
    const excludedId = lateEntrantOptionEnabled() ? state.lateEntrantId : '';
    return state.selectedIds.filter(id => id !== excludedId);
  }

  function createEmptyEpisodeOutcome() {
    return {
      type: 'normal',
      arrivals: [],
      departures: [],
      teamChanges: [],
      exile: null,
      returnChallenge: null,
      idolPlay: null,
      noElimination: false,
      voteOffTeam: false,
      cancelVote: false,
      doubleElimination: false,
      notes: []
    };
  }

  function createInitialTwistState() {
    return {
      completed: {
        return: false,
        returnChallenge: false,
        lateEntrant: false,
        teamSwap: false,
        nonElimination: false,
        doubleElimination: false,
        challengeElimination: false
      },
      lastMajorEpisode: -10,
      returnEpisode: 0,
      returnChallengeEpisode: 0,
      teamSwapTargetRemaining: 0,
      teamSwapEpisode: 0,
      teamSwapReason: '',
      teamSwapOriginalCount: 0,
      rareDepartures: { quit: 0, medical: 0, disqualification: 0 },
      ineligibleReturnIds: [],
      enteredIds: [],
      returnedIds: [],
      nonEliminationCount: 0,
      nonEliminationTypes: []
    };
  }

  function makeTwistEvent({ stage = 'preChallenge', category = 'Production Twist', title, participants = [], text, effects = [], advantageImage = '', advantageLabel = '', teamRosters = [] }) {
    return {
      id: `twist-${stage}-${state.episodeNumber}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
      templateId: `dynamic-${String(title || 'twist').toLowerCase().replace(/[^a-z0-9]+/g, '-')}`,
      category,
      subcategory: 'Season Twist',
      title,
      participants: [...new Set(participants.filter(id => state.contestantById.has(id)))],
      allianceName: '',
      voteMeta: null,
      text,
      effects,
      stage,
      episode: state.episodeNumber,
      advantageImage,
      advantageLabel,
      teamRosters: (teamRosters || []).map(team => ({ name: team.name, members: [...(team.members || [])] }))
    };
  }

  function queueTwistEvent(stage, event) {
    if (!event) return;
    state.pendingStageEvents ||= { preChallenge: [], preVote: [] };
    state.pendingStageEvents[stage] ||= [];
    state.pendingStageEvents[stage].push(event);
  }

  function consumeTwistEvents(stage) {
    const events = [...(state.pendingStageEvents?.[stage] || [])];
    if (state.pendingStageEvents) state.pendingStageEvents[stage] = [];
    return events;
  }

  function initializeNewContestantConnections(id) {
    runtimeFor(id);
    const others = [...new Set([...state.activeIds, ...state.selectedIds])].filter(otherId => otherId !== id && state.contestantById.has(otherId));
    others.forEach(otherId => {
      const pairKey = relationshipKey(id, otherId);
      const seeded = Number(state.relationships.get(pairKey) ?? randomInteger(-2, 2));
      const relationship = clampRange(seeded, -10, 10);
      setDirectional(state.directionalRelationships, id, otherId, relationship, -10, 10);
      setDirectional(state.directionalRelationships, otherId, id, relationship, -10, 10);
      const trust = clampRange(45 + relationship * 4, 0, 100);
      const suspicion = clampRange(Math.max(0, -relationship * 5), 0, 100);
      [state.trust, state.suspicion, state.irritation, state.grudges, state.targetPriority, state.voteCommitment].forEach(map => {
        if (!(map instanceof Map)) return;
      });
      setDirectional(state.trust, id, otherId, trust, 0, 100);
      setDirectional(state.trust, otherId, id, trust, 0, 100);
      setDirectional(state.suspicion, id, otherId, suspicion, 0, 100);
      setDirectional(state.suspicion, otherId, id, suspicion, 0, 100);
      setDirectional(state.irritation, id, otherId, Math.max(0, -relationship * 3), 0, 100);
      setDirectional(state.irritation, otherId, id, Math.max(0, -relationship * 3), 0, 100);
      setDirectional(state.grudges, id, otherId, Math.max(0, -relationship * 2), 0, 100);
      setDirectional(state.grudges, otherId, id, Math.max(0, -relationship * 2), 0, 100);
      setDirectional(state.targetPriority, id, otherId, 0, 0, 100);
      setDirectional(state.targetPriority, otherId, id, 0, 0, 100);
      setDirectional(state.voteCommitment, id, otherId, 0, 0, 100);
      setDirectional(state.voteCommitment, otherId, id, 0, 0, 100);
    });
  }

  function smallestActiveTeam(excludedNames = []) {
    const excluded = new Set(excludedNames);
    const eligible = state.teams.filter(team => !excluded.has(team.name));
    if (!eligible.length) return null;
    const sizes = eligible.map(team => ({ team, size: team.members.filter(id => state.activeIds.includes(id)).length }));
    const minimum = Math.min(...sizes.map(entry => entry.size));
    const tied = sizes.filter(entry => entry.size === minimum);
    return tied[randomInteger(0, tied.length - 1)]?.team || eligible[0];
  }

  function addContestantToGame(id, source = 'arrival') {
    if (!id || !state.contestantById.has(id) || state.activeIds.includes(id)) return null;
    initializeNewContestantConnections(id);
    state.activeIds.push(id);
    let teamName = '';
    if (!state.merged) {
      const team = smallestActiveTeam();
      if (team) {
        if (!team.members.includes(id)) team.members.push(id);
        teamName = team.name;
      }
    }
    state.episodeOutcome.arrivals.push({ id, source, teamName });
    state.twistState?.enteredIds?.push(id);
    if (source.includes('return') && state.twistState && !state.twistState.returnedIds.includes(id)) state.twistState.returnedIds.push(id);
    return { id, teamName };
  }

  function removeContestantFromGame(id, reason, stage = 'challenge', detail = '') {
    if (!id || !state.activeIds.includes(id)) return null;
    if (state.idolState?.status === 'held' && state.idolState.holderId === id && reason !== 'vote') {
      state.idolState.status = 'expired';
      state.idolState.holderId = '';
    }
    applyAutomaticElimination(id);
    const departure = { id, reason, stage, detail };
    if (!(state.episodeOutcome.departures || []).some(item => item.id === id)) state.episodeOutcome.departures.push(departure);
    if (['medical', 'disqualification'].includes(reason) && state.twistState) {
      if (!state.twistState.ineligibleReturnIds.includes(id)) state.twistState.ineligibleReturnIds.push(id);
    }
    return departure;
  }

  function allPreviouslyEliminatedIds() {
    return [...new Set(state.episodes.flatMap(episodeEliminatedIds))]
      .filter(id => state.contestantById.has(id) && !state.activeIds.includes(id));
  }

  function eligibleReturneeIds() {
    const blocked = new Set([...(state.twistState?.ineligibleReturnIds || []), ...(state.twistState?.returnedIds || [])]);
    return allPreviouslyEliminatedIds().filter(id => !blocked.has(id));
  }

  function returneeAppealScore(id) {
    const profile = getProfile(id);
    const runtime = runtimeFor(id);
    return skillToTen(currentHidden(id, 'entertainment')) * 2.2
      + skillToTen(currentHidden(id, 'hostFavor')) * 1.5
      + runtime.socialVisibility * .12
      + runtime.strategicInfluence * .08
      + Math.random() * 12;
  }

  function chooseChrisReturnee() {
    const eligible = eligibleReturneeIds();
    return weightedChoice(eligible, id => Math.max(1, returneeAppealScore(id))) || null;
  }

  function chooseLateEntrantId() {
    const chosen = state.lateEntrantId;
    if (chosen && state.contestantById.has(chosen) && state.selectedIds.includes(chosen) && !state.activeIds.includes(chosen)) return chosen;
    const pool = state.selectedIds.filter(id => state.contestantById.has(id) && !state.activeIds.includes(id));
    return pool.length ? pool[randomInteger(0, pool.length - 1)] : '';
  }

  function canTriggerMajorTwist() {
    return state.episodeNumber - Number(state.twistState?.lastMajorEpisode ?? -10) >= 2;
  }

  function recordMajorTwist(key) {
    if (!state.twistState) return;
    if (key && Object.hasOwn(state.twistState.completed, key)) state.twistState.completed[key] = true;
    state.twistState.lastMajorEpisode = state.episodeNumber;
  }


  function schedulePlannedTeamSwap() {
    if (!state.twistState) return;
    state.twistState.teamSwapOriginalCount = state.teams.length;
    state.twistState.teamSwapTargetRemaining = 0;
    if (!seasonOptionEnabled('teamSwap')) return;
    const startingCount = state.activeIds.length;
    const mergeTarget = Number(elements.mergeAt?.value || 9);
    if (startingCount <= mergeTarget + 2) return;
    const midpoint = (startingCount + mergeTarget) / 2;
    const earliestRemaining = Math.max(mergeTarget + 2, Math.floor(midpoint) - 1);
    const latestRemaining = Math.min(startingCount - 2, Math.ceil(midpoint));
    if (latestRemaining < earliestRemaining) return;
    state.twistState.teamSwapTargetRemaining = randomInteger(earliestRemaining, latestRemaining);
  }

  function currentActiveTeamSizes() {
    return state.teams.map(team => team.members.filter(id => state.activeIds.includes(id)).length);
  }

  function teamSwapTriggerReason() {
    if (state.merged || state.twistState?.completed?.teamSwap || state.activeIds.length < 4) return '';
    const mergeTarget = Number(elements.mergeAt?.value || 9);
    if (state.activeIds.length <= mergeTarget) return '';
    const sizes = currentActiveTeamSizes();
    const smallest = sizes.length ? Math.min(...sizes) : 0;
    const mergeIsNotNextEpisode = state.activeIds.length > mergeTarget + 1;
    const forced = smallest <= 2 && mergeIsNotNextEpisode;
    const plannedTarget = Number(state.twistState?.teamSwapTargetRemaining || 0);
    const planned = seasonOptionEnabled('teamSwap') && plannedTarget > 0 && state.activeIds.length <= plannedTarget;
    if (forced) return 'forced-small-team';
    return planned ? 'planned' : '';
  }

  function chooseFreshTeamNames(count = 2) {
    const currentNames = new Set(state.teams.map(team => team.name));
    const neverUsed = TEAM_OPTIONS.filter(team => !state.usedTeamNames.includes(team.name) && !currentNames.has(team.name));
    const different = TEAM_OPTIONS.filter(team => !currentNames.has(team.name));
    const source = neverUsed.length >= count ? neverUsed : different.length >= count ? different : TEAM_OPTIONS;
    return shuffled(source).slice(0, count).map(team => team.name);
  }

  function applyRandomTeamSwap(reason) {
    const previousTeams = captureStatusSnapshot();
    const previousTeamById = new Map();
    previousTeams.forEach(team => team.members.forEach(id => previousTeamById.set(id, team.name)));
    const campers = shuffled(state.activeIds);
    const sizes = teamDistribution(campers.length, 2);
    const names = chooseFreshTeamNames(2);
    let cursor = 0;
    state.teams = sizes.map((size, index) => ({
      name: names[index] || TEAM_OPTIONS[index]?.name || `Team ${index + 1}`,
      members: campers.slice(cursor, cursor += size)
    }));
    state.teams.forEach(team => {
      if (!state.usedTeamNames.includes(team.name)) state.usedTeamNames.push(team.name);
      state.teamRuntime.set(team.name, { cohesion: 50, morale: 50 });
    });
    state.episodeOutcome.teamChanges = campers.map(id => ({
      id,
      fromTeam: previousTeamById.get(id) || '',
      toTeam: state.teams.find(team => team.members.includes(id))?.name || '',
      reason: reason === 'forced-small-team' ? 'automatic-team-swap' : 'planned-team-swap'
    }));
    recordMajorTwist('teamSwap');
    state.twistState.teamSwapEpisode = state.episodeNumber;
    state.twistState.teamSwapReason = reason;
    state.statusSnapshot = captureStatusSnapshot();
    if (!state.autoSimulating) state.sectionCheckpoints.episodeStart = captureRuntimeSnapshot();

    queueTwistEvent('preChallenge', makeTwistEvent({
      stage: 'preChallenge',
      category: 'Team Swap',
      title: 'Time for a Swap!',
      participants: [],
      text: 'Chris dissolves the current teams and randomly assigns every remaining camper into two new teams.',
      effects: [],
      teamRosters: state.teams
    }));
  }

  function maybeApplyTeamSwap() {
    const reason = teamSwapTriggerReason();
    if (!reason) return false;
    applyRandomTeamSwap(reason);
    return true;
  }

  function findIdolForContestant(id, stage, sourceText) {
    if (!id || !state.idolState || state.idolState.status !== 'hidden') return false;
    state.idolState.status = 'held';
    state.idolState.holderId = id;
    state.idolState.foundEpisode = state.episodeNumber;
    state.idolState.foundStage = stage;
    adjustSeasonHidden(id, 'idolHunting', .25);
    adjustSeasonHidden(id, 'twistAwareness', .15);
    adjustSeasonSkill(id, 'strategy', .05);
    queueTwistEvent(stage, makeTwistEvent({
      stage,
      category: 'Secret Advantage',
      title: 'Hidden Immunity Idol Found',
      participants: [id],
      text: `${contestantDisplayName(id)} ${sourceText} and secretly claims the only immunity idol in the game. It can be played after Chris names them as eliminated.`,
      effects: [`${contestantDisplayName(id)} secretly possesses the single-use immunity idol.`],
      advantageImage: 'images/idol.webp',
      advantageLabel: 'Hidden Immunity Idol'
    }));
    return true;
  }

  function resolvePendingExileReturn() {
    const exile = state.pendingExile;
    if (!exile?.id) return;
    const id = exile.id;
    const awareness = skillToTen(currentHidden(id, 'twistAwareness'));
    const awarenessShift = clampRange((awareness - 5.5) * .010, -.035, .035);
    const roll = Math.random();
    const idolThreshold = clampRange(.06 + awarenessShift * .45, .035, .085);
    const clueThreshold = clampRange(.31 + awarenessShift, .24, .38);
    const intelligenceThreshold = clampRange(.51 + awarenessShift * .50, .46, .56);
    let title = 'Back from Boney Island';
    let text = `${contestantDisplayName(id)} returns from exile exhausted, annoyed, and carrying absolutely nothing useful.`;
    let effects = [`${contestantDisplayName(id)} returns empty-handed.`];
    if (roll < idolThreshold && state.idolState?.status === 'hidden') {
      findIdolForContestant(id, 'preChallenge', 'finds the McLean-Brand Chris Head hidden beneath a pile of cursed driftwood');
      state.pendingExile = null;
      return;
    }
    if (roll < clueThreshold) {
      state.idolState.clues[id] = Number(state.idolState.clues[id] || 0) + 1;
      adjustSeasonHidden(id, 'idolHunting', .15);
      adjustSeasonHidden(id, 'twistAwareness', .12);
      title = 'A Suspiciously Useful Clue';
      text = `${contestantDisplayName(id)} returns from Boney Island with a clue pointing toward the hidden immunity idol.`;
      effects = [`${contestantDisplayName(id)} has a better chance of finding the idol later.`];
    } else if (roll < intelligenceThreshold) {
      adjustRuntime(id, 'strategicInfluence', 3);
      adjustSeasonSkill(id, 'strategy', .08);
      adjustSeasonHidden(id, 'twistAwareness', .10);
      title = 'Island Intelligence';
      text = `${contestantDisplayName(id)} overhears production chatter and returns with useful information about the next challenge.`;
      effects = [`${contestantDisplayName(id)} gains useful information.`];
    } else if (roll < .68) {
      adjustRuntime(id, 'fatigue', 12);
      adjustRuntime(id, 'health', -5);
      title = 'Boney Island Bites Back';
      text = `${contestantDisplayName(id)} returns scratched, sleep-deprived, and carrying a minor disadvantage into the next challenge.`;
      effects = [`${contestantDisplayName(id)} begins the episode tired and slightly injured.`];
    }
    queueTwistEvent('preChallenge', makeTwistEvent({ stage: 'preChallenge', category: 'Exile', title, participants: [id], text, effects }));
    state.pendingExile = null;
  }

  function maybeFindCampIdol(stage = 'preChallenge') {
    if (!seasonOptionEnabled('immunityIdol') || state.idolState?.status !== 'hidden') return;
    if (state.episodeNumber < 4 || state.episodeNumber > 14 || !state.activeIds.length) return;
    const candidates = state.activeIds.map(id => {
      const profile = getProfile(id);
      const clue = Number(state.idolState.clues?.[id] || 0);
      return { id, weight: Math.max(1, skillToTen(currentHidden(id, 'idolHunting')) * 1.6 + skillToTen(currentHidden(id, 'twistAwareness')) * .85 + skillToTen(currentSkill(id, 'intelligence')) + skillToTen(currentSkill(id, 'strategy')) + clue * 8) };
    });
    const finder = weightedChoice(candidates, item => item.weight)?.id;
    const bestWeight = Math.max(...candidates.map(item => item.weight), 1);
    const risingChance = .055 + Math.max(0, state.episodeNumber - 4) * .018 + Math.min(.12, bestWeight / 180);
    if (finder && Math.random() < risingChance) {
      findIdolForContestant(finder, stage, stage === 'preVote'
        ? 'slips away from the vote scramble, notices an oddly Chris-shaped rock, and searches beneath it'
        : 'spends free time searching around camp and discovers a suspiciously branded hiding place');
    }
  }

  function prepareEpisodeOpeningTwists({ mergeOpening = false } = {}) {
    expireNarrativeState();
    resolvePendingExileReturn();
    const completed = state.twistState?.completed || {};
    if (!state.episodeOutcome?.returnChallenge && seasonOptionEnabled('lateEntrant') && !completed.lateEntrant && state.episodeNumber >= 4 && (!state.merged || mergeOpening)) {
      const id = chooseLateEntrantId();
      if (id) {
        const arrival = addContestantToGame(id, 'late-entrant');
        recordMajorTwist('lateEntrant');
        queueTwistEvent('preChallenge', makeTwistEvent({
          stage: 'preChallenge', category: 'Late Entrant', title: 'A New Camper Has Arrived', participants: [id],
          text: `${contestantDisplayName(id)} arrives late with fresh clothes, no elimination trauma, and the confidence of someone who missed the worst part of camp. ${arrival?.teamName ? `Chris places them on ${arrival.teamName}.` : 'They enter directly into the individual game.'}`,
          effects: [`${contestantDisplayName(id)} officially joins the competition.`]
        }));
      }
    }

    const enoughRoom = state.activeIds.length > 6;
    if (seasonOptionEnabled('return') && !completed.return && state.episodeNumber >= 5 && enoughRoom && eligibleReturneeIds().length >= 3 && canTriggerMajorTwist()) {
      const id = chooseChrisReturnee();
      if (id) {
        const arrival = addContestantToGame(id, 'chris-return');
        recordMajorTwist('return');
        state.twistState.returnEpisode = state.episodeNumber;
        queueTwistEvent('preChallenge', makeTwistEvent({
          stage: 'preChallenge', category: 'Return', title: 'Chris Has Changed His Mind', participants: [id],
          text: `Chris announces that the season was getting boring and personally selects ${contestantDisplayName(id)} to return. ${arrival?.teamName ? `They rejoin the game on ${arrival.teamName}.` : 'They return as an individual contestant.'}`,
          effects: [`${contestantDisplayName(id)} returns to the competition.`]
        }));
      }
    }
    maybeFindCampIdol('preChallenge');
  }

  function chooseEpisodeStructuralTwist() {
    const completed = state.twistState?.completed || {};
    if (!canTriggerMajorTwist() || state.activeIds.length <= 6) return 'normal';
    const secondNonElimination = seasonOptionEnabled('nonElimination')
      && completed.nonElimination
      && Number(state.twistState.nonEliminationCount || 0) < 2
      && state.episodeNumber >= 8
      && Math.random() < .12;
    if (seasonOptionEnabled('nonElimination') && ((!completed.nonElimination && state.episodeNumber >= 5) || secondNonElimination)) {
      if (!completed.nonElimination) recordMajorTwist('nonElimination');
      else state.twistState.lastMajorEpisode = state.episodeNumber;
      state.twistState.nonEliminationCount = Number(state.twistState.nonEliminationCount || 0) + 1;
      const previousTypes = state.twistState.nonEliminationTypes || [];
      state.episodeOutcome.type = previousTypes.length && !state.merged
        ? (previousTypes.at(-1) === 'vote-off-team' ? 'fake-elimination' : 'vote-off-team')
        : (!state.merged && Math.random() < .42 ? 'vote-off-team' : 'fake-elimination');
      state.twistState.nonEliminationTypes = [...previousTypes, state.episodeOutcome.type];
      state.episodeOutcome.noElimination = true;
      state.episodeOutcome.voteOffTeam = state.episodeOutcome.type === 'vote-off-team';
      return state.episodeOutcome.type;
    }
    if (seasonOptionEnabled('challengeElimination') && !completed.challengeElimination && state.episodeNumber >= 6) {
      recordMajorTwist('challengeElimination');
      state.episodeOutcome.type = 'challenge-elimination';
      queueTwistEvent('preChallenge', makeTwistEvent({
        stage: 'preChallenge', category: 'Challenge Elimination', title: 'Last Place Is Going Home', participants: [],
        text: 'Chris announces that the lowest-performing contestant will be eliminated by the challenge itself. There will be no regular vote.',
        effects: ['The challenge loser will receive an immediate ELIMINATED result.']
      }));
      return state.episodeOutcome.type;
    }
    if (seasonOptionEnabled('doubleElimination') && !completed.doubleElimination && state.episodeNumber >= 7 && state.merged) {
      recordMajorTwist('doubleElimination');
      state.episodeOutcome.type = 'double-elimination';
      state.episodeOutcome.doubleElimination = true;
      queueTwistEvent('preChallenge', makeTwistEvent({
        stage: 'preChallenge', category: 'Production Twist', title: 'Two Campers Will Leave', participants: [],
        text: 'Chris reveals that tonight is a double elimination. A genuine two-way voting tie will eliminate both tied contestants; otherwise every voter must name two different targets.',
        effects: ['Two contestants must leave this episode.']
      }));
      return state.episodeOutcome.type;
    }
    return 'normal';
  }

  function chooseWorstChallengeContestant() {
    const result = state.challengeResult;
    if (!result) return '';
    if (result.merged) return result.rankedIds?.at(-1) || '';
    const losing = state.teams.find(team => team.name === result.loser);
    const ids = (losing?.members || []).filter(id => state.activeIds.includes(id));
    return ids.sort((first, second) => Number(result.performances?.[first] || 0) - Number(result.performances?.[second] || 0))[0] || '';
  }

  function chooseRareDepartureCandidate(kind) {
    const result = state.challengeResult;
    const pool = [...state.activeIds];
    if (!pool.length) return '';
    return weightedChoice(pool, id => {
      const profile = getProfile(id);
      const runtime = runtimeFor(id);
      const detail = result?.performanceDetails?.[id];
      const poor = detail ? Math.max(0, 60 - Number(detail.normalized || 50)) : 0;
      const hidden = effectiveHiddenFor(id);
      if (kind === 'medical') {
        const injuryRisk = skillToTen(hidden.injuryRisk);
        const injuryResistance = skillToTen(hidden.injuryResistance);
        return Math.max(1,
          (100 - runtime.health) * 1.5
          + runtime.fatigue * .7
          + injuryRisk * 5.2
          + (11 - injuryResistance) * 4.3
          + poor * 1.2
        );
      }
      if (kind === 'disqualification') {
        return Math.max(1,
          skillToTen(hidden.ruleBreaking) * 5.6
          + skillToTen(hidden.sabotage) * 3.8
          + skillToTen(hidden.authorityResistance) * 3.4
          + skillToTen(currentSkill(id, 'aggression')) * 2.2
          + getDirectional(state.irritation, id, state.challengeResult?.winner || '', 0)
        );
      }
      return Math.max(1,
        runtime.quitRisk * 1.3
        + runtime.emotionalPressure
        + runtime.isolation * .8
        + (100 - runtime.morale)
        + (11 - skillToTen(currentSkill(id, 'loyalty'))) * 4
        + (11 - skillToTen(hidden.motivation)) * 4.5
        + (11 - skillToTen(hidden.pressureResistance)) * 2.5
        + skillToTen(hidden.quitRisk) * 2.2
      );
    }) || '';
  }

  function setSpecialDeparture(reason, id, detail, stage = 'challenge') {
    if (!id || !state.activeIds.includes(id)) return null;
    const departure = removeContestantFromGame(id, reason, stage, detail);
    if (!departure) return null;

    state.episodeOutcome.type = reason;
    state.episodeOutcome.cancelVote = true;
    state.automaticEliminatedId = id;

    const labels = {
      'challenge-elimination': ['Challenge Elimination', 'Last Place Means Last Place', `${contestantDisplayName(id)} finishes last and is eliminated immediately by the challenge rules.`],
      medical: ['Medical Removal', 'Production Calls It', `${contestantDisplayName(id)} is ruled medically unable to continue after the challenge.`],
      disqualification: ['Disqualification', 'Chris Stops the Game', `${contestantDisplayName(id)} is removed for breaking the rules badly enough that even this show has standards.`],
      quit: ['Quit', 'I Am Done!', `${contestantDisplayName(id)} voluntarily withdraws from the competition and the scheduled vote is cancelled.`]
    };
    const [category, title, text] = labels[reason] || ['Departure', 'Contestant Leaves', detail];
    if (reason !== 'medical') {
      queueTwistEvent('preVote', makeTwistEvent({ stage: 'preVote', category, title, participants: [id], text, effects: [detail] }));
    }
    return departure;
  }

  function buildExileVote(winningTeam, losingTeam, candidates) {
    const voters = (winningTeam?.members || []).filter(id => state.activeIds.includes(id));
    const ballots = voters.map(voterId => {
      const targetId = weightedChoice(candidates, candidateId => {
        const threat = strategicThreat(candidateId, candidates) * 1.15;
        const hostility = Math.max(0, -currentRelationship(voterId, candidateId)) * 6;
        const suspicion = getDirectional(state.suspicion, voterId, candidateId) * .32;
        const protection = Math.max(0, currentRelationship(voterId, candidateId)) * -1.6;
        return Math.max(1, threat + hostility + suspicion + protection + Math.random() * 20);
      });
      return targetId ? { voterId, targetId } : null;
    }).filter(Boolean);
    const tally = tallyBallots(ballots, candidates);
    const highest = Math.max(...Object.values(tally).map(Number), 0);
    const tiedIds = Object.entries(tally).filter(([, count]) => Number(count) === highest).map(([id]) => id);
    const id = tiedIds.length ? tiedIds[randomInteger(0, tiedIds.length - 1)] : candidates[0] || '';
    return { id, voters, ballots, tally, tiedIds, votesShown: false };
  }

  function resolveAfterChallengeTwists() {
    if (!state.challengeResult || state.episodeType === 'finale-race' || state.episodeType === 'final-four-showdown' || state.episodeType === 'return-challenge') return;
    if (state.episodeOutcome.type === 'challenge-elimination') {
      const id = chooseWorstChallengeContestant();
      setSpecialDeparture('challenge-elimination', id, `${contestantDisplayName(id)} was eliminated by finishing last in the challenge.`);
      return;
    }

    if (state.episodeOutcome.type === 'normal') {
      const challenge = currentChallengeData();
      const dangerous = challenge?.volatility === 'chaotic';
      if (seasonOptionEnabled('medicalRemovals') && state.twistState.rareDepartures.medical < 1 && Math.random() < (dangerous ? .045 : .012)) {
        const id = chooseRareDepartureCandidate('medical');
        if (id) {
          state.twistState.rareDepartures.medical += 1;
          setSpecialDeparture('medical', id, `${contestantDisplayName(id)} suffers a serious injury after a dangerous challenge failure and cannot continue.`);
          if (Math.random() < .07 && state.activeIds.length > 7) {
            const secondId = chooseRareDepartureCandidate('medical');
            if (secondId && secondId !== id) setSpecialDeparture('medical', secondId, `${contestantDisplayName(secondId)} is also removed after production discovers a second serious injury.`);
          }
          return;
        }
      }
      if (seasonOptionEnabled('disqualifications') && state.twistState.rareDepartures.disqualification < 1 && Math.random() < .016) {
        const id = chooseRareDepartureCandidate('disqualification');
        if (id) {
          state.twistState.rareDepartures.disqualification += 1;
          const reasons = [
            'is caught deliberately breaking an announced challenge rule',
            'destroys an important piece of production equipment during a sabotage attempt',
            'refuses a mandatory safety instruction and interferes with filming',
            'is caught cheating so blatantly that Chris cannot edit around it',
            'endangers the cast and crew while confronting the host'
          ];
          const reason = reasons[randomInteger(0, reasons.length - 1)];
          setSpecialDeparture('disqualification', id, `${contestantDisplayName(id)} ${reason} and is immediately disqualified.`);
          return;
        }
      }
      if (seasonOptionEnabled('quits') && state.twistState.rareDepartures.quit < 1) {
        const id = chooseRareDepartureCandidate('quit');
        const runtime = id ? runtimeFor(id) : null;
        const quitChance = runtime ? clampRange((runtime.quitRisk + runtime.emotionalPressure + runtime.isolation - runtime.morale) / 1450, .003, .055) : 0;
        if (id && Math.random() < quitChance) {
          state.twistState.rareDepartures.quit += 1;
          setSpecialDeparture('quit', id, `${contestantDisplayName(id)} quits and becomes the episode's departure.`);
          return;
        }
      }
    }

    if (seasonOptionEnabled('exile') && !state.merged && !state.episodeOutcome.cancelVote && state.challengeResult.loser) {
      const losing = state.teams.find(team => team.name === state.challengeResult.loser);
      const winningName = (state.challengeResult.winners || [state.challengeResult.winner]).filter(Boolean)[0] || '';
      const winning = state.teams.find(team => team.name === winningName);
      const previousEpisode = [...state.episodes]
        .sort((first, second) => Number(second.number || 0) - Number(first.number || 0))[0];
      const previousExileId = Number(previousEpisode?.number || 0) === state.episodeNumber - 1
        ? (previousEpisode?.episodeOutcome?.exile?.id || previousEpisode?.exiledIds?.[0] || '')
        : '';
      const allCandidates = (losing?.members || []).filter(id => state.activeIds.includes(id));
      const candidates = allCandidates.filter(id => id !== previousExileId);
      const exileVote = buildExileVote(winning, losing, candidates);
      if (exileVote.id) {
        state.episodeOutcome.exile = {
          ...exileVote,
          selectedBy: winningName || 'the winning team',
          fromTeam: losing?.name || state.challengeResult.loser
        };
        state.pendingExile = { id: exileVote.id, episode: state.episodeNumber, selectedBy: winningName || 'the winning team' };
      }
    }
    maybeFindCampIdol('preVote');
  }

  function syntheticDepartureVoteResult() {
    const departure = state.episodeOutcome.departures[0];
    if (!departure) return null;
    const pool = [...(state.challengeResult?.merged ? state.activeIds : (state.teams.find(team => team.name === state.challengeResult?.loser)?.members || []))];
    return {
      losingTeamName: state.challengeResult?.merged ? state.mergedTeamName : state.challengeResult?.loser,
      eligibleTargets: [], pool, ballots: [], tally: {}, tiedIds: [], hadInitialTie: false, revote: null,
      eliminatedId: departure.id, eliminatedIds: [departure.id], safeOrder: [], soleVote: false,
      tieShown: false, revoteSafeRevealed: false, eliminationRevealed: false, votesShown: false,
      ceremonyStarted: false, autoRevealActive: false, effectsApplied: true,
      specialDeparture: true, departureReason: departure.reason,
      sendoff: departure.detail || randomSendoff(contestantDisplayName(departure.id))
    };
  }

  function applyIdolToVoteResult(result) {
    const holderId = state.idolState?.status === 'held' ? state.idolState.holderId : '';
    const provisionalIds = result?.eliminatedIds?.length ? result.eliminatedIds : [result?.eliminatedId].filter(Boolean);
    if (!holderId || !result || !provisionalIds.includes(holderId)) return result;

    result.ballots.forEach(ballot => {
      const targetIds = Array.isArray(ballot.targetIds) ? ballot.targetIds : [ballot.targetId].filter(Boolean);
      if (targetIds.includes(holderId)) {
        ballot.cancelledTargetIds = [...new Set([...(ballot.cancelledTargetIds || []), holderId])];
      }
    });

    const eligibleAfterIdol = result.eligibleTargets.filter(id => id !== holderId);
    const tally = tallyBallots(result.ballots, eligibleAfterIdol);
    const validTiedIds = idsWithHighestVotes(tally);
    let revote = null;
    let eliminatedIds = [];

    if (result.doubleElimination) {
      eliminatedIds = Object.entries(tally)
        .sort((first, second) => Number(second[1]) - Number(first[1]) || Math.random() - .5)
        .slice(0, Math.min(2, eligibleAfterIdol.length))
        .map(([id]) => id);
    } else if (validTiedIds.length > 1) {
      revote = buildRevote(validTiedIds, result.pool, result.ballots);
      eliminatedIds = [revote.eliminatedId];
    } else {
      eliminatedIds = [validTiedIds[0] || eligibleAfterIdol[0]].filter(Boolean);
    }
    if (!eliminatedIds.length) return result;

    result.originalEliminatedId = holderId;
    result.originalSendoff = result.sendoff;
    result.tallyAfterIdol = tally;
    result.tiedIds = [...validTiedIds];
    result.hadInitialTie = !result.doubleElimination && validTiedIds.length > 1;
    result.revote = revote;
    result.idolRevote = null;
    result.eliminatedId = eliminatedIds[0];
    result.eliminatedIds = eliminatedIds;
    result.sendoff = result.hadInitialTie && revote?.tieBroken
      ? `The idol cancelled the deciding votes, the revote tied again, and Chris randomly selected ${contestantDisplayName(result.eliminatedId)} for elimination.`
      : randomSendoff(contestantDisplayName(result.eliminatedId));
    result.idolPlay = {
      holderId,
      cancelledVotes: result.ballots.reduce((total, ballot) => total + (ballot.cancelledTargetIds || []).filter(id => id === holderId).length, 0),
      replacementId: result.eliminatedId,
      replacementIds: [...result.eliminatedIds],
      requiredRevote: Boolean(revote)
    };
    result.safeOrder = suspenseSafeOrder(result.pool, result.eliminatedIds, tally).filter(id => id !== holderId);
    state.episodeOutcome.idolPlay = cloneEpisodeValue(result.idolPlay);
    state.idolState.status = 'played';
    state.idolState.playedEpisode = state.episodeNumber;
    state.idolState.holderId = '';
    return result;
  }

  function finalizePostVoteTwists(result) {
    if (!result || result.specialDeparture) return result;
    if (state.episodeOutcome.noElimination) {
      result.noElimination = true;
      result.teamSwitch = state.episodeOutcome.voteOffTeam;
      result.apparentEliminatedId = result.eliminatedId;
      result.apparentSendoff = result.sendoff;
      result.twistSendoff = state.episodeOutcome.voteOffTeam
        ? `${contestantDisplayName(result.eliminatedId)}, surprise! You are not leaving. You have been voted off your team and onto somebody else's problem.`
        : `${contestantDisplayName(result.eliminatedId)}, you are actually safe. Nobody is leaving tonight! That entire ceremony was real, emotional, and completely pointless.`;
      return result;
    }
    return applyIdolToVoteResult(result);
  }

  function updateSetup() {
    const cast = castLimit();
    if (elements.participantCountValue) elements.participantCountValue.value = String(cast);
    if (elements.slotCount) elements.slotCount.textContent = String(cast);
    if (elements.mergeAt) {
      const maxMerge = cast - 2;
      elements.mergeAt.max = String(maxMerge);
      if (Number(elements.mergeAt.value) > maxMerge) elements.mergeAt.value = String(maxMerge);
      if (Number(elements.mergeAt.value) < 6) elements.mergeAt.value = '6';
      const merge = Number(elements.mergeAt.value);
      if (elements.mergeAtValue) elements.mergeAtValue.value = String(merge);
      const low = Math.max(6, Math.round(cast * .5));
      const high = Math.min(maxMerge, Math.round(cast * .62));
      if (elements.mergeHelp) elements.mergeHelp.textContent = `Recommended for a ${cast}-person cast: ${low}–${high}.`;
      const lateEnabled = lateEntrantOptionEnabled();
      const startingCount = Math.max(0, cast - (lateEnabled ? 1 : 0));
      const distribution = teamDistribution(startingCount, teamCount());
      const teamText = distribution.every(value => value === distribution[0])
        ? `${teamCount()} teams of ${distribution[0]}`
        : `${teamCount()} teams (${distribution.join(' / ')})`;
      if (elements.seasonPreviewTitle) elements.seasonPreviewTitle.textContent = lateEnabled
        ? `${cast} contestants · ${teamText} + 1 late entrant`
        : `${cast} contestants · ${teamText}`;
      if (elements.seasonPreviewDetail) {
        const late = document.querySelector('[data-season-option="lateEntrant"]')?.checked ? ' · Late entrant enabled' : '';
        elements.seasonPreviewDetail.textContent = `Merge at ${merge} · ${finaleLabel()}${late}`;
      }
    }
    while (state.selectedIds.length > cast) state.selectedIds.pop();
    renderRoster();
    renderSelectedCast();
    refreshLateEntrantPicker();
  }

  function showScreen(targetId) {
    const target = document.getElementById(targetId);
    if (!target) return;
    activeScreenId = targetId;
    elements.screens.forEach(screen => screen.classList.toggle('is-active', screen === target));
    if (targetId === 'participants-screen') {
      renderRoster();
      renderSelectedCast();
    }
    if (targetId === 'statistics-screen') renderStatistics();
    scheduleSimulatorPersistence();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  function resetSetup() {
    const name = document.getElementById('simulationName');
    if (name) name.value = 'Camp Wawanakwa';
    elements.participantCount.value = '16';
    elements.mergeAt.value = '9';
    const twoTeams = document.querySelector('input[name="teamCount"][value="2"]');
    if (twoTeams) twoTeams.checked = true;
    elements.endingFormat.value = 'final-two-race';
    document.querySelectorAll('#setup-screen input[type="checkbox"]').forEach(input => { input.checked = false; });
    if (elements.lateEntrantSelect) elements.lateEntrantSelect.value = '';
    state.lateEntrantId = '';
    updateSetup();
  }

  function createCheckboxOption(label, checked, onChange, className = 'dropdown-option') {
    const option = document.createElement('label');
    option.className = className;
    const input = document.createElement('input');
    input.type = 'checkbox';
    input.checked = checked;
    input.addEventListener('change', onChange);
    const text = document.createElement('span');
    text.textContent = label;
    option.append(input, text);
    return option;
  }

  function renderShowChecklist() {
    if (!elements.showChecklist) return;
    elements.showChecklist.replaceChildren();
    elements.showChecklist.append(createCheckboxOption('All Shows', state.selectedShows.size === 0, event => {
      if (event.target.checked) {
        state.selectedShows.clear();
        state.selectedSeasons.clear();
        renderAllFilters();
      } else if (state.selectedShows.size === 0) event.target.checked = true;
    }, 'dropdown-all-option'));
    sortedShows().forEach(show => {
      elements.showChecklist.append(createCheckboxOption(show, state.selectedShows.has(show), event => {
        if (event.target.checked) state.selectedShows.add(show);
        else state.selectedShows.delete(show);
        pruneSeasonSelection();
        renderAllFilters();
      }));
    });
  }

  function validSeasonKeys() {
    const valid = new Set();
    state.selectedShows.forEach(show => seasonsForShow(show).forEach(season => valid.add(seasonKey(show, season))));
    return valid;
  }

  function pruneSeasonSelection() {
    const valid = validSeasonKeys();
    [...state.selectedSeasons].forEach(key => { if (!valid.has(key)) state.selectedSeasons.delete(key); });
  }

  function renderSeasonChecklist() {
    if (!elements.seasonChecklist) return;
    elements.seasonChecklist.replaceChildren();
    if (state.selectedShows.size === 0) {
      const note = document.createElement('p');
      note.className = 'season-empty-note';
      note.textContent = 'Choose one or more shows to see their seasons.';
      elements.seasonChecklist.append(note);
      elements.seasonDropdown?.classList.add('is-disabled');
      return;
    }
    elements.seasonDropdown?.classList.remove('is-disabled');
    elements.seasonChecklist.append(createCheckboxOption('All Seasons', state.selectedSeasons.size === 0, event => {
      if (event.target.checked) {
        state.selectedSeasons.clear();
        renderAllFilters();
      } else if (state.selectedSeasons.size === 0) event.target.checked = true;
    }, 'dropdown-all-option'));
    [...state.selectedShows].sort((a, b) => showPriority(a) - showPriority(b) || naturalCompare(a, b)).forEach(show => {
      const group = document.createElement('section');
      group.className = 'season-group';
      const title = document.createElement('div');
      title.className = 'season-group-title';
      title.textContent = show;
      group.append(title);
      seasonsForShow(show).forEach(season => {
        const key = seasonKey(show, season);
        group.append(createCheckboxOption(`Season ${season}`, state.selectedSeasons.has(key), event => {
          if (event.target.checked) state.selectedSeasons.add(key);
          else state.selectedSeasons.delete(key);
          renderAllFilters();
        }));
      });
      elements.seasonChecklist.append(group);
    });
  }

  function updateFilterLabels() {
    if (elements.showFilterLabel) {
      elements.showFilterLabel.textContent = state.selectedShows.size === 0
        ? 'All Shows'
        : state.selectedShows.size === 1 ? [...state.selectedShows][0] : `${state.selectedShows.size} Shows Selected`;
    }
    if (elements.seasonFilterLabel) {
      elements.seasonFilterLabel.textContent = state.selectedShows.size === 0
        ? 'Choose a show first'
        : state.selectedSeasons.size === 0 ? 'All Seasons' : `${state.selectedSeasons.size} Season${state.selectedSeasons.size === 1 ? '' : 's'} Selected`;
    }
  }

  function renderAllFilters() {
    renderShowChecklist();
    renderSeasonChecklist();
    updateFilterLabels();
    renderRoster();
  }

  function contestantMatchesFilters(contestant) {
    const shows = contestant.shows || [];
    if (state.selectedShows.size && !shows.some(show => state.selectedShows.has(show))) return false;
    if (state.selectedSeasons.size) {
      const match = [...state.selectedSeasons].some(key => {
        const [show, season] = splitSeasonKey(key);
        return (contestant.seasonsByShow?.[show] || []).map(String).includes(season);
      });
      if (!match) return false;
    }
    const query = String(elements.participantSearch?.value || '').trim().toLowerCase();
    if (!query) return true;
    return [contestant.fullName, contestant.nickname].filter(Boolean).some(value => String(value).toLowerCase().includes(query));
  }

  function filteredContestants() {
    return state.contestants.filter(contestantMatchesFilters).sort((a, b) =>
      naturalCompare(a.fullName || a.nickname, b.fullName || b.nickname) || naturalCompare(a.nickname, b.nickname));
  }

  function renderRoster() {
    if (!elements.rosterGrid) return;
    const contestants = filteredContestants();
    if (elements.availableCount) elements.availableCount.textContent = String(contestants.length);
    elements.rosterGrid.replaceChildren();
    if (!state.contestants.length) {
      const message = document.createElement('div');
      message.className = 'contestant-list-empty';
      message.textContent = 'Cast data could not be loaded. Make sure cast_data.js is in the parent folder.';
      elements.rosterGrid.append(message);
      return;
    }
    if (!contestants.length) {
      const message = document.createElement('div');
      message.className = 'contestant-list-empty';
      message.textContent = 'No contestants match these filters.';
      elements.rosterGrid.append(message);
      return;
    }
    const selected = new Set(state.selectedIds);
    const fragment = document.createDocumentFragment();
    contestants.forEach(contestant => {
      const row = document.createElement('button');
      row.type = 'button';
      row.className = `contestant-name-row${selected.has(contestant.id) ? ' is-selected' : ''}`;
      row.textContent = contestant.fullName || contestant.nickname || 'Unnamed Contestant';
      row.title = contestant.nickname && contestant.nickname !== contestant.fullName ? `Nickname: ${contestant.nickname}` : row.textContent;
      row.setAttribute('role', 'option');
      row.setAttribute('aria-selected', selected.has(contestant.id) ? 'true' : 'false');
      row.addEventListener('click', () => addContestant(contestant.id));
      fragment.append(row);
    });
    elements.rosterGrid.append(fragment);
  }

  function addContestant(id) {
    if (state.selectedIds.includes(id)) return;
    if (state.selectedIds.length >= castLimit()) {
      showToast(`Your cast already has ${castLimit()} contestants.`);
      return;
    }
    if (!state.contestantById.has(id)) return;
    state.selectedIds.push(id);
    getProfile(id);
    renderRoster();
    renderSelectedCast();
  }

  function removeContestant(id) {
    state.selectedIds = state.selectedIds.filter(value => value !== id);
    renderRoster();
    renderSelectedCast();
  }

  function clearCast() {
    state.selectedIds = [];
    renderRoster();
    renderSelectedCast();
  }

  function resetSimulationData() {
    state.activeEditId = null;
    state.teams = [];
    state.teamSetupSignature = '';
    state.activeIds = [];
    state.directionalRelationships = new Map();
    state.trust = new Map();
    state.suspicion = new Map();
    state.irritation = new Map();
    state.grudges = new Map();
    state.targetPriority = new Map();
    state.voteCommitment = new Map();
    state.votePlans = new Map();
    state.voteLandscape = null;
    state.contestantRuntime = new Map();
    state.teamRuntime = new Map();
    state.alliances = [];
    state.usedAllianceNames = [];
    state.eventHistory = [];
    state.episodeEvents = { preChallenge: [], preVote: [] };
    state.eventSnapshots = { preChallenge: null, preVote: null };
    state.sectionCheckpoints = { episodeStart: null, afterPreChallenge: null, afterChallenge: null, afterPreVote: null, afterVote: null };
    state.challengeSnapshot = null;
    state.currentChallenge = null;
    state.usedChallengeIds = [];
    state.usedIndividualChallengeIds = [];
    state.challengeResult = null;
    state.challengeRevealed = false;
    state.voteResult = null;
    state.voteRevealIndex = 0;
    state.voteCeremonyFinished = false;
    state.episodeNumber = 1;
    state.merged = false;
    state.mergedTeamName = '';
    state.usedTeamNames = [];
    state.statusSnapshot = [];
    state.episodes = [];
    state.currentEpisodeIndex = 0;
    state.isHistoricalView = false;
    state.liveMergeState = null;
    state.autoSimulating = false;
    state.seasonStarted = false;
    state.finaleFormat = selectedFinaleFormat();
    state.episodeType = 'regular';
    state.mergeOpening = false;
    state.automaticEliminatedId = '';
    state.juryResult = null;
    state.juryRevealIndex = 0;
    state.juryRevealActive = false;
    state.juryRevealed = false;
    state.returnChallengeRevealed = false;
    state.seasonWinnerId = '';
    state.seasonComplete = false;
    state.finalPlacements = [];
    state.seasonOptions = {};
    state.lateEntrantId = elements.lateEntrantSelect?.value || '';
    state.twistState = null;
    state.episodeOutcome = createEmptyEpisodeOutcome();
    state.pendingStageEvents = { preChallenge: [], preVote: [] };
    state.pendingExile = null;
    state.idolState = null;
  }

  function resetContestantConfiguration({ clearSelected = false } = {}) {
    document.querySelectorAll('dialog[open]').forEach(dialog => closeDialog(dialog));
    closeRelationshipMenu();
    state.profilesById = new Map();
    state.relationships = new Map();
    state.relationshipControls = new Map();
    resetSimulationData();
    if (clearSelected) state.selectedIds = [];
    renderRoster();
    renderSelectedCast();
    updateSetup();
    showScreen('participants-screen');
  }

  function resetSeasonToCast() {
    resetContestantConfiguration({ clearSelected: false });
    showToast('Season reset. Contestant skills, relationships, and season history were cleared.');
  }

  function resetCastAndConfiguration() {
    resetContestantConfiguration({ clearSelected: true });
    showToast('Cast, skills, relationships, and season history were cleared.');
  }

  function shuffled(values) {
    const copy = [...values];
    for (let index = copy.length - 1; index > 0; index -= 1) {
      const swap = Math.floor(Math.random() * (index + 1));
      [copy[index], copy[swap]] = [copy[swap], copy[index]];
    }
    return copy;
  }

  function randomizeCast() {
    const pool = filteredContestants();
    if (!pool.length) return showToast('No contestants match the current filters.');
    const picked = shuffled(pool).slice(0, castLimit());
    state.selectedIds = picked.map(contestant => contestant.id);
    state.selectedIds.forEach(getProfile);
    renderRoster();
    renderSelectedCast();
    if (picked.length < castLimit()) showToast(`Only ${picked.length} matching contestants were available.`);
    else showToast('Cast randomized.');
  }

  function normalizedGenderGroup(contestant) {
    const value = String(contestant?.gender ?? contestant?.sex ?? '').trim().toLowerCase();
    if (['male', 'man', 'm', 'boy', 'masculine'].includes(value)) return 'male';
    if (['female', 'woman', 'f', 'girl', 'feminine'].includes(value)) return 'female';
    return 'other';
  }

  function balancedGenderCounts(pool, requestedCount) {
    const available = { male: 0, female: 0, other: 0 };
    pool.forEach(contestant => { available[normalizedGenderGroup(contestant)] += 1; });
    const count = Math.min(requestedCount, pool.length);
    const candidates = [];
    for (let male = 0; male <= Math.min(count, available.male); male += 1) {
      for (let female = 0; female <= Math.min(count - male, available.female); female += 1) {
        const other = count - male - female;
        if (other < 0 || other > available.other) continue;
        candidates.push({
          male, female, other,
          score: (other * 1000) + Math.abs(male - female)
        });
      }
    }
    if (!candidates.length) return { male: 0, female: 0, other: count };
    const bestScore = Math.min(...candidates.map(candidate => candidate.score));
    return shuffled(candidates.filter(candidate => candidate.score === bestScore))[0];
  }

  function genderSelectionSummary(ids) {
    const counts = { male: 0, female: 0, other: 0 };
    ids.forEach(id => {
      const contestant = state.contestantById.get(id);
      if (contestant) counts[normalizedGenderGroup(contestant)] += 1;
    });
    const parts = [`${counts.male} male`, `${counts.female} female`];
    if (counts.other) parts.push(`${counts.other} other/unspecified`);
    return parts.join(', ');
  }

  function randomizeEvenGenderCast() {
    const pool = filteredContestants();
    if (!pool.length) return showToast('No contestants match the current filters.');
    const requested = castLimit();
    const target = balancedGenderCounts(pool, requested);
    const groups = { male: [], female: [], other: [] };
    pool.forEach(contestant => groups[normalizedGenderGroup(contestant)].push(contestant));
    const picked = [
      ...shuffled(groups.male).slice(0, target.male),
      ...shuffled(groups.female).slice(0, target.female),
      ...shuffled(groups.other).slice(0, target.other)
    ];
    state.selectedIds = shuffled(picked).map(contestant => contestant.id);
    state.selectedIds.forEach(getProfile);
    renderRoster();
    renderSelectedCast();
    if (picked.length < requested) {
      showToast(`Only ${picked.length} matching contestants were available.`);
    } else {
      showToast(`Even-gender cast randomized: ${genderSelectionSummary(state.selectedIds)}.`);
    }
  }

  function addRandomContestant() {
    const available = filteredContestants().filter(contestant => !state.selectedIds.includes(contestant.id));
    if (!available.length) return showToast('No unselected contestants match the current filters.');
    addContestant(available[Math.floor(Math.random() * available.length)].id);
  }

  function setImageWithFallback(img, contestant) {
    const source = String(contestant.image || '').trim();
    const raw = /^(?:https?:|data:|blob:)/i.test(source)
      ? source
      : source.replace(/\.png(?=([?#]|$))/i, '.webp');
    const candidates = [];
    if (/^(?:https?:|data:|blob:|\/)/i.test(raw)) candidates.push(raw);
    else if (raw) {
      if (raw.startsWith('../')) candidates.push(raw, raw.replace(/^\.\.\//, ''));
      else candidates.push(`../${raw}`, raw);
    }
    candidates.push(createPlaceholderImage(contestant.nickname || contestant.fullName || '?'));
    let index = 0;
    img.onerror = () => {
      index += 1;
      if (index < candidates.length) img.src = candidates[index];
      else img.onerror = null;
    };
    img.src = candidates[0];
  }

  function createPlaceholderImage(name) {
    const initials = String(name).split(/\s+/).slice(0, 2).map(part => part[0] || '').join('').toUpperCase() || '?';
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 120"><rect width="120" height="120" rx="22" fill="#f3d6a5"/><circle cx="60" cy="45" r="24" fill="#d56b3d"/><path d="M21 111c4-27 18-41 39-41s35 14 39 41" fill="#3f624b"/><text x="60" y="52" text-anchor="middle" font-family="Arial,sans-serif" font-size="20" font-weight="700" fill="#fffaf0">${initials}</text></svg>`;
    return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
  }

  function renderSelectedCast() {
    if (!elements.selectedGrid) return;
    elements.selectedGrid.replaceChildren();
    if (!state.selectedIds.length) {
      const empty = document.createElement('div');
      empty.className = 'cast-empty-state';
      empty.innerHTML = '<strong>Your camp is empty</strong><p>Choose contestants from the list. Their portraits and edit controls will appear here.</p>';
      elements.selectedGrid.append(empty);
      updateCastCount();
      refreshLateEntrantPicker();
      return;
    }
    const fragment = document.createDocumentFragment();
    state.selectedIds.forEach(id => {
      const contestant = state.contestantById.get(id);
      if (!contestant) return;
      const card = document.createElement('article');
      card.className = 'selected-contestant-card';
      const image = document.createElement('img');
      image.className = 'selected-contestant-image';
      image.alt = contestant.nickname || contestant.fullName || 'Contestant';
      setImageWithFallback(image, contestant);
      const name = document.createElement('strong');
      name.className = 'selected-contestant-name';
      name.textContent = contestant.nickname || contestant.fullName || 'Unnamed';
      name.title = contestant.fullName || name.textContent;
      const actions = document.createElement('div');
      actions.className = 'selected-card-actions';
      const edit = document.createElement('button');
      edit.type = 'button';
      edit.className = 'card-action-btn edit-btn';
      edit.textContent = 'Edit';
      edit.addEventListener('click', () => contestant.isCustom ? openCustomContestantDialog(id) : openEditDialog(id));
      const remove = document.createElement('button');
      remove.type = 'button';
      remove.className = 'card-action-btn remove-btn';
      remove.textContent = 'Remove';
      remove.addEventListener('click', () => removeContestant(id));
      actions.append(edit, remove);
      card.append(image, name, actions);
      fragment.append(card);
    });
    elements.selectedGrid.append(fragment);
    updateCastCount();
    refreshLateEntrantPicker();
  }

  function updateCastCount() {
    const selected = state.selectedIds.length;
    const limit = castLimit();
    if (elements.selectedCount) elements.selectedCount.textContent = String(selected);
    if (elements.slotCount) elements.slotCount.textContent = String(limit);
    elements.castCountChip?.classList.toggle('is-complete', selected === limit);
    elements.castCountChip?.classList.toggle('is-over', selected > limit);
    if (elements.startSeasonBtn) {
      elements.startSeasonBtn.disabled = selected !== limit;
      elements.startSeasonBtn.title = selected !== limit ? `Select exactly ${limit} contestants to start.` : '';
    }
    if (elements.randomizeAllSkillsBtn) elements.randomizeAllSkillsBtn.disabled = selected === 0;
    if (elements.randomizeAllArchetypesBtn) elements.randomizeAllArchetypesBtn.disabled = selected === 0;
    const mappings = [
      ['statsPoolCount', state.contestants.length], ['statsLineupCount', selected],
      ['summaryParticipantCount', state.contestants.length], ['summarySelectedCount', selected]
    ];
    mappings.forEach(([id, value]) => { const node = document.getElementById(id); if (node) node.textContent = String(value); });
  }

  function fillArchetypeSelect() {
    [elements.archetypeSelect, elements.customArchetypeSelect].filter(Boolean).forEach(select => {
      select.replaceChildren();
      const none = document.createElement('option');
      none.value = '';
      none.textContent = '—';
      select.append(none);
      ARCHETYPES.forEach(archetype => {
        const option = document.createElement('option');
        option.value = archetype.name;
        option.textContent = archetype.name;
        select.append(option);
      });
    });
  }

  function renderSkillGrid(grid, definitions, skills, idPrefix = 'stat') {
    if (!grid) return;
    grid.replaceChildren();
    definitions.forEach(([key, label]) => {
      const row = document.createElement('div');
      row.className = 'stat-editor-row';
      const labelElement = document.createElement('label');
      const inputId = `${idPrefix}-${key}`;
      labelElement.htmlFor = inputId;
      labelElement.textContent = label;
      const input = document.createElement('input');
      input.id = inputId;
      input.name = key;
      input.type = 'range';
      input.min = '1';
      input.max = '15';
      input.step = '1';
      input.value = String(clamp(skills[key] ?? DEFAULT_STAT));
      const output = document.createElement('output');
      output.className = 'stat-value';
      output.value = input.value;
      output.textContent = input.value;
      input.addEventListener('input', () => { output.value = input.value; output.textContent = input.value; });
      row.append(labelElement, input, output);
      grid.append(row);
    });
  }

  function renderEditorSkills(skills) {
    renderSkillGrid(elements.competitionSkillsGrid, COMPETITION_SKILLS, skills);
    renderSkillGrid(elements.socialSkillsGrid, SOCIAL_SKILLS, skills);
  }

  function currentFormSkills() {
    return Object.fromEntries(ALL_SKILLS.map(([key]) => {
      const input = elements.contestantEditForm?.elements.namedItem(key);
      return [key, clamp(input?.value ?? DEFAULT_STAT)];
    }));
  }

  function openEditDialog(id) {
    const contestant = state.contestantById.get(id);
    if (!contestant || !elements.contestantEditDialog) return;
    state.activeEditId = id;
    const profile = getProfile(id);
    elements.editContestantName.textContent = contestant.nickname || contestant.fullName || 'Edit Contestant';
    elements.editContestantFullName.textContent = contestant.fullName && contestant.fullName !== contestant.nickname ? contestant.fullName : '';
    elements.editContestantImage.alt = contestant.nickname || contestant.fullName || 'Contestant';
    setImageWithFallback(elements.editContestantImage, contestant);
    elements.archetypeSelect.value = profile.archetype || '';
    renderEditorSkills(profile.skills);
    openDialog(elements.contestantEditDialog);
  }

  function applyArchetypeInEditor() {
    const name = elements.archetypeSelect?.value || '';
    if (!name) return;
    renderEditorSkills(archetypePreset(name));
  }

  function randomizeEditorSkills() {
    renderEditorSkills(randomSkills());
  }

  function resetEditorSkills() {
    renderEditorSkills(baselineSkills());
  }

  function saveActiveProfile() {
    const id = state.activeEditId;
    if (!id) return;
    const profile = getProfile(id);
    profile.archetype = elements.archetypeSelect?.value || '';
    profile.skills = currentFormSkills();
    profile.randomizedArchetypeMods = {};
    profile.archetypePresetVersion = profile.archetype ? ARCHETYPE_PRESET_VERSION : 0;
    refreshHidden(profile);
    closeDialog(elements.contestantEditDialog);
    showToast('Contestant profile updated.');
  }

  function rebuildContestantIndex() {
    const merged = new Map();
    builtInContestants.forEach(contestant => {
      if (contestant?.id) merged.set(contestant.id, contestant);
    });
    (state.customContestants || []).forEach(contestant => {
      if (contestant?.id) merged.set(contestant.id, contestant);
    });
    state.contestants = [...merged.values()];
    state.contestantById = merged;
  }

  function customContestantId() {
    const randomPart = typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function'
      ? crypto.randomUUID().slice(0, 8)
      : Math.random().toString(36).slice(2, 10);
    return `custom_${Date.now().toString(36)}_${randomPart}`;
  }

  function renderCustomSkills(skills = baselineSkills()) {
    renderSkillGrid(elements.customCompetitionSkillsGrid, COMPETITION_SKILLS, skills, 'custom-stat');
    renderSkillGrid(elements.customSocialSkillsGrid, SOCIAL_SKILLS, skills, 'custom-social-stat');
  }

  function currentCustomFormSkills() {
    return Object.fromEntries(ALL_SKILLS.map(([key]) => {
      const input = elements.customContestantForm?.elements.namedItem(key);
      return [key, clamp(input?.value ?? DEFAULT_STAT)];
    }));
  }

  function applyArchetypeInCustomEditor() {
    const name = elements.customArchetypeSelect?.value || '';
    renderCustomSkills(name ? archetypePreset(name) : baselineSkills());
  }

  function randomizeCustomSkills() {
    if (elements.customArchetypeSelect) elements.customArchetypeSelect.value = '';
    renderCustomSkills(randomSkills());
  }

  function resetCustomSkills() {
    if (elements.customArchetypeSelect) elements.customArchetypeSelect.value = '';
    renderCustomSkills(baselineSkills());
  }

  function setCustomPreviewSource(source = '', fallbackName = '') {
    if (!elements.customContestantImagePreview) return;
    setImageWithFallback(elements.customContestantImagePreview, {
      image: source,
      nickname: elements.customContestantNickname?.value || fallbackName,
      fullName: elements.customContestantName?.value || fallbackName
    });
  }

  function resetCustomContestantForm() {
    activeCustomContestantId = '';
    pendingCustomImageData = '';
    pendingCustomImagePromise = Promise.resolve();
    if (elements.customContestantTitle) elements.customContestantTitle.textContent = 'Create Contestant';
    if (elements.customContestantImageUrl) elements.customContestantImageUrl.value = '';
    if (elements.customContestantImageFile) elements.customContestantImageFile.value = '';
    if (elements.customContestantName) elements.customContestantName.value = '';
    if (elements.customContestantNickname) elements.customContestantNickname.value = '';
    if (elements.customArchetypeSelect) elements.customArchetypeSelect.value = '';
    if (elements.deleteCustomContestantBtn) elements.deleteCustomContestantBtn.hidden = true;
    renderCustomSkills(baselineSkills());
    setCustomPreviewSource('', '?');
  }

  function openCustomContestantDialog(id = '') {
    if (!elements.createContestantDialog) return;
    const contestant = id ? state.contestantById.get(id) : null;
    if (!contestant?.isCustom) {
      resetCustomContestantForm();
    } else {
      activeCustomContestantId = contestant.id;
      pendingCustomImageData = /^data:/i.test(String(contestant.image || '')) ? contestant.image : '';
      pendingCustomImagePromise = Promise.resolve();
      if (elements.customContestantTitle) elements.customContestantTitle.textContent = 'Edit Contestant';
      if (elements.customContestantImageUrl) elements.customContestantImageUrl.value = /^https?:/i.test(String(contestant.image || '')) ? contestant.image : '';
      if (elements.customContestantImageFile) elements.customContestantImageFile.value = '';
      if (elements.customContestantName) elements.customContestantName.value = contestant.fullName || '';
      if (elements.customContestantNickname) elements.customContestantNickname.value = contestant.nickname || '';
      const profile = getProfile(contestant.id);
      if (elements.customArchetypeSelect) elements.customArchetypeSelect.value = profile.archetype || '';
      if (elements.deleteCustomContestantBtn) elements.deleteCustomContestantBtn.hidden = Boolean(state.seasonStarted);
      renderCustomSkills(profile.skills);
      setCustomPreviewSource(contestant.image || '', contestant.nickname || contestant.fullName || '?');
    }
    openDialog(elements.createContestantDialog);
  }

  function imageFromFile(file) {
    return new Promise((resolve, reject) => {
      const url = URL.createObjectURL(file);
      const image = new Image();
      image.onload = () => {
        URL.revokeObjectURL(url);
        resolve(image);
      };
      image.onerror = () => {
        URL.revokeObjectURL(url);
        reject(new Error('Image could not be loaded.'));
      };
      image.src = url;
    });
  }

  async function compressCustomImage(file) {
    if (!file || !String(file.type || '').startsWith('image/')) return '';
    const image = await imageFromFile(file);
    const largest = Math.max(image.naturalWidth || image.width || 1, image.naturalHeight || image.height || 1);
    const initialScale = Math.min(1, CUSTOM_IMAGE_MAX_DIMENSION / largest);
    let width = Math.max(1, Math.round((image.naturalWidth || image.width || 1) * initialScale));
    let height = Math.max(1, Math.round((image.naturalHeight || image.height || 1) * initialScale));
    let quality = .76;
    let result = '';

    for (let attempt = 0; attempt < 8; attempt += 1) {
      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      const context = canvas.getContext('2d', { alpha: true });
      context.drawImage(image, 0, 0, width, height);
      result = canvas.toDataURL('image/webp', quality);
      if (!/^data:image\/webp/i.test(result)) result = canvas.toDataURL('image/jpeg', quality);
      if (result.length <= CUSTOM_IMAGE_TARGET_LENGTH) break;
      if (quality > .5) quality -= .09;
      else {
        width = Math.max(120, Math.round(width * .84));
        height = Math.max(120, Math.round(height * .84));
      }
    }
    return result;
  }

  function handleCustomImageFile(event) {
    const file = event.target.files?.[0];
    if (!file) return;
    pendingCustomImagePromise = compressCustomImage(file)
      .then(data => {
        pendingCustomImageData = data;
        if (elements.customContestantImageUrl) elements.customContestantImageUrl.value = '';
        setCustomPreviewSource(data, elements.customContestantNickname?.value || elements.customContestantName?.value || '?');
      })
      .catch(() => {
        pendingCustomImageData = '';
        setCustomPreviewSource('', elements.customContestantNickname?.value || elements.customContestantName?.value || '?');
      });
  }

  function handleCustomImageUrl() {
    pendingCustomImageData = '';
    if (elements.customContestantImageFile) elements.customContestantImageFile.value = '';
    setCustomPreviewSource(elements.customContestantImageUrl?.value.trim() || '', elements.customContestantNickname?.value || elements.customContestantName?.value || '?');
  }

  function resetCustomContestantEditor() {
    if (!activeCustomContestantId) {
      resetCustomContestantForm();
      return;
    }
    const contestant = state.contestantById.get(activeCustomContestantId);
    if (!contestant?.isCustom) {
      resetCustomContestantForm();
      return;
    }
    pendingCustomImageData = /^data:/i.test(String(contestant.image || '')) ? contestant.image : '';
    pendingCustomImagePromise = Promise.resolve();
    if (elements.customContestantTitle) elements.customContestantTitle.textContent = 'Edit Contestant';
    if (elements.customContestantImageUrl) elements.customContestantImageUrl.value = /^https?:/i.test(String(contestant.image || '')) ? contestant.image : '';
    if (elements.customContestantImageFile) elements.customContestantImageFile.value = '';
    if (elements.customContestantName) elements.customContestantName.value = contestant.fullName || '';
    if (elements.customContestantNickname) elements.customContestantNickname.value = contestant.nickname || '';
    const profile = getProfile(contestant.id);
    if (elements.customArchetypeSelect) elements.customArchetypeSelect.value = profile.archetype || '';
    if (elements.deleteCustomContestantBtn) elements.deleteCustomContestantBtn.hidden = Boolean(state.seasonStarted);
    renderCustomSkills(profile.skills);
    setCustomPreviewSource(contestant.image || '', contestant.nickname || contestant.fullName || '?');
  }

  async function saveCustomContestant() {
    await pendingCustomImagePromise;
    const fullName = String(elements.customContestantName?.value || '').trim();
    const nicknameValue = String(elements.customContestantNickname?.value || '').trim();
    if (!fullName) {
      elements.customContestantName?.focus();
      return;
    }

    const id = activeCustomContestantId || customContestantId();
    const existing = state.customContestants.find(item => item.id === id);
    const imageUrl = String(elements.customContestantImageUrl?.value || '').trim();
    const image = pendingCustomImageData || imageUrl || existing?.image || '';
    const skills = currentCustomFormSkills();
    const archetype = elements.customArchetypeSelect?.value || '';
    const contestant = {
      id,
      nickname: nicknameValue || fullName,
      fullName,
      image,
      skills: { ...skills },
      shows: [CUSTOM_SHOW],
      seasonsByShow: { [CUSTOM_SHOW]: [] },
      isCustom: true
    };

    const index = state.customContestants.findIndex(item => item.id === id);
    if (index >= 0) state.customContestants[index] = contestant;
    else state.customContestants.push(contestant);

    rebuildContestantIndex();
    const profile = getProfile(id);
    profile.archetype = archetype;
    profile.skills = { ...skills };
    profile.randomizedArchetypeMods = {};
    profile.archetypePresetVersion = archetype ? ARCHETYPE_PRESET_VERSION : 0;
    refreshHidden(profile);

    closeDialog(elements.createContestantDialog);
    state.selectedShows = new Set([CUSTOM_SHOW]);
    state.selectedSeasons.clear();
    renderAllFilters();
    renderSelectedCast();
    scheduleSimulatorPersistence();
    persistSimulatorState();
  }

  function deleteCustomContestant() {
    const id = activeCustomContestantId;
    if (!id || state.seasonStarted) return;
    state.customContestants = state.customContestants.filter(item => item.id !== id);
    state.selectedIds = state.selectedIds.filter(value => value !== id);
    state.activeIds = state.activeIds.filter(value => value !== id);
    state.profilesById.delete(id);
    state.contestantRuntime.delete(id);
    state.relationships = new Map([...state.relationships].filter(([key]) => !String(key).split('::').includes(id)));
    [state.directionalRelationships, state.trust, state.suspicion, state.irritation, state.grudges, state.targetPriority, state.voteCommitment].forEach(map => {
      [...map.keys()].forEach(key => {
        if (String(key).split('::').includes(id)) map.delete(key);
      });
    });
    state.alliances.forEach(alliance => {
      alliance.members = (alliance.members || []).filter(memberId => memberId !== id);
      if (alliance.members.length < 2) alliance.active = false;
    });
    rebuildContestantIndex();
    activeCustomContestantId = '';
    closeDialog(elements.createContestantDialog);
    renderAllFilters();
    renderSelectedCast();
    scheduleSimulatorPersistence();
    persistSimulatorState();
  }

  function randomizeAllSelectedSkills() {
    state.selectedIds.forEach(id => {
      const profile = getProfile(id);
      profile.skills = randomSkills();
      profile.randomizedArchetypeMods = {};
      refreshHidden(profile);
    });
    closeDialog(elements.randomizeAllSkillsDialog);
    showToast(`Randomized skills for ${state.selectedIds.length} contestants.`);
  }

  function applyRandomizedArchetypeToProfile(profile, archetypeName) {
    profile.archetype = archetypeName;
    profile.skills = archetypePreset(archetypeName);
    profile.hidden = archetypeHiddenPreset(archetypeName) || deriveHidden(profile);
    profile.randomizedArchetypeMods = {};
    profile.archetypePresetVersion = ARCHETYPE_PRESET_VERSION;
  }

  function randomizeAllSelectedArchetypes() {
    if (!state.selectedIds.length || !ARCHETYPES.length) return;
    const archetypePool = shuffled(ARCHETYPES);
    state.selectedIds.forEach((id, index) => {
      const archetype = archetypePool[index % archetypePool.length];
      applyRandomizedArchetypeToProfile(getProfile(id), archetype.name);
    });
    closeDialog(elements.randomizeAllArchetypesDialog);
    scheduleSimulatorPersistence();
    showToast(`Randomized archetypes for ${state.selectedIds.length} contestants. Current skills were adjusted by each archetype's modifiers.`);
  }

  function populatePresetShowSelect() {
    if (!elements.presetShowSelect) return;
    elements.presetShowSelect.replaceChildren(new Option('Choose a show…', ''));
    sortedShows().filter(show => show !== CUSTOM_SHOW).forEach(show => elements.presetShowSelect.add(new Option(show, show)));
    elements.presetSeasonSelect.replaceChildren(new Option('Choose a show first', ''));
    elements.presetSeasonSelect.disabled = true;
    elements.applyPresetCastBtn.disabled = true;
    elements.presetCastPreview.textContent = '';
    elements.presetCastPreview.hidden = true;
  }

  function updatePresetSeasons() {
    const show = elements.presetShowSelect.value;
    elements.presetSeasonSelect.replaceChildren();
    if (!show) {
      elements.presetSeasonSelect.add(new Option('Choose a show first', ''));
      elements.presetSeasonSelect.disabled = true;
      elements.applyPresetCastBtn.disabled = true;
      elements.presetCastPreview.textContent = '';
    elements.presetCastPreview.hidden = true;
      return;
    }
    elements.presetSeasonSelect.add(new Option('Choose a season…', ''));
    seasonsForShow(show).forEach(season => elements.presetSeasonSelect.add(new Option(`Season ${season}`, season)));
    elements.presetSeasonSelect.disabled = false;
    elements.applyPresetCastBtn.disabled = true;
    elements.presetCastPreview.textContent = '';
    elements.presetCastPreview.hidden = true;
  }

  function contestantsForPreset(show, season) {
    return state.contestants.filter(contestant => (contestant.seasonsByShow?.[show] || []).map(String).includes(String(season)))
      .sort((a, b) => naturalCompare(a.fullName || a.nickname, b.fullName || b.nickname));
  }

  function updatePresetPreview() {
    const show = elements.presetShowSelect.value;
    const season = elements.presetSeasonSelect.value;
    if (!show || !season) {
      elements.applyPresetCastBtn.disabled = true;
      elements.presetCastPreview.textContent = '';
      elements.presetCastPreview.hidden = true;
      return;
    }
    const cast = contestantsForPreset(show, season);
    elements.presetCastPreview.textContent = cast.length
      ? `${cast.length} contestants found for ${show}, Season ${season}.`
      : 'No contestants were found for this season.';
    elements.presetCastPreview.hidden = false;
    elements.applyPresetCastBtn.disabled = cast.length === 0;
  }

  function applyPresetCast() {
    const show = elements.presetShowSelect.value;
    const season = elements.presetSeasonSelect.value;
    const cast = contestantsForPreset(show, season);
    if (!cast.length) return;

    const limit = castLimit();
    const openSlots = Math.max(0, limit - state.selectedIds.length);
    if (openSlots === 0) {
      closeDialog(elements.presetCastDialog);
      showToast(`Your cast already has ${limit} contestants.`);
      return;
    }

    const selected = new Set(state.selectedIds);
    const availableFromPreset = cast.filter(contestant => !selected.has(contestant.id));
    const added = availableFromPreset.slice(0, openSlots);

    added.forEach(contestant => {
      state.selectedIds.push(contestant.id);
      getProfile(contestant.id);
    });

    renderRoster();
    renderSelectedCast();
    closeDialog(elements.presetCastDialog);

    if (!added.length) {
      showToast('Every contestant from this pre-set cast is already in your lineup.');
    } else if (added.length < openSlots) {
      showToast(`Added ${added.length} contestant${added.length === 1 ? '' : 's'} from ${show}, Season ${season}. ${openSlots - added.length} cast slot${openSlots - added.length === 1 ? '' : 's'} remain open.`);
    } else if (availableFromPreset.length > openSlots) {
      showToast(`Filled the ${openSlots} available cast slot${openSlots === 1 ? '' : 's'} from ${show}, Season ${season}.`);
    } else {
      showToast(`Added ${added.length} contestant${added.length === 1 ? '' : 's'} from ${show}, Season ${season}.`);
    }
  }


  function relationshipKey(firstId, secondId) {
    return [String(firstId), String(secondId)].sort(naturalCompare).join('::');
  }

  function relationshipLabel(score) {
    return RELATIONSHIP_LABELS.get(Number(score)) || 'Neutral';
  }

  function relationshipTone(score) {
    const value = Number(score);
    if (value <= -7) return 'is-hostile';
    if (value <= -3) return 'is-negative';
    if (value < 0) return 'is-slightly-negative';
    if (value === 0) return 'is-neutral';
    if (value <= 2) return 'is-slightly-positive';
    if (value <= 6) return 'is-positive';
    return 'is-devoted';
  }

  function prepareRelationships() {
    const selected = new Set(state.selectedIds);
    [...state.relationships.keys()].forEach(key => {
      const [firstId, secondId] = key.split('::');
      if (!selected.has(firstId) || !selected.has(secondId)) state.relationships.delete(key);
    });
    for (let first = 0; first < state.selectedIds.length; first += 1) {
      for (let second = first + 1; second < state.selectedIds.length; second += 1) {
        const key = relationshipKey(state.selectedIds[first], state.selectedIds[second]);
        if (!state.relationships.has(key)) state.relationships.set(key, 0);
      }
    }
  }

  function formattedRelationshipScore(score) {
    const value = Number(score);
    return value > 0 ? `+${value}` : String(value);
  }

  function closeRelationshipMenu() {
    elements.relationshipsDialog?.querySelector('.relationship-score-menu')?.remove();
    document.querySelectorAll('.relationship-score-button[aria-expanded="true"]').forEach(button => {
      button.setAttribute('aria-expanded', 'false');
    });
  }

  function updateRelationshipButton(button, value) {
    const numericValue = Number(value);
    button.textContent = formattedRelationshipScore(numericValue);
    button.dataset.value = String(numericValue);
    button.title = `${formattedRelationshipScore(numericValue)} · ${relationshipLabel(numericValue)}`;
    button.classList.remove('is-hostile', 'is-negative', 'is-slightly-negative', 'is-neutral', 'is-slightly-positive', 'is-positive', 'is-devoted');
    button.classList.add(relationshipTone(numericValue));
  }

  function setRelationshipScore(key, value) {
    const numericValue = Number(value);
    state.relationships.set(key, numericValue);
    state.relationshipControls.get(key)?.forEach(control => updateRelationshipButton(control, numericValue));
    closeRelationshipMenu();
  }

  function openRelationshipMenu(button, key) {
    closeRelationshipMenu();
    const menu = document.createElement('div');
    menu.className = 'relationship-score-menu';
    menu.setAttribute('role', 'listbox');
    menu.setAttribute('aria-label', 'Choose relationship score');

    for (let score = -10; score <= 10; score += 1) {
      const option = document.createElement('button');
      option.type = 'button';
      option.className = `relationship-score-option ${relationshipTone(score)}`;
      option.setAttribute('role', 'option');
      option.setAttribute('aria-selected', Number(state.relationships.get(key) ?? 0) === score ? 'true' : 'false');

      const points = document.createElement('strong');
      points.textContent = formattedRelationshipScore(score);
      const label = document.createElement('span');
      label.textContent = relationshipLabel(score);
      option.append(points, label);
      option.addEventListener('click', event => {
        event.stopPropagation();
        setRelationshipScore(key, score);
      });
      menu.append(option);
    }

    elements.relationshipsDialog.append(menu);
    button.setAttribute('aria-expanded', 'true');

    const buttonRect = button.getBoundingClientRect();
    const menuRect = menu.getBoundingClientRect();
    const left = Math.max(6, Math.min(buttonRect.left, window.innerWidth - menuRect.width - 6));
    let top = buttonRect.bottom + 3;
    if (top + menuRect.height > window.innerHeight - 6) top = Math.max(6, buttonRect.top - menuRect.height - 3);
    menu.style.left = `${left}px`;
    menu.style.top = `${top}px`;
    const selectedOption = menu.querySelector('[aria-selected="true"]');
    if (selectedOption) menu.scrollTop = Math.max(0, selectedOption.offsetTop - (menu.clientHeight - selectedOption.offsetHeight) / 2);
  }

  function makeRelationshipSelect(firstId, secondId) {
    const key = relationshipKey(firstId, secondId);
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'relationship-score-button';
    button.setAttribute('aria-haspopup', 'listbox');
    button.setAttribute('aria-expanded', 'false');
    button.setAttribute('aria-label', `${state.contestantById.get(firstId)?.fullName || 'Contestant'} and ${state.contestantById.get(secondId)?.fullName || 'Contestant'} relationship`);
    updateRelationshipButton(button, state.relationships.get(key) ?? 0);
    if (!state.relationshipControls.has(key)) state.relationshipControls.set(key, new Set());
    state.relationshipControls.get(key).add(button);
    button.addEventListener('click', event => {
      event.stopPropagation();
      openRelationshipMenu(button, key);
    });
    return button;
  }

  function renderRelationshipGrid() {
    if (!elements.relationshipGrid) return;
    closeRelationshipMenu();
    prepareRelationships();
    state.relationshipControls = new Map();
    elements.relationshipGrid.replaceChildren();

    const head = document.createElement('thead');
    const headRow = document.createElement('tr');
    const corner = document.createElement('th');
    corner.className = 'relationship-corner-cell';
    corner.setAttribute('aria-hidden', 'true');
    headRow.append(corner);
    state.selectedIds.forEach(id => {
      const contestant = state.contestantById.get(id);
      const header = document.createElement('th');
      header.className = 'relationship-column-head';
      header.title = contestant?.fullName || contestant?.nickname || '';
      const image = document.createElement('img');
      image.className = 'relationship-contestant-image';
      image.alt = contestant?.fullName || contestant?.nickname || 'Contestant';
      if (contestant) setImageWithFallback(image, contestant);
      header.append(image);
      headRow.append(header);
    });
    head.append(headRow);

    const body = document.createElement('tbody');
    state.selectedIds.forEach(rowId => {
      const rowContestant = state.contestantById.get(rowId);
      const row = document.createElement('tr');
      const rowHead = document.createElement('th');
      rowHead.className = 'relationship-row-head';
      rowHead.title = rowContestant?.fullName || rowContestant?.nickname || '';
      const rowImage = document.createElement('img');
      rowImage.className = 'relationship-contestant-image';
      rowImage.alt = rowContestant?.fullName || rowContestant?.nickname || 'Contestant';
      if (rowContestant) setImageWithFallback(rowImage, rowContestant);
      rowHead.append(rowImage);
      row.append(rowHead);

      state.selectedIds.forEach(columnId => {
        const cell = document.createElement('td');
        if (rowId === columnId) {
          cell.className = 'relationship-self-cell';
          cell.textContent = '—';
        } else {
          cell.append(makeRelationshipSelect(rowId, columnId));
        }
        row.append(cell);
      });
      body.append(row);
    });
    elements.relationshipGrid.append(head, body);
  }

  function randomRelationshipScore() {
    const centered = (Math.random() + Math.random() + Math.random() + Math.random()) - 2;
    let value = Math.round(centered * 5.1);
    if (Math.random() < .025) value = Math.random() < .5 ? -10 : 10;
    return Math.max(-10, Math.min(10, value));
  }

  function applyRelationshipValues(factory) {
    prepareRelationships();
    state.relationships.forEach((_, key) => state.relationships.set(key, factory()));
    renderRelationshipGrid();
  }

  function openRelationshipSetupStep() {
    renderRelationshipGrid();
    openDialog(elements.relationshipsDialog);
  }

  function startSeasonSetupFlow() {
    if (state.selectedIds.length !== castLimit()) {
      showToast(`Select exactly ${castLimit()} contestants before starting.`);
      return;
    }
    if (lateEntrantOptionEnabled()) {
      refreshLateEntrantPicker();
      openDialog(elements.lateEntrantDialog);
      return;
    }
    state.lateEntrantId = '';
    openRelationshipSetupStep();
  }

  function confirmLateEntrantSelection() {
    const id = elements.lateEntrantSelect?.value || '';
    if (!id || !state.selectedIds.includes(id)) {
      if (elements.lateEntrantMessage) {
        elements.lateEntrantMessage.textContent = 'Choose one contestant from the selected cast.';
        elements.lateEntrantMessage.hidden = false;
      }
      return;
    }
    state.lateEntrantId = id;
    closeDialog(elements.lateEntrantDialog);
    openRelationshipSetupStep();
    scheduleSimulatorPersistence();
  }

  function confirmRelationships() {
    closeDialog(elements.relationshipsDialog);
    setTeamSetupMessage('');
    prepareTeamSetup(false);
    renderTeamSetup();
    openDialog(elements.teamSetupDialog);
  }

  function currentTeamSetupSignature() {
    const starters = startingCastIds();
    return `${teamCount()}|${starters.slice().sort(naturalCompare).join('|')}|${teamDistribution(starters.length, teamCount()).join(',')}`;
  }

  function defaultTeams() {
    const sizes = teamDistribution(startingCastIds().length, teamCount());
    return sizes.map((size, index) => ({
      name: TEAM_OPTIONS[index]?.name || TEAM_OPTIONS[0].name,
      members: Array(size).fill('')
    }));
  }

  function prepareTeamSetup(forceReset = false) {
    const signature = currentTeamSetupSignature();
    if (forceReset || state.teamSetupSignature !== signature || state.teams.length !== teamCount()) {
      state.teams = defaultTeams();
      state.teamSetupSignature = signature;
    }
  }

  function teamOption(name) {
    return TEAM_BY_NAME.get(name) || TEAM_OPTIONS[0];
  }

  function assignedContestantIds(exceptTeamIndex = -1, exceptSlotIndex = -1) {
    const assigned = new Set();
    state.teams.forEach((team, teamIndex) => team.members.forEach((id, slotIndex) => {
      if (teamIndex === exceptTeamIndex && slotIndex === exceptSlotIndex) return;
      if (id) assigned.add(id);
    }));
    return assigned;
  }

  function assignedTeamNames(exceptTeamIndex = -1) {
    return new Set(state.teams.map((team, index) => index === exceptTeamIndex ? '' : team.name).filter(Boolean));
  }

  function createTeamEmblemPlaceholder(team) {
    const initials = team.name.split(/\s+/).map(word => word[0]).join('').slice(0, 3).toUpperCase();
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 120"><circle cx="60" cy="60" r="54" fill="#fff8e8" stroke="${team.color}" stroke-width="9"/><path d="M60 19 43 50h12L39 82h42L65 50h12Z" fill="${team.color}"/><text x="60" y="105" text-anchor="middle" font-family="Arial,sans-serif" font-size="18" font-weight="900" fill="#203138">${initials}</text></svg>`;
    return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
  }

  function setTeamEmblemWithFallback(img, team) {
    const encodedFolder = 'images/Team%20Emblems';
    const candidates = [
      `${encodedFolder}/${team.emblem}`,
      `../${encodedFolder}/${team.emblem}`,
      createTeamEmblemPlaceholder(team)
    ];
    let index = 0;
    img.onerror = () => {
      index += 1;
      if (index < candidates.length) img.src = candidates[index];
      else img.onerror = null;
    };
    img.src = candidates[0];
  }

  function createEmptyCamperImage() {
    const svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="100" height="100" rx="20" fill="#f1e3c7"/><circle cx="50" cy="37" r="18" fill="#c9b898"/><path d="M18 94c4-24 16-36 32-36s28 12 32 36" fill="#9eaa91"/></svg>';
    return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
  }

  function renderTeamSetup() {
    if (!elements.teamSetupGrid) return;
    prepareTeamSetup(false);
    elements.teamSetupGrid.replaceChildren();
    state.teams.forEach((team, teamIndex) => {
      const teamData = teamOption(team.name);
      const card = document.createElement('section');
      card.className = 'team-setup-card';
      card.style.setProperty('--team-color', teamData.color);

      const header = document.createElement('div');
      header.className = 'team-setup-card-head';
      const identity = document.createElement('div');
      identity.className = 'team-name-field';
      const label = document.createElement('span');
      label.textContent = `Team ${teamIndex + 1}`;
      const nameSelect = document.createElement('select');
      nameSelect.className = 'team-name-select';
      const unavailableNames = assignedTeamNames(teamIndex);
      TEAM_OPTIONS.forEach(optionData => {
        const option = new Option(optionData.name, optionData.name);
        option.disabled = unavailableNames.has(optionData.name);
        nameSelect.add(option);
      });
      nameSelect.value = team.name;
      nameSelect.addEventListener('change', () => {
        team.name = nameSelect.value;
        renderTeamSetup();
      });
      identity.append(label, nameSelect);

      const emblem = document.createElement('img');
      emblem.className = 'team-emblem-image';
      emblem.alt = `${team.name} emblem`;
      setTeamEmblemWithFallback(emblem, teamData);
      header.append(identity, emblem);

      const memberList = document.createElement('div');
      memberList.className = 'team-member-slots';
      team.members.forEach((currentId, slotIndex) => {
        const slot = document.createElement('div');
        slot.className = 'team-member-slot';
        const portrait = document.createElement('img');
        portrait.className = 'team-member-image';
        const currentContestant = state.contestantById.get(currentId);
        portrait.alt = currentContestant ? (currentContestant.nickname || currentContestant.fullName) : 'Empty team spot';
        if (currentContestant) setImageWithFallback(portrait, currentContestant);
        else portrait.src = createEmptyCamperImage();

        const select = document.createElement('select');
        select.className = 'team-member-select';
        select.add(new Option(`Choose contestant ${slotIndex + 1}…`, ''));
        const unavailable = assignedContestantIds(teamIndex, slotIndex);
        startingCastIds()
          .map(id => state.contestantById.get(id))
          .filter(Boolean)
          .sort((first, second) => naturalCompare(first.fullName || first.nickname, second.fullName || second.nickname))
          .forEach(contestant => {
            const labelText = contestant.fullName || contestant.nickname || 'Unnamed Contestant';
            const option = new Option(labelText, contestant.id);
            option.disabled = unavailable.has(contestant.id);
            select.add(option);
          });
        select.value = currentId || '';
        select.addEventListener('change', () => {
          team.members[slotIndex] = select.value;
          renderTeamSetup();
        });
        slot.append(portrait, select);
        memberList.append(slot);
      });

      card.append(header, memberList);
      elements.teamSetupGrid.append(card);
    });
  }

  function randomizeTeams() {
    setTeamSetupMessage('');
    prepareTeamSetup(false);
    const names = shuffled(TEAM_OPTIONS.map(team => team.name)).slice(0, state.teams.length);
    const campers = shuffled(startingCastIds());
    let cursor = 0;
    state.teams.forEach((team, index) => {
      team.name = names[index];
      team.members = team.members.map(() => campers[cursor++]);
    });
    renderTeamSetup();
  }

  function randomizeEvenGenderTeams() {
    setTeamSetupMessage('');
    prepareTeamSetup(false);
    const names = shuffled(TEAM_OPTIONS.map(team => team.name)).slice(0, state.teams.length);
    const pools = { male: [], female: [], other: [] };
    startingCastIds().forEach(id => {
      const contestant = state.contestantById.get(id);
      if (contestant) pools[normalizedGenderGroup(contestant)].push(id);
    });
    Object.keys(pools).forEach(key => { pools[key] = shuffled(pools[key]); });

    const assignments = state.teams.map(team => ({
      capacity: team.members.length,
      members: [],
      male: 0,
      female: 0,
      other: 0
    }));
    const teamOrder = shuffled(assignments.map((_, index) => index));

    const chooseGenderForTeam = team => {
      const options = ['male', 'female'].filter(gender => pools[gender].length);
      if (!options.length) return pools.other.length ? 'other' : '';
      if (options.length === 1) return options[0];
      const maleImbalance = Math.abs((team.male + 1) - team.female);
      const femaleImbalance = Math.abs(team.male - (team.female + 1));
      if (maleImbalance < femaleImbalance) return 'male';
      if (femaleImbalance < maleImbalance) return 'female';
      if (pools.male.length !== pools.female.length) return pools.male.length > pools.female.length ? 'male' : 'female';
      return Math.random() < .5 ? 'male' : 'female';
    };

    let added = true;
    while (added) {
      added = false;
      teamOrder.forEach(index => {
        const team = assignments[index];
        if (team.members.length >= team.capacity) return;
        let gender = chooseGenderForTeam(team);
        if (!gender) gender = ['male', 'female', 'other'].find(key => pools[key].length) || '';
        if (!gender) return;
        const id = pools[gender].pop();
        team.members.push(id);
        team[gender] += 1;
        added = true;
      });
    }

    state.teams.forEach((team, index) => {
      team.name = names[index];
      team.members = assignments[index].members;
    });
    renderTeamSetup();
    const summary = assignments.map((team, index) => {
      const extra = team.other ? `, ${team.other} other/unspecified` : '';
      return `Team ${index + 1}: ${team.male} male, ${team.female} female${extra}`;
    }).join(' · ');
    showToast(`Even-gender team split randomized. ${summary}`);
  }

  function resetTeams() {
    setTeamSetupMessage('');
    prepareTeamSetup(true);
    renderTeamSetup();
  }

  function setTeamSetupMessage(message = '', kind = 'error') {
    if (!elements.teamSetupMessage) return;
    elements.teamSetupMessage.textContent = message;
    elements.teamSetupMessage.hidden = !message;
    elements.teamSetupMessage.classList.toggle('is-success', kind === 'success');
  }

  function seasonPreparationEstimate() {
    const regularStop = finaleTargetCount(selectedFinaleFormat());
    const regularEpisodes = Math.max(0, state.selectedIds.length - regularStop);
    const finaleEpisodes = selectedFinaleFormat().startsWith('final-two') ? 2 : selectedFinaleFormat() === 'final-four-showdown' ? 2 : 1;
    const options = readSeasonOptionsFromSetup();
    const extras = (options.nonElimination ? 1 : 0) + (options.return ? 1 : 0);
    return Math.max(1, regularEpisodes + finaleEpisodes + extras);
  }

  function updateSeasonPreparation(message, completed = 0, total = seasonPreparationEstimate()) {
    const safeTotal = Math.max(1, Number(total) || 1);
    const safeCompleted = Math.max(0, Math.min(safeTotal, Number(completed) || 0));
    const percent = Math.round((safeCompleted / safeTotal) * 100);
    if (elements.seasonPreparingText) elements.seasonPreparingText.textContent = message;
    if (elements.seasonPreparingBar) elements.seasonPreparingBar.style.width = `${percent}%`;
    if (elements.seasonPreparingProgress) elements.seasonPreparingProgress.setAttribute('aria-valuenow', String(percent));
  }

  function yieldSeasonPreparation() {
    return new Promise(resolve => window.setTimeout(resolve, 0));
  }

  async function confirmTeams() {
    if (seasonPreparationRunning) return;
    const names = state.teams.map(team => team.name);
    if (new Set(names).size !== names.length) {
      setTeamSetupMessage('Each team needs a different team name.');
      return;
    }
    const members = state.teams.flatMap(team => team.members);
    if (members.some(id => !id)) {
      setTeamSetupMessage('Fill every team spot before confirming. You can also use Randomize or Randomize Even-Gender Split.');
      return;
    }
    const starters = startingCastIds();
    if (new Set(members).size !== starters.length || members.length !== starters.length || starters.some(id => !members.includes(id))) {
      setTeamSetupMessage('Each starting contestant must appear on exactly one team. The selected late entrant must remain off the starting teams.');
      return;
    }

    seasonPreparationRunning = true;
    setTeamSetupMessage('');
    if (elements.confirmTeamsBtn) elements.confirmTeamsBtn.disabled = true;
    closeDialog(elements.teamSetupDialog);
    updateSeasonPreparation('Setting up contestants, relationships, and teams…', 0);
    openDialog(elements.seasonPreparingDialog);
    await yieldSeasonPreparation();

    try {
      initializeSeasonRuntime();
      await simulateSeasonToFinaleAsync((message, completed, total) => {
        updateSeasonPreparation(message, completed, total);
      });
      updateSeasonPreparation('Season ready!', seasonPreparationEstimate(), seasonPreparationEstimate());
      await yieldSeasonPreparation();
      closeDialog(elements.seasonPreparingDialog);
      showScreen('simulation-screen');
      activateEpisode(0);
      openEpisodePanel('overview');
      persistSimulatorState();
    } catch (error) {
      console.error('Season preparation failed.', error);
      closeDialog(elements.seasonPreparingDialog);
      openDialog(elements.teamSetupDialog);
      setTeamSetupMessage('The season could not finish generating. Please try confirming the teams again.');
    } finally {
      seasonPreparationRunning = false;
      if (elements.confirmTeamsBtn) elements.confirmTeamsBtn.disabled = false;
    }
  }



  function clampRange(value, minimum, maximum) {
    return Math.max(minimum, Math.min(maximum, Number(value) || 0));
  }

  function randomInteger(minimum, maximum) {
    const low = Math.ceil(minimum);
    const high = Math.floor(maximum);
    return Math.floor(Math.random() * (high - low + 1)) + low;
  }

  function weightedChoice(items, weightFor) {
    const weighted = items.map(item => ({ item, weight: Math.max(0, Number(weightFor(item)) || 0) }));
    const total = weighted.reduce((sum, entry) => sum + entry.weight, 0);
    if (total <= 0) return items.length ? items[randomInteger(0, items.length - 1)] : null;
    let roll = Math.random() * total;
    for (const entry of weighted) {
      roll -= entry.weight;
      if (roll <= 0) return entry.item;
    }
    return weighted.at(-1)?.item || null;
  }

  function directionalKey(fromId, toId) {
    return `${fromId}>>${toId}`;
  }

  function getDirectional(map, fromId, toId, fallback = 0) {
    return Number(map.get(directionalKey(fromId, toId)) ?? fallback);
  }

  function setDirectional(map, fromId, toId, value, minimum, maximum) {
    const key = directionalKey(fromId, toId);
    const next = clampRange(value, minimum, maximum);
    map.set(key, next);
    return next;
  }

  function adjustDirectional(map, fromId, toId, delta, minimum, maximum) {
    return setDirectional(map, fromId, toId, getDirectional(map, fromId, toId) + delta, minimum, maximum);
  }

  function runtimeFor(id) {
    if (!state.contestantRuntime.has(id)) {
      const profile = getProfile(id);
      const hidden = profile.hidden || {};
      const centered = key => clampRange(Number(hidden[key] ?? DEFAULT_STAT), 1, 15) - 8;
      state.contestantRuntime.set(id, {
        morale: clampRange(50 + centered('enthusiasm') * 1.5, 42, 58),
        emotionalPressure: clampRange(18 + centered('pressure') * 2.2 - centered('pressureResistance') * 1.2, 5, 35),
        confidence: clampRange(50 + centered('confidence') * 4, 28, 72),
        isolation: 5,
        fatigue: 5,
        health: 100,
        quitRisk: clampRange(5 + centered('quitRisk') * 2.2 - centered('motivation') * 1.1, 0, 22),
        strategicInfluence: 0,
        socialVisibility: 0,
        hygiene: 60,
        seasonSkills: Object.fromEntries(DYNAMIC_VISIBLE_SKILL_KEYS.map(key => [key, clampRange(profile.skills?.[key] ?? DEFAULT_STAT, 1, 15)])),
        seasonHidden: Object.fromEntries(DYNAMIC_HIDDEN_TRAIT_KEYS.map(key => [key, clampRange(hidden?.[key] ?? DEFAULT_STAT, 1, 15)])),
        developmentEpisode: 0,
        developmentSkillDelta: {},
        developmentHiddenDelta: {},
        reputations: {},
        flags: {},
        memories: [],
        storylines: {},
        promises: [],
        plans: [],
        recentCategories: [],
        eventAppearances: 0,
        quitStage: 0,
        withdrawn: false
      });
    }
    const runtime = state.contestantRuntime.get(id);
    const profile = getProfile(id);
    if (!Number.isFinite(Number(runtime.hygiene))) runtime.hygiene = 60;
    if (!runtime.seasonSkills || typeof runtime.seasonSkills !== 'object' || Array.isArray(runtime.seasonSkills)) runtime.seasonSkills = {};
    DYNAMIC_VISIBLE_SKILL_KEYS.forEach(key => {
      if (!Number.isFinite(Number(runtime.seasonSkills[key]))) runtime.seasonSkills[key] = clampRange(profile.skills?.[key] ?? DEFAULT_STAT, 1, 15);
    });
    if (!runtime.seasonHidden || typeof runtime.seasonHidden !== 'object' || Array.isArray(runtime.seasonHidden)) runtime.seasonHidden = {};
    DYNAMIC_HIDDEN_TRAIT_KEYS.forEach(key => {
      if (!Number.isFinite(Number(runtime.seasonHidden[key]))) runtime.seasonHidden[key] = clampRange(profile.hidden?.[key] ?? DEFAULT_STAT, 1, 15);
    });
    if (!Number.isFinite(Number(runtime.developmentEpisode))) runtime.developmentEpisode = 0;
    if (!runtime.developmentSkillDelta || typeof runtime.developmentSkillDelta !== 'object' || Array.isArray(runtime.developmentSkillDelta)) runtime.developmentSkillDelta = {};
    if (!runtime.developmentHiddenDelta || typeof runtime.developmentHiddenDelta !== 'object' || Array.isArray(runtime.developmentHiddenDelta)) runtime.developmentHiddenDelta = {};
    if (!runtime.reputations || typeof runtime.reputations !== 'object') runtime.reputations = {};
    if (!runtime.flags || typeof runtime.flags !== 'object' || Array.isArray(runtime.flags)) runtime.flags = {};
    if (!Array.isArray(runtime.memories)) runtime.memories = [];
    if (!runtime.storylines || typeof runtime.storylines !== 'object' || Array.isArray(runtime.storylines)) runtime.storylines = {};
    if (!Array.isArray(runtime.promises)) runtime.promises = [];
    if (!Array.isArray(runtime.plans)) runtime.plans = [];
    if (!Array.isArray(runtime.recentCategories)) runtime.recentCategories = [];
    return runtime;
  }

  function currentSkill(id, key) {
    const profile = getProfile(id);
    if (!DYNAMIC_VISIBLE_SKILL_SET.has(key)) return clampRange(profile.skills?.[key] ?? DEFAULT_STAT, 1, 15);
    return clampRange(runtimeFor(id).seasonSkills?.[key] ?? profile.skills?.[key] ?? DEFAULT_STAT, 1, 15);
  }

  function currentHidden(id, key) {
    const profile = getProfile(id);
    if (!DYNAMIC_HIDDEN_TRAIT_SET.has(key)) return clampRange(profile.hidden?.[key] ?? DEFAULT_STAT, 1, 15);
    return clampRange(runtimeFor(id).seasonHidden?.[key] ?? profile.hidden?.[key] ?? DEFAULT_STAT, 1, 15);
  }

  function effectiveSkillsFor(id) {
    return Object.fromEntries(ALL_SKILLS.map(([key]) => [key, currentSkill(id, key)]));
  }

  function effectiveHiddenFor(id) {
    return Object.fromEntries(HIDDEN_TRAIT_KEYS.map(key => [key, currentHidden(id, key)]));
  }

  function ensureDevelopmentLedger(runtime) {
    if (Number(runtime.developmentEpisode || 0) === Number(state.episodeNumber || 0)) return;
    runtime.developmentEpisode = Number(state.episodeNumber || 0);
    runtime.developmentSkillDelta = {};
    runtime.developmentHiddenDelta = {};
  }

  function boundedEpisodeDevelopment(ledger, key, requested, limit) {
    const used = Number(ledger[key] || 0);
    const next = clampRange(used + Number(requested || 0), -limit, limit);
    ledger[key] = next;
    return next - used;
  }

  function adjustSeasonSkill(id, key, delta) {
    if (!DYNAMIC_VISIBLE_SKILL_SET.has(key)) return currentSkill(id, key);
    const profile = getProfile(id);
    const runtime = runtimeFor(id);
    ensureDevelopmentLedger(runtime);
    const applied = boundedEpisodeDevelopment(runtime.developmentSkillDelta, key, delta, SEASON_VISIBLE_EPISODE_CHANGE_LIMIT);
    if (!applied) return currentSkill(id, key);
    const base = clampRange(profile.skills?.[key] ?? DEFAULT_STAT, 1, 15);
    const minimum = Math.max(1, base - SEASON_VISIBLE_DEVIATION_LIMIT);
    const maximum = Math.min(15, base + SEASON_VISIBLE_DEVIATION_LIMIT);
    runtime.seasonSkills[key] = clampRange(Number(runtime.seasonSkills[key] ?? base) + applied, minimum, maximum);
    return runtime.seasonSkills[key];
  }

  function adjustSeasonHidden(id, key, delta) {
    if (!DYNAMIC_HIDDEN_TRAIT_SET.has(key)) return currentHidden(id, key);
    const profile = getProfile(id);
    const runtime = runtimeFor(id);
    ensureDevelopmentLedger(runtime);
    const applied = boundedEpisodeDevelopment(runtime.developmentHiddenDelta, key, delta, SEASON_HIDDEN_EPISODE_CHANGE_LIMIT);
    if (!applied) return currentHidden(id, key);
    const base = clampRange(profile.hidden?.[key] ?? DEFAULT_STAT, 1, 15);
    const minimum = Math.max(1, base - SEASON_HIDDEN_DEVIATION_LIMIT);
    const maximum = Math.min(15, base + SEASON_HIDDEN_DEVIATION_LIMIT);
    runtime.seasonHidden[key] = clampRange(Number(runtime.seasonHidden[key] ?? base) + applied, minimum, maximum);
    return runtime.seasonHidden[key];
  }

  function adjustRuntime(id, key, delta) {
    const runtime = runtimeFor(id);
    const hidden = effectiveHiddenFor(id);
    let adjustedDelta = Number(delta) || 0;
    const centered = trait => clampRange(Number(hidden[trait] ?? DEFAULT_STAT), 1, 15) - 8;

    if (key === 'confidence') {
      if (adjustedDelta > 0) {
        adjustedDelta *= clampRange(1 + centered('confidenceGrowth') * .055, .72, 1.38);
      } else if (adjustedDelta < 0) {
        adjustedDelta *= clampRange(1 - centered('pressureResistance') * .030 - centered('composure') * .020, .68, 1.32);
      }
    } else if (key === 'emotionalPressure' && adjustedDelta > 0) {
      adjustedDelta *= clampRange(
        1 + centered('pressure') * .045 - centered('pressureResistance') * .050 - centered('composure') * .025,
        .62,
        1.45
      );
    } else if (key === 'health' && adjustedDelta < 0) {
      adjustedDelta *= clampRange(
        1 - centered('injuryResistance') * .045 + centered('injuryRisk') * .040,
        .55,
        1.55
      );
    } else if (key === 'fatigue' && adjustedDelta > 0) {
      adjustedDelta *= clampRange(
        1 - centered('recovery') * .025 - centered('injuryResistance') * .015 + centered('injuryRisk') * .015,
        .70,
        1.32
      );
    } else if (key === 'quitRisk' && adjustedDelta > 0) {
      adjustedDelta *= clampRange(
        1 - centered('motivation') * .040 - centered('pressureResistance') * .025 + centered('quitRisk') * .035,
        .62,
        1.45
      );
      if (hasNarrativeFlag(id, 'stay-out-of-spite')) adjustedDelta *= .55;
      if (hasNarrativeFlag(id, 'quit-threshold')) adjustedDelta *= 1.35;
    }

    if (key === 'morale' && adjustedDelta < 0 && hasNarrativeFlag(id, 'stay-out-of-spite')) adjustedDelta *= .80;
    if (key === 'isolation' && adjustedDelta > 0 && hasNarrativeFlag(id, 'temporary-withdrawal')) adjustedDelta *= .45;

    runtime[key] = clampRange((runtime[key] ?? 0) + adjustedDelta, 0, 100);
    return runtime[key];
  }

  function addReputation(id, label, amount = 1) {
    const runtime = runtimeFor(id);
    runtime.reputations[label] = clampRange((runtime.reputations[label] || 0) + amount, 0, 10);
  }



  function narrativeSlug(value) {
    return String(value || '')
      .replace(/\[[A-FQ]\]/g, '')
      .replace(/[’']/g, '')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 64);
  }

  function narrativeRoleIndex(role) {
    if (typeof role === 'number') return role;
    const text = String(role || 'A').toUpperCase();
    if (/^[A-F]$/.test(text)) return text.charCodeAt(0) - 65;
    return 0;
  }

  function narrativeTargetIds(target, participants) {
    const ids = [...(participants || [])];
    if (Array.isArray(target)) return [...new Set(target.flatMap(item => narrativeTargetIds(item, ids)))];
    const key = String(target || 'A').toLowerCase();
    if (key === 'participants' || key === 'all') return [...ids];
    if (key === 'others') return ids.slice(1);
    if (key === 'active') return [...state.activeIds];
    const index = narrativeRoleIndex(target);
    return ids[index] ? [ids[index]] : [];
  }

  function activeNarrativeFlag(id, key) {
    const runtime = runtimeFor(id);
    const flag = runtime.flags?.[narrativeSlug(key)];
    if (!flag) return null;
    if (Number.isFinite(Number(flag.expiresEpisode)) && state.episodeNumber > Number(flag.expiresEpisode)) {
      delete runtime.flags[narrativeSlug(key)];
      return null;
    }
    return flag;
  }

  function hasNarrativeFlag(id, key, aboutId = '') {
    const flag = activeNarrativeFlag(id, key);
    if (!flag) return false;
    return !aboutId || !flag.aboutId || String(flag.aboutId) === String(aboutId);
  }

  function addNarrativeFlag(id, key, options = {}) {
    if (!id || !state.contestantById.has(id)) return null;
    const runtime = runtimeFor(id);
    const slug = narrativeSlug(key);
    if (!slug) return null;
    const duration = Number(options.duration || 0);
    const existing = runtime.flags[slug] || {};
    const flag = {
      key: slug,
      label: options.label || existing.label || String(key || slug),
      createdEpisode: Number(existing.createdEpisode || state.episodeNumber),
      expiresEpisode: duration > 0 ? Math.max(Number(existing.expiresEpisode || 0), state.episodeNumber + duration) : (existing.expiresEpisode ?? null),
      sourceEvent: options.sourceEvent || existing.sourceEvent || '',
      aboutId: options.aboutId || existing.aboutId || '',
      strength: clampRange(Number(options.strength ?? existing.strength ?? 1), 1, 5)
    };
    runtime.flags[slug] = flag;
    return flag;
  }

  function removeNarrativeFlag(id, key) {
    const runtime = runtimeFor(id);
    const slug = narrativeSlug(key);
    if (!runtime.flags?.[slug]) return false;
    delete runtime.flags[slug];
    return true;
  }

  function addNarrativeMemory(ownerId, key, options = {}) {
    if (!ownerId || !state.contestantById.has(ownerId)) return null;
    const runtime = runtimeFor(ownerId);
    const slug = narrativeSlug(key);
    if (!slug) return null;
    const aboutId = options.aboutId || '';
    const existing = runtime.memories.find(memory => memory.key === slug && String(memory.aboutId || '') === String(aboutId));
    if (existing) {
      existing.strength = clampRange(Number(existing.strength || 1) + Number(options.strength || 1), 1, 5);
      existing.lastEpisode = state.episodeNumber;
      if (options.valence) existing.valence = options.valence;
      return existing;
    }
    const memory = {
      key: slug,
      label: options.label || String(key || slug),
      aboutId,
      strength: clampRange(Number(options.strength || 1), 1, 5),
      valence: options.valence || 'neutral',
      createdEpisode: state.episodeNumber,
      lastEpisode: state.episodeNumber,
      sourceEvent: options.sourceEvent || ''
    };
    runtime.memories.push(memory);
    runtime.memories = runtime.memories.slice(-40);
    return memory;
  }

  function hasNarrativeMemory(ownerId, key, aboutId = '') {
    const slug = narrativeSlug(key);
    return runtimeFor(ownerId).memories.some(memory =>
      memory.key === slug && (!aboutId || !memory.aboutId || String(memory.aboutId) === String(aboutId))
    );
  }

  function advanceNarrativeStoryline(id, key, amount = 1, options = {}) {
    if (!id || !state.contestantById.has(id)) return null;
    const runtime = runtimeFor(id);
    const slug = narrativeSlug(key);
    const existing = runtime.storylines[slug] || {
      key: slug,
      label: options.label || String(key || slug),
      progress: 0,
      startedEpisode: state.episodeNumber,
      lastEpisode: state.episodeNumber,
      sourceEvent: options.sourceEvent || ''
    };
    existing.progress = clampRange(Number(existing.progress || 0) + Number(amount || 0), 0, 10);
    existing.lastEpisode = state.episodeNumber;
    if (options.status) existing.status = options.status;
    runtime.storylines[slug] = existing;
    return existing;
  }

  function addNarrativePromise(fromId, toId, key, options = {}) {
    if (!fromId || !toId || fromId === toId) return null;
    const runtime = runtimeFor(fromId);
    const slug = narrativeSlug(key);
    const existing = runtime.promises.find(item => item.key === slug && String(item.toId) === String(toId) && item.active !== false);
    if (existing) return existing;
    const promise = {
      key: slug,
      label: options.label || String(key || slug),
      toId,
      active: true,
      createdEpisode: state.episodeNumber,
      expiresEpisode: options.duration ? state.episodeNumber + Number(options.duration) : null,
      sourceEvent: options.sourceEvent || ''
    };
    runtime.promises.push(promise);
    runtime.promises = runtime.promises.slice(-30);
    return promise;
  }

  function hasNarrativePromise(fromId, toId, key) {
    const slug = narrativeSlug(key);
    return runtimeFor(fromId).promises.some(item =>
      item.active !== false
      && item.key === slug
      && (!toId || String(item.toId) === String(toId))
      && (!Number.isFinite(Number(item.expiresEpisode)) || state.episodeNumber <= Number(item.expiresEpisode))
    );
  }

  function addNarrativePlan(ownerId, key, options = {}) {
    if (!ownerId || !state.contestantById.has(ownerId)) return null;
    const runtime = runtimeFor(ownerId);
    const slug = narrativeSlug(key);
    if (!slug) return null;
    const aboutId = options.aboutId || '';
    const existing = runtime.plans.find(item => item.key === slug && item.active !== false && String(item.aboutId || '') === String(aboutId));
    if (existing) {
      existing.strength = clampRange(Number(existing.strength || 1) + Number(options.strength || 1), 1, 5);
      existing.lastEpisode = state.episodeNumber;
      return existing;
    }
    const plan = {
      key: slug, label: options.label || String(key || slug), aboutId, active: true,
      strength: clampRange(Number(options.strength || 1), 1, 5),
      createdEpisode: state.episodeNumber, lastEpisode: state.episodeNumber,
      expiresEpisode: options.duration ? state.episodeNumber + Number(options.duration) : state.episodeNumber + 3,
      sourceEvent: options.sourceEvent || ''
    };
    runtime.plans.push(plan);
    runtime.plans = runtime.plans.slice(-30);
    return plan;
  }

  function hasNarrativePlan(ownerId, key, aboutId = '') {
    const slug = narrativeSlug(key);
    return runtimeFor(ownerId).plans.some(item =>
      item.active !== false && item.key === slug
      && (!aboutId || !item.aboutId || String(item.aboutId) === String(aboutId))
      && (!Number.isFinite(Number(item.expiresEpisode)) || state.episodeNumber <= Number(item.expiresEpisode))
    );
  }

  function unlockEventOpportunity(key, ownerId, options = {}) {
    const slug = narrativeSlug(key);
    if (!slug || !ownerId) return null;
    state.eventOpportunities ||= [];
    const earliestEpisode = Number(options.earliestEpisode ?? state.episodeNumber);
    const expiresEpisode = Number(options.expiresEpisode ?? (earliestEpisode + Number(options.duration ?? 1)));
    const existing = state.eventOpportunities.find(item => item.active !== false && item.key === slug && String(item.ownerId) === String(ownerId));
    if (existing) {
      existing.earliestEpisode = Math.max(Number(existing.earliestEpisode || 0), earliestEpisode);
      existing.expiresEpisode = Math.max(existing.expiresEpisode, expiresEpisode);
      existing.weight = Math.max(Number(existing.weight || 1), Number(options.weight || 1));
      existing.dynamic = Boolean(existing.dynamic || options.dynamic);
      existing.tag = narrativeSlug(options.tag || existing.tag || key);
      if (options.stage) existing.stage = options.stage;
      if (options.aboutId) existing.aboutId = options.aboutId;
      return existing;
    }
    const opportunity = {
      id: `opportunity-${slug}-${ownerId}-${state.episodeNumber}-${Math.random().toString(36).slice(2, 6)}`,
      key: slug,
      tag: narrativeSlug(options.tag || key),
      ownerId,
      aboutId: options.aboutId || '',
      earliestEpisode,
      expiresEpisode,
      stage: options.stage || '',
      weight: Number(options.weight || 1),
      active: true,
      sourceEvent: options.sourceEvent || '',
      dynamic: Boolean(options.dynamic)
    };
    state.eventOpportunities.push(opportunity);
    return opportunity;
  }

  function activeEventOpportunities(key = '') {
    const slug = key ? narrativeSlug(key) : '';
    return (state.eventOpportunities || []).filter(item =>
      item.active !== false
      && (!slug || item.key === slug || item.tag === slug)
      && state.episodeNumber >= Number(item.earliestEpisode || 0)
      && state.episodeNumber <= Number(item.expiresEpisode ?? state.episodeNumber)
      && (!item.stage || item.stage === activeEpisodePanel || item.stage === 'any')
    );
  }

  function consumeEventOpportunity(opportunity) {
    if (!opportunity) return;
    opportunity.active = false;
    opportunity.consumedEpisode = state.episodeNumber;
  }

  function expireNarrativeState() {
    state.activeIds.forEach(id => {
      const runtime = runtimeFor(id);
      Object.entries(runtime.flags || {}).forEach(([key, flag]) => {
        if (Number.isFinite(Number(flag.expiresEpisode)) && state.episodeNumber > Number(flag.expiresEpisode)) delete runtime.flags[key];
      });
      runtime.promises = (runtime.promises || []).filter(item =>
        item.active !== false && (!Number.isFinite(Number(item.expiresEpisode)) || state.episodeNumber <= Number(item.expiresEpisode))
      );
      runtime.plans = (runtime.plans || []).filter(item =>
        item.active !== false && (!Number.isFinite(Number(item.expiresEpisode)) || state.episodeNumber <= Number(item.expiresEpisode))
      );
    });
    state.eventOpportunities = (state.eventOpportunities || []).filter(item =>
      item.active !== false && state.episodeNumber <= Number(item.expiresEpisode ?? state.episodeNumber)
    );
    state.narrativeMaintenanceEpisode = state.episodeNumber;
  }

  function skillToTen(value) {
    return clampRange(1 + ((Number(value) - 1) * 9 / 14), 1, 10);
  }

  function traitsFor(id) {
    const skills = effectiveSkillsFor(id);
    const hidden = effectiveHiddenFor(id);
    const runtime = runtimeFor(id);
    const h = key => skillToTen(hidden[key] ?? DEFAULT_STAT);

    const aggression = skillToTen(skills.aggression);
    const loyalty = skillToTen(skills.loyalty);
    const honesty = skillToTen(skills.honesty);
    const teamwork = skillToTen(skills.teamwork);
    const intelligence = skillToTen(skills.intelligence);
    const endurance = skillToTen(skills.endurance);
    const agility = skillToTen(skills.agility);
    const strategy = skillToTen(skills.strategy);

    const charisma = h('charisma');
    const socialAwareness = h('socialAwareness');
    const emotionalStability = h('emotionalStability');
    const entertainment = h('entertainment');
    const leadership = h('leadership');
    const deception = h('deception');
    const fearTolerance = h('fearTolerance');
    const injuryRisk = h('injuryRisk');
    const injuryResistance = h('injuryResistance');
    const allianceDependence = h('allianceDependence');
    const attentionSeeking = h('attentionSeeking');
    const conflict = h('conflict');
    const motivation = h('motivation');
    const enthusiasm = h('enthusiasm');
    const pressureSensitivity = h('pressure');
    const pressureResistance = h('pressureResistance');
    const composure = h('composure');
    const baselineConfidence = h('confidence');
    const reactions = h('reactions');
    const grossTolerance = h('grossTolerance');
    const adaptability = h('adaptability');

    return {
      sociability: clampRange((teamwork + charisma + entertainment + enthusiasm) / 4, 1, 10),
      charisma,
      socialAwareness,
      empathy: clampRange((teamwork + honesty + loyalty) / 3, 1, 10),
      humor: clampRange((entertainment + charisma) / 2, 1, 10),
      strategy,
      deception,
      leadership,
      loyalty,
      ambition: clampRange((strategy + aggression + intelligence + h('ego')) / 4, 1, 10),
      aggression,
      patience: clampRange(h('patience') - runtime.emotionalPressure / 90 - runtime.fatigue / 120, 1, 10),
      emotionalStability,
      sensitivity: clampRange(11 - emotionalStability + (pressureSensitivity - 5.5) * .35 + (h('ego') - 5.5) * .15, 1, 10),
      confidence: clampRange(5 + (runtime.confidence - 50) / 12 + (baselineConfidence - 5.5) * .45, 1, 10),
      independence: clampRange(11 - allianceDependence, 1, 10),
      dramaticness: clampRange((aggression + entertainment + attentionSeeking + conflict) / 4, 1, 10),
      workEthic: clampRange((motivation + enthusiasm + endurance + teamwork) / 4, 1, 10),
      campCompetence: clampRange((intelligence + adaptability + grossTolerance + endurance) / 4, 1, 10),
      clumsiness: clampRange(11 - (agility + reactions) / 2 + (injuryRisk - injuryResistance) * .30, 1, 10),
      fearfulness: clampRange(11 - fearTolerance, 1, 10),
      hygiene: clampRange((honesty + teamwork + h('composure')) / 3 + (runtime.hygiene - 50) / 22, 1, 10),

      adaptability,
      allianceDependence,
      attentionSeeking,
      authorityResistance: h('authorityResistance'),
      betrayal: h('betrayal'),
      baselineConfidence,
      confidenceGrowth: h('confidenceGrowth'),
      composure,
      conflict,
      consistency: h('consistency'),
      creativity: h('creativity'),
      ego: h('ego'),
      enthusiasm,
      grossTolerance,
      influence: h('influence'),
      injuryResistance,
      injuryRisk,
      intimidation: h('intimidation'),
      motivation,
      pressureSensitivity,
      pressureResistance,
      reactions,
      riskAppetite: h('riskAppetite'),
      riskCalculation: h('riskCalculation'),
      romance: h('romance'),
      subtlety: h('subtlety'),
      threat: h('threat'),
      threatManagement: h('threatManagement'),
      twistAwareness: h('twistAwareness')
    };
  }

  function teamForContestant(id) {
    return state.teams.find(team => team.members.includes(id)) || null;
  }

  function teamForCurrentEpisodeContestant(id) {
    if (state.merged) return null;
    const snapshotTeam = (state.statusSnapshot || []).find(team => (team.members || []).includes(id));
    return snapshotTeam || teamForContestant(id);
  }

  function teamRuntimeFor(teamName) {
    if (!state.teamRuntime.has(teamName)) state.teamRuntime.set(teamName, { cohesion: 50, morale: 50 });
    return state.teamRuntime.get(teamName);
  }

  function adjustTeam(teamName, key, delta) {
    if (!teamName) return 50;
    const runtime = teamRuntimeFor(teamName);
    runtime[key] = clampRange((runtime[key] ?? 50) + delta, 0, 100);
    return runtime[key];
  }

  function currentRelationship(fromId, toId) {
    return getDirectional(state.directionalRelationships, fromId, toId, 0);
  }

  function currentTrust(fromId, toId) {
    return getDirectional(state.trust, fromId, toId, 45);
  }

  function relationshipAverage(firstId, secondId) {
    return (currentRelationship(firstId, secondId) + currentRelationship(secondId, firstId)) / 2;
  }

  function averageRelationship(id, pool = state.activeIds) {
    const others = pool.filter(otherId => otherId !== id);
    if (!others.length) return 0;
    return others.reduce((sum, otherId) => sum + currentRelationship(id, otherId), 0) / others.length;
  }

  function initializeSeasonRuntime() {
    state.lateEntrantId = lateEntrantOptionEnabled() ? (elements.lateEntrantSelect?.value || state.lateEntrantId || '') : '';
    state.activeIds = startingCastIds();
    state.directionalRelationships = new Map();
    state.trust = new Map();
    state.suspicion = new Map();
    state.irritation = new Map();
    state.grudges = new Map();
    state.targetPriority = new Map();
    state.voteCommitment = new Map();
    state.votePlans = new Map();
    state.voteLandscape = null;
    state.contestantRuntime = new Map();
    state.teamRuntime = new Map();
    state.alliances = [];
    state.usedAllianceNames = [];
    state.eventHistory = [];
    state.episodeEvents = { preChallenge: [], preVote: [] };
    state.eventSnapshots = { preChallenge: null, preVote: null };
    state.sectionCheckpoints = { episodeStart: null, afterPreChallenge: null, afterChallenge: null, afterPreVote: null, afterVote: null };
    state.challengeSnapshot = null;
    state.currentChallenge = null;
    state.usedChallengeIds = [];
    state.usedIndividualChallengeIds = [];
    state.challengeResult = null;
    state.challengeRevealed = false;
    state.voteResult = null;
    state.voteRevealIndex = 0;
    state.voteCeremonyFinished = false;
    state.episodeNumber = 1;
    state.merged = false;
    state.mergedTeamName = '';
    state.usedTeamNames = state.teams.map(team => team.name);
    state.statusSnapshot = [];
    state.episodes = [];
    state.currentEpisodeIndex = 0;
    state.isHistoricalView = false;
    state.liveMergeState = null;
    state.autoSimulating = false;
    state.seasonStarted = true;
    state.finaleFormat = selectedFinaleFormat();
    state.episodeType = 'regular';
    state.mergeOpening = false;
    state.automaticEliminatedId = '';
    state.juryResult = null;
    state.juryRevealIndex = 0;
    state.juryRevealActive = false;
    state.juryRevealed = false;
    state.returnChallengeRevealed = false;
    state.seasonWinnerId = '';
    state.seasonComplete = false;
    state.finalPlacements = [];
    state.seasonOptions = readSeasonOptionsFromSetup();
    state.lateEntrantId = seasonOptionEnabled('lateEntrant') ? (elements.lateEntrantSelect?.value || state.lateEntrantId || '') : '';
    state.twistState = createInitialTwistState();
    schedulePlannedTeamSwap();
    state.episodeOutcome = createEmptyEpisodeOutcome();
    state.pendingStageEvents = { preChallenge: [], preVote: [] };
    state.pendingExile = null;
    state.eventOpportunities = [];
    state.narrativeMaintenanceEpisode = 0;
    state.idolState = {
      status: seasonOptionEnabled('immunityIdol') ? 'hidden' : 'disabled',
      holderId: '',
      foundEpisode: 0,
      foundStage: '',
      playedEpisode: 0,
      clues: {}
    };

    state.activeIds.forEach(id => runtimeFor(id));
    state.relationships.forEach((score, key) => {
      const [firstId, secondId] = key.split('::');
      const relationship = clampRange(Number(score), -10, 10);
      setDirectional(state.directionalRelationships, firstId, secondId, relationship, -10, 10);
      setDirectional(state.directionalRelationships, secondId, firstId, relationship, -10, 10);
      const startingTrust = clampRange(45 + relationship * 4, 0, 100);
      const startingSuspicion = clampRange(Math.max(0, -relationship * 5), 0, 100);
      setDirectional(state.trust, firstId, secondId, startingTrust, 0, 100);
      setDirectional(state.trust, secondId, firstId, startingTrust, 0, 100);
      setDirectional(state.suspicion, firstId, secondId, startingSuspicion, 0, 100);
      setDirectional(state.suspicion, secondId, firstId, startingSuspicion, 0, 100);
      setDirectional(state.irritation, firstId, secondId, Math.max(0, -relationship * 3), 0, 100);
      setDirectional(state.irritation, secondId, firstId, Math.max(0, -relationship * 3), 0, 100);
      setDirectional(state.grudges, firstId, secondId, Math.max(0, -relationship * 2), 0, 100);
      setDirectional(state.grudges, secondId, firstId, Math.max(0, -relationship * 2), 0, 100);
      setDirectional(state.targetPriority, firstId, secondId, 0, 0, 100);
      setDirectional(state.targetPriority, secondId, firstId, 0, 0, 100);
      setDirectional(state.voteCommitment, firstId, secondId, 0, 0, 100);
      setDirectional(state.voteCommitment, secondId, firstId, 0, 0, 100);
    });
    state.teams.forEach(team => state.teamRuntime.set(team.name, { cohesion: 50, morale: 50 }));
    state.statusSnapshot = captureStatusSnapshot();
    state.sectionCheckpoints.episodeStart = captureRuntimeSnapshot();
    resetEpisodeInterface();
    renderSeasonOverview();
    renderEpisodeSummary();
  }

  function resetEpisodeInterface() {
    if (elements.roundTitle) elements.roundTitle.textContent = `Episode ${state.episodeNumber}`;
    if (elements.preChallengeEventCount) elements.preChallengeEventCount.textContent = 'Not generated';
    if (elements.preVoteEventCount) elements.preVoteEventCount.textContent = 'Waiting for challenge';
    if (elements.generatePreChallengeEventsBtn) {
      elements.generatePreChallengeEventsBtn.textContent = 'Generate Events';
      elements.generatePreChallengeEventsBtn.disabled = false;
      elements.generatePreChallengeEventsBtn.hidden = false;
    }
    if (elements.generatePreVoteEventsBtn) {
      elements.generatePreVoteEventsBtn.textContent = 'Generate Events';
      elements.generatePreVoteEventsBtn.disabled = true;
      elements.generatePreVoteEventsBtn.hidden = false;
    }
    if (elements.continueToChallengeBtn) elements.continueToChallengeBtn.disabled = true;
    if (elements.continueToPreVoteBtn) elements.continueToPreVoteBtn.disabled = true;
    if (elements.continueToVoteBtn) elements.continueToVoteBtn.disabled = true;
    if (elements.runChallengeBtn) {
      elements.runChallengeBtn.textContent = state.episodeType === 'finale-race' ? 'Reveal Results' : 'Run Challenge';
      elements.runChallengeBtn.hidden = false;
      elements.runChallengeBtn.disabled = true;
    }
    if (elements.challengeReveal) elements.challengeReveal.hidden = true;
    resetVoteCeremonyInterface();
    renderEventBatch('preChallenge');
    renderEventBatch('preVote');
    renderChallengeBoard();
  }


  function cloneEpisodeValue(value) {
    return value == null ? value : JSON.parse(JSON.stringify(value));
  }

  function hideCompletedEpisodePresentation(record) {
    const hidden = cloneEpisodeValue(record);
    hidden.challengeRevealed = false;
    hidden.voteRevealIndex = 0;
    hidden.voteCeremonyFinished = false;
    hidden.juryRevealIndex = 0;
    hidden.juryRevealActive = false;
    hidden.juryRevealed = false;
    hidden.returnChallengeRevealed = false;
    if (hidden.episodeOutcome?.returnChallenge) hidden.episodeOutcome.returnChallenge.revealed = false;
    if (hidden.episodeOutcome?.exile) hidden.episodeOutcome.exile.votesShown = false;
    if (hidden.challengeResult) hidden.challengeResult.revealed = false;
    if (hidden.voteResult) {
      hidden.voteResult.tieShown = false;
      hidden.voteResult.revoteSafeRevealed = false;
      hidden.voteResult.eliminationRevealed = false;
      hidden.voteResult.votesShown = false;
      hidden.voteResult.ceremonyStarted = false;
      hidden.voteResult.autoRevealActive = false;
    }
    return hidden;
  }

  function ordinalPlacement(value) {
    const number = Math.max(1, Number(value) || 1);
    const mod100 = number % 100;
    const suffix = mod100 >= 11 && mod100 <= 13
      ? 'th'
      : ({ 1: 'st', 2: 'nd', 3: 'rd' }[number % 10] || 'th');
    return `${number}${suffix}`;
  }

  function episodeEliminatedIds(record) {
    const ids = [];
    (record?.episodeOutcome?.departures || []).forEach(item => ids.push(item.id));
    if (record?.automaticEliminatedId) ids.push(record.automaticEliminatedId);
    if (!record?.voteResult?.noElimination) {
      (record?.voteResult?.eliminatedIds || [record?.voteResult?.eliminatedId]).filter(Boolean).forEach(id => ids.push(id));
    }
    return [...new Set(ids.filter(Boolean))];
  }

  function eliminatedBeforeCurrentEpisode() {
    const departed = [];
    [...state.episodes]
      .filter(record => Number(record.number || 0) < Number(state.episodeNumber || 0))
      .sort((first, second) => Number(first.number || 0) - Number(second.number || 0))
      .forEach(record => {
        (record.episodeOutcome?.arrivals || []).forEach(arrival => {
          const index = departed.indexOf(arrival.id);
          if (index >= 0) departed.splice(index, 1);
        });
        episodeEliminatedIds(record).forEach(id => {
          const previousIndex = departed.indexOf(id);
          if (previousIndex >= 0) departed.splice(previousIndex, 1);
          departed.push(id);
        });
      });
    return departed.filter(id => !state.activeIds.includes(id));
  }

  function captureStatusSnapshot() {
    if (state.merged) {
      return [{
        name: state.mergedTeamName || 'Merged Team',
        members: [...state.activeIds]
      }];
    }
    return state.teams
      .map(team => ({
        name: team.name,
        members: team.members.filter(id => state.activeIds.includes(id))
      }))
      .filter(team => team.members.length > 0);
  }

  function clearEpisodeProgress() {
    state.episodeEvents = { preChallenge: [], preVote: [] };
    state.eventSnapshots = { preChallenge: null, preVote: null };
    state.sectionCheckpoints = { episodeStart: null, afterPreChallenge: null, afterChallenge: null, afterPreVote: null, afterVote: null };
    state.challengeSnapshot = null;
    state.currentChallenge = null;
    state.challengeResult = null;
    state.challengeRevealed = false;
    state.voteResult = null;
    state.voteRevealIndex = 0;
    state.voteCeremonyFinished = false;
    state.automaticEliminatedId = '';
    state.juryResult = null;
    state.juryRevealIndex = 0;
    state.juryRevealActive = false;
    state.juryRevealed = false;
    state.returnChallengeRevealed = false;
    state.seasonWinnerId = '';
    state.seasonComplete = false;
    state.finalPlacements = [];
    state.episodeOutcome = createEmptyEpisodeOutcome();
    state.pendingStageEvents = { preChallenge: [], preVote: [] };
    state.votePlans = new Map();
    state.voteLandscape = null;
    [...state.voteCommitment.keys()].forEach(key => state.voteCommitment.set(key, 0));
    state.statusSnapshot = captureStatusSnapshot();
    if (!state.autoSimulating) state.sectionCheckpoints.episodeStart = captureRuntimeSnapshot();
    if (!state.autoSimulating) resetEpisodeInterface();
  }

  function recoverBetweenEpisodes() {
    state.activeIds.forEach(id => {
      const runtime = runtimeFor(id);
      const hidden = effectiveHiddenFor(id);
      const recovery = clampRange(Number(hidden.recovery ?? DEFAULT_STAT), 1, 15);
      const pressureResistance = clampRange(Number(hidden.pressureResistance ?? DEFAULT_STAT), 1, 15);
      const composure = clampRange(Number(hidden.composure ?? DEFAULT_STAT), 1, 15);
      const motivation = clampRange(Number(hidden.motivation ?? DEFAULT_STAT), 1, 15);
      const enthusiasm = clampRange(Number(hidden.enthusiasm ?? DEFAULT_STAT), 1, 15);
      const confidenceTarget = clampRange(50 + (Number(hidden.confidence ?? DEFAULT_STAT) - 8) * 4, 28, 72);

      const fatigueRecovery = randomInteger(7, 12) + (recovery - 8) * .75;
      const pressureRecovery = randomInteger(3, 7) + (pressureResistance - 8) * .45 + (composure - 8) * .25;
      const quitRecovery = randomInteger(1, 4) + (motivation - 8) * .32;
      runtime.fatigue = clampRange(runtime.fatigue - fatigueRecovery, 0, 100);
      runtime.emotionalPressure = clampRange(runtime.emotionalPressure - Math.max(.5, pressureRecovery), 0, 100);
      runtime.confidence = nudgeToward(runtime.confidence, confidenceTarget, 1.0);
      if (runtime.morale < 50) runtime.morale = clampRange(runtime.morale + randomInteger(1, 4) + Math.max(0, enthusiasm - 8) * .2, 0, 100);
      else if (runtime.morale > 58) runtime.morale = clampRange(runtime.morale - randomInteger(0, 2), 0, 100);
      runtime.quitRisk = clampRange(runtime.quitRisk - Math.max(.5, quitRecovery), 0, 100);
    });
  }

  function episodeRecord(completed = false) {
    const record = {
      number: state.episodeNumber,
      merged: Boolean(state.merged),
      completed: Boolean(completed),
      episodeType: state.episodeType || 'regular',
      finaleFormat: state.finaleFormat || 'final-two-race',
      mergeOpening: Boolean(state.mergeOpening),
      mergedTeamName: state.mergedTeamName || '',
      statusTeams: cloneEpisodeValue(state.statusSnapshot || captureStatusSnapshot()),
      episodeEvents: cloneEpisodeValue(state.episodeEvents),
      currentChallenge: state.currentChallenge,
      challengeResult: cloneEpisodeValue(state.challengeResult),
      challengeRevealed: Boolean(state.challengeRevealed),
      voteResult: cloneEpisodeValue(state.voteResult),
      voteRevealIndex: Number(state.voteRevealIndex || 0),
      voteCeremonyFinished: Boolean(state.voteCeremonyFinished),
      automaticEliminatedId: state.automaticEliminatedId || '',
      episodeOutcome: cloneEpisodeValue(state.episodeOutcome || createEmptyEpisodeOutcome()),
      exiledIds: state.episodeOutcome?.exile?.id ? [state.episodeOutcome.exile.id] : [],
      idolStateSnapshot: cloneEpisodeValue(state.idolState),
      juryResult: cloneEpisodeValue(state.juryResult),
      juryRevealIndex: Number(state.juryRevealIndex || 0),
      juryRevealActive: false,
      juryRevealed: Boolean(state.juryRevealed),
      returnChallengeRevealed: Boolean(state.returnChallengeRevealed),
      seasonWinnerId: state.seasonWinnerId || '',
      seasonComplete: Boolean(state.seasonComplete),
      finalPlacements: [...(state.finalPlacements || [])],
      endActiveIds: [...state.activeIds]
    };
    if (completed) record.edgic = buildEpisodeEdgic(record);
    return record;
  }

  function syncCurrentEpisodeRecord() {
    if (!state.episodes.length) return;
    const record = state.episodes[state.currentEpisodeIndex];
    if (!record || record.number !== state.episodeNumber) return;

    if (state.isHistoricalView) {
      record.challengeRevealed = Boolean(state.challengeRevealed);
      record.voteRevealIndex = Number(state.voteRevealIndex || 0);
      record.voteCeremonyFinished = Boolean(state.voteCeremonyFinished);
      record.juryRevealIndex = Number(state.juryRevealIndex || 0);
      record.juryRevealActive = false;
      record.juryRevealed = Boolean(state.juryRevealed);
      record.returnChallengeRevealed = Boolean(state.returnChallengeRevealed);
      if (record.episodeOutcome?.returnChallenge) record.episodeOutcome.returnChallenge.revealed = Boolean(state.returnChallengeRevealed);
      if (record.episodeOutcome?.exile && state.episodeOutcome?.exile) record.episodeOutcome.exile.votesShown = Boolean(state.episodeOutcome.exile.votesShown);
      record.seasonWinnerId = state.seasonWinnerId || record.seasonWinnerId || '';
      record.seasonComplete = Boolean(state.seasonComplete || record.seasonComplete);
      if (record.challengeResult && state.challengeResult) {
        record.challengeResult.revealed = Boolean(state.challengeRevealed);
      }
      if (record.voteResult && state.voteResult) {
        record.voteResult.tieShown = Boolean(state.voteResult.tieShown);
        record.voteResult.revoteSafeRevealed = Boolean(state.voteResult.revoteSafeRevealed);
        record.voteResult.eliminationRevealed = Boolean(state.voteResult.eliminationRevealed);
        record.voteResult.votesShown = Boolean(state.voteResult.votesShown);
        record.voteResult.ceremonyStarted = Boolean(state.voteResult.ceremonyStarted);
        record.voteResult.autoRevealActive = false;
      }
      updateRoundSelect();
      return;
    }

    const updated = episodeRecord(Boolean(
      state.voteResult?.eliminationRevealed
      || ((state.episodeType === 'finale-race' || state.episodeType === 'return-challenge' || state.episodeOutcome?.cancelVote) && state.challengeRevealed)
      || (state.juryResult && state.juryRevealed)
    ));
    state.episodes[state.currentEpisodeIndex] = updated;
    state.liveMergeState = cloneEpisodeValue(updated);
    updateRoundSelect();
  }

  function updateRoundSelect() {
    if (!elements.roundSelect) return;
    const currentIndex = state.currentEpisodeIndex;
    elements.roundSelect.replaceChildren();
    state.episodes.forEach((record, index) => {
      const option = document.createElement('option');
      option.value = String(index);
      option.textContent = `Episode ${record.number}`;
      elements.roundSelect.append(option);
    });
    elements.roundSelect.value = String(Math.max(0, Math.min(currentIndex, state.episodes.length - 1)));
  }

  function applyEpisodeRecord(record) {
    state.episodeNumber = record.number;
    state.merged = Boolean(record.merged);
    state.episodeType = record.episodeType || 'regular';
    state.finaleFormat = record.finaleFormat || state.finaleFormat || 'final-two-race';
    state.mergeOpening = Boolean(record.mergeOpening);
    state.mergedTeamName = record.mergedTeamName || '';
    state.statusSnapshot = cloneEpisodeValue(record.statusTeams || []);
    state.episodeEvents = cloneEpisodeValue(record.episodeEvents || { preChallenge: [], preVote: [] });
    state.currentChallenge = record.currentChallenge || null;
    state.challengeResult = cloneEpisodeValue(record.challengeResult);
    state.challengeRevealed = Boolean(record.challengeRevealed);
    state.voteResult = cloneEpisodeValue(record.voteResult);
    state.voteRevealIndex = Number(record.voteRevealIndex || 0);
    state.voteCeremonyFinished = Boolean(record.voteCeremonyFinished);
    state.automaticEliminatedId = record.automaticEliminatedId || '';
    state.episodeOutcome = cloneEpisodeValue(record.episodeOutcome || createEmptyEpisodeOutcome());
    state.idolState = cloneEpisodeValue(record.idolStateSnapshot || state.idolState);
    state.juryResult = cloneEpisodeValue(record.juryResult);
    state.juryRevealIndex = Number(record.juryRevealIndex || 0);
    state.juryRevealActive = false;
    state.juryRevealed = Boolean(record.juryRevealed);
    state.returnChallengeRevealed = Boolean(record.returnChallengeRevealed || record.episodeOutcome?.returnChallenge?.revealed);
    state.seasonWinnerId = record.seasonWinnerId || '';
    state.seasonComplete = Boolean(record.seasonComplete);
    state.finalPlacements = [...(record.finalPlacements || [])];
    state.activeIds = [...(record.endActiveIds || state.activeIds)];
    if (state.voteResult?.eliminationRevealed) {
      state.voteRevealIndex = state.voteResult.safeOrder?.length || 0;
      state.voteResult.ceremonyStarted = true;
      state.voteResult.autoRevealActive = false;
      if (state.voteResult.hadInitialTie) {
        state.voteResult.tieShown = true;
        state.voteResult.revoteSafeRevealed = true;
      }
    }
  }

  function episodeHasChallengeStage() {
    return state.episodeType !== 'finale-jury';
  }

  function episodeHasVoteStage() {
    if (state.episodeType === 'finale-race' || state.episodeType === 'finale-jury' || state.episodeType === 'return-challenge') return false;
    return !state.episodeOutcome?.cancelVote;
  }

  function juryFinaleUnlocked() {
    if (!state.juryResult) return false;
    if (state.episodeType === 'semifinal-sole-vote') return Boolean(state.voteResult?.eliminationRevealed);
    return true;
  }

  function currentEpisodeCompletionRevealed() {
    if (state.episodeType === 'finale-race' || state.episodeType === 'return-challenge' || state.episodeOutcome?.cancelVote) return Boolean(state.challengeRevealed);
    if (state.episodeType === 'finale-jury') return Boolean(state.juryRevealed);
    if (state.juryResult) return Boolean(state.voteResult?.eliminationRevealed && state.juryRevealed);
    return Boolean(state.voteResult?.eliminationRevealed);
  }

  function renderReturnChallengeSection() {
    const result = state.episodeOutcome?.returnChallenge;
    if (elements.returnChallengeStageTab) elements.returnChallengeStageTab.hidden = !result;
    if (!result) {
      if (elements.returnChallengeCompetitorGrid) elements.returnChallengeCompetitorGrid.replaceChildren();
      if (elements.returnChallengeResultArea) {
        elements.returnChallengeResultArea.replaceChildren();
        elements.returnChallengeResultArea.hidden = true;
      }
      return;
    }
    if (elements.returnChallengeIntroduction) {
      elements.returnChallengeIntroduction.textContent = '“Eliminated campers, one of you is getting another chance! Complete this recycled nightmare course, reach the camp gate first, and you are officially back in the game. Everybody else gets eliminated twice!”';
    }
    if (elements.returnChallengeCompetitorGrid) {
      elements.returnChallengeCompetitorGrid.replaceChildren();
      (result.competitors || []).forEach(id => {
        const card = document.createElement('article');
        card.className = 'return-challenge-competitor-card';
        card.append(ceremonyPortrait(id));
        const name = document.createElement('strong');
        name.textContent = contestantDisplayName(id);
        card.append(name);
        elements.returnChallengeCompetitorGrid.append(card);
      });
    }
    if (elements.revealReturnChallengeBtn) {
      elements.revealReturnChallengeBtn.hidden = Boolean(state.returnChallengeRevealed);
      elements.revealReturnChallengeBtn.disabled = Boolean(state.returnChallengeRevealed);
    }
    if (elements.returnChallengeResultArea) {
      elements.returnChallengeResultArea.replaceChildren();
      elements.returnChallengeResultArea.hidden = !state.returnChallengeRevealed;
      if (state.returnChallengeRevealed) {
        const card = document.createElement('article');
        card.className = 'return-challenge-winner-card';
        card.append(ceremonyPortrait(result.winnerId));
        const copy = document.createElement('div');
        const label = document.createElement('span');
        label.textContent = 'BACK IN THE GAME';
        const name = document.createElement('strong');
        name.textContent = contestantDisplayName(result.winnerId);
        const detail = document.createElement('p');
        detail.textContent = result.teamName
          ? `${contestantDisplayName(result.winnerId)} wins the gauntlet and returns on ${result.teamName}.`
          : `${contestantDisplayName(result.winnerId)} wins the gauntlet and returns to the individual game.`;
        copy.append(label, name, detail);
        card.append(copy);
        elements.returnChallengeResultArea.append(card);
      }
    }
    if (elements.returnChallengeBackBtn) elements.returnChallengeBackBtn.dataset.openPanel = state.mergeOpening ? 'merge' : 'overview';
    if (elements.continueFromReturnChallengeBtn) elements.continueFromReturnChallengeBtn.disabled = !state.returnChallengeRevealed;
  }

  function renderEpisodeRecord() {
    if (elements.roundTitle) elements.roundTitle.textContent = `Episode ${state.episodeNumber}`;
    if (elements.roundSubline) {
      elements.roundSubline.textContent = state.episodeType === 'finale-race'
        ? 'The final race'
        : state.episodeType === 'finale-jury'
          ? 'The jury decides the winner'
          : state.episodeType === 'final-four-showdown'
            ? 'Four campers, two finalist spots'
            : state.mergeOpening ? 'The individual game begins' : 'Camp status';
    }
    if (elements.mergeStageTab) elements.mergeStageTab.hidden = !state.mergeOpening;
    if (elements.returnChallengeStageTab) elements.returnChallengeStageTab.hidden = !state.episodeOutcome?.returnChallenge;
    if (elements.voteStageTab) elements.voteStageTab.hidden = !episodeHasVoteStage();
    if (elements.finaleStageTab) elements.finaleStageTab.hidden = !juryFinaleUnlocked();

    const preChallengeTab = document.querySelector('.section-toggle[data-panel-target="pre-challenge"]');
    const challengeTab = document.querySelector('.section-toggle[data-panel-target="challenge"]');
    const preVoteTab = document.querySelector('.section-toggle[data-panel-target="pre-vote"]');
    if (preChallengeTab) preChallengeTab.hidden = false;
    if (challengeTab) challengeTab.hidden = !episodeHasChallengeStage();
    if (preVoteTab) preVoteTab.hidden = !episodeHasVoteStage();

    const overviewProceed = document.querySelector('[data-panel="overview"] [data-open-panel]');
    if (overviewProceed) {
      overviewProceed.dataset.openPanel = state.mergeOpening
        ? 'merge'
        : state.episodeOutcome?.returnChallenge ? 'return-challenge' : 'pre-challenge';
      overviewProceed.textContent = state.episodeType === 'finale-jury'
        ? 'Begin the Jury Finale'
        : state.mergeOpening ? 'See the Merge'
          : state.episodeOutcome?.returnChallenge ? 'Begin the Return Challenge' : 'Begin Camp Life';
    }
    if (elements.mergeContinueBtn) {
      elements.mergeContinueBtn.dataset.openPanel = state.episodeOutcome?.returnChallenge ? 'return-challenge' : 'pre-challenge';
      elements.mergeContinueBtn.textContent = state.episodeOutcome?.returnChallenge ? 'Begin the Return Challenge' : 'Begin the Individual Game';
    }
    if (elements.preChallengeBackBtn) {
      elements.preChallengeBackBtn.dataset.openPanel = state.episodeOutcome?.returnChallenge
        ? 'return-challenge'
        : state.mergeOpening ? 'merge' : 'overview';
    }

    renderSeasonOverview();
    renderMergePanel();
    renderReturnChallengeSection();
    renderEventBatch('preChallenge');
    renderEventBatch('preVote');
    if (episodeHasChallengeStage()) {
      renderChallengeBoard();
    } else {
      if (elements.challengeEyebrow) elements.challengeEyebrow.textContent = 'Final jury decision';
      if (elements.challengeName) elements.challengeName.textContent = 'No Final Challenge';
      if (elements.challengeIntroduction) elements.challengeIntroduction.textContent = 'The finalists have reached the end. The merged contestants they helped eliminate will decide the winner.';
      if (elements.challengeReveal) elements.challengeReveal.hidden = true;
      if (elements.challengeTeamBoard) elements.challengeTeamBoard.replaceChildren();
      if (elements.challengeExileArea) {
        elements.challengeExileArea.replaceChildren();
        elements.challengeExileArea.hidden = true;
      }
      if (elements.runChallengeBtn) elements.runChallengeBtn.hidden = true;
    }
    if (state.voteResult) renderVotingCeremony();
    else resetVoteCeremonyInterface();
    renderFinalePanel();
    renderEpisodeSummary();
    applyEpisodeControlState();
  }

  function applyEpisodeControlState() {
    const readOnly = state.isHistoricalView;
    if (elements.generatePreChallengeEventsBtn) elements.generatePreChallengeEventsBtn.hidden = readOnly || Boolean(state.episodeEvents.preChallenge.length);
    if (elements.revealReturnChallengeBtn) elements.revealReturnChallengeBtn.disabled = Boolean(state.returnChallengeRevealed);
    if (elements.continueFromReturnChallengeBtn) elements.continueFromReturnChallengeBtn.disabled = !state.returnChallengeRevealed;
    if (elements.generatePreVoteEventsBtn) elements.generatePreVoteEventsBtn.hidden = readOnly || Boolean(state.episodeEvents.preVote.length) || !episodeHasVoteStage();
    if (elements.runChallengeBtn) {
      elements.runChallengeBtn.textContent = state.episodeType === 'finale-race' ? 'Reveal Results' : 'Run Challenge';
      elements.runChallengeBtn.hidden = !episodeHasChallengeStage() || Boolean(state.challengeRevealed);
    }
    if (elements.continueToChallengeBtn) {
      const juryFinale = state.episodeType === 'finale-jury';
      elements.continueToChallengeBtn.dataset.openPanel = juryFinale ? 'finale' : 'challenge';
      elements.continueToChallengeBtn.textContent = juryFinale ? 'Continue to Jury Vote' : 'Continue to Challenge';
      elements.continueToChallengeBtn.disabled = !state.episodeEvents.preChallenge.length;
    }

    if (elements.continueToPreVoteBtn) {
      const challengeOnly = state.episodeType === 'finale-race' || state.episodeType === 'return-challenge' || Boolean(state.episodeOutcome?.cancelVote);
      elements.continueToPreVoteBtn.dataset.openPanel = challengeOnly ? 'summary' : 'pre-vote';
      elements.continueToPreVoteBtn.textContent = state.episodeType === 'finale-race'
        ? 'View Finale Summary'
        : state.episodeType === 'return-challenge' ? 'View Comeback Result'
          : state.episodeOutcome?.cancelVote ? 'View Episode Summary' : 'Continue to Camp';
      elements.continueToPreVoteBtn.disabled = !state.challengeRevealed
        || Boolean(state.episodeOutcome?.exile?.id && !state.episodeOutcome.exile.votesShown);
    }

    if (elements.continueToVoteBtn) elements.continueToVoteBtn.disabled = !state.episodeEvents.preVote.length;
    if (elements.continueToSummaryBtn) elements.continueToSummaryBtn.disabled = !state.voteResult?.eliminationRevealed;
    if (elements.proceedEpisodeBtn) {
      elements.proceedEpisodeBtn.disabled = !currentEpisodeCompletionRevealed();
      elements.proceedEpisodeBtn.textContent = state.currentEpisodeIndex < state.episodes.length - 1 ? 'Proceed' : 'View Statistics';
    }
    if (elements.finaleStageTab) elements.finaleStageTab.hidden = !juryFinaleUnlocked();
    if (elements.revealFinaleResultBtn) {
      elements.revealFinaleResultBtn.textContent = state.juryRevealActive ? 'Revealing Votes…' : 'Reveal Results';
      elements.revealFinaleResultBtn.disabled = !juryFinaleUnlocked() || Boolean(state.juryRevealed) || Boolean(state.juryRevealActive);
      elements.revealFinaleResultBtn.hidden = !state.juryResult || Boolean(state.juryRevealed);
    }
    if (elements.finaleToSummaryBtn) elements.finaleToSummaryBtn.disabled = !state.juryRevealed;
  }

  function activateEpisode(index) {
    if (!state.episodes.length) return;
    finaleRevealToken += 1;
    state.juryRevealActive = false;
    if (!state.isHistoricalView) syncCurrentEpisodeRecord();
    const safeIndex = Math.max(0, Math.min(Number(index) || 0, state.episodes.length - 1));
    const record = state.episodes[safeIndex];
    state.currentEpisodeIndex = safeIndex;
    state.isHistoricalView = Boolean(record.completed && safeIndex !== state.episodes.length - 1) || Boolean(record.completed && !record.merged);
    applyEpisodeRecord(record);
    updateRoundSelect();
    renderEpisodeRecord();
    openEpisodePanel('overview');
  }

  function nextUnusedMergedTeamName() {
    const unused = TEAM_OPTIONS.filter(team => !state.usedTeamNames.includes(team.name));
    const selected = (unused.length ? unused : TEAM_OPTIONS)[randomInteger(0, (unused.length ? unused : TEAM_OPTIONS).length - 1)];
    if (selected && !state.usedTeamNames.includes(selected.name)) state.usedTeamNames.push(selected.name);
    return selected?.name || 'Merged Misfits';
  }

  function renderMergePanel() {
    if (elements.mergeHostImage) setStaticImageFallback(elements.mergeHostImage, ['images/chris.webp', '../images/chris.webp']);
    if (elements.mergeAnnouncementText) {
      elements.mergeAnnouncementText.textContent = state.merged
        ? '“Congratulations, campers! You have officially survived the team phase, which means your teammates are no longer your problem—now everybody is your problem. From this point on, challenges are individual, immunity protects exactly one of you, and every camper gets a vote. Welcome to the merge!”'
        : '';
    }
    if (elements.mergeTeamName) elements.mergeTeamName.textContent = state.mergedTeamName || 'Merged Team';
    if (!elements.mergeContestantGrid) return;
    elements.mergeContestantGrid.replaceChildren();
    if (!state.merged) return;
    const mergeIds = [...new Set(
      (state.statusSnapshot?.length
        ? state.statusSnapshot.flatMap(team => team.members || [])
        : state.activeIds)
    )];
    mergeIds.forEach(id => {
      const contestant = state.contestantById.get(id);
      if (!contestant) return;
      const card = document.createElement('article');
      card.className = 'merge-contestant-card';
      const image = document.createElement('img');
      image.alt = contestant.fullName || contestant.nickname || 'Contestant';
      setImageWithFallback(image, contestant);
      const name = document.createElement('strong');
      name.textContent = contestantDisplayName(id);
      card.append(image, name);
      elements.mergeContestantGrid.append(card);
    });
  }

  function completePrecomputedChallenge() {
    const challenge = prepareChallengeResult();
    if (!challenge) return null;
    state.challengeRevealed = true;
    challenge.revealed = true;
    applyChallengeEffects();
    return challenge;
  }

  function completePrecomputedVote() {
    const vote = prepareVoteResult();
    if (!vote) return null;
    vote.ceremonyStarted = true;
    vote.autoRevealActive = false;
    vote.tieShown = Boolean(vote.hadInitialTie);
    vote.revoteSafeRevealed = Boolean(vote.hadInitialTie);
    vote.eliminationRevealed = true;
    state.voteRevealIndex = vote.safeOrder.length;
    finalizeVoteElimination();
    return vote;
  }

  function storePrecomputedEpisode() {
    state.autoSimulating = false;
    state.episodes.push(hideCompletedEpisodePresentation(episodeRecord(true)));
  }

  function advanceSimulationEpisode() {
    recoverBetweenEpisodes();
    state.episodeNumber += 1;
  }

  function returnChallengeDue() {
    if (!seasonOptionEnabled('returnChallenge') || state.twistState?.completed?.returnChallenge) return false;
    if (state.episodeNumber < 7 || state.activeIds.length <= 6 || eligibleReturneeIds().length < 3) return false;
    if (state.twistState?.returnEpisode && state.episodeNumber - state.twistState.returnEpisode < 3) return false;
    return canTriggerMajorTwist();
  }

  function resolveReturnChallengeForEpisode() {
    if (!returnChallengeDue()) return null;
    const competitors = eligibleReturneeIds();
    if (!competitors.length) {
      state.twistState.completed.returnChallenge = true;
      return null;
    }
    const scored = competitors.map(id => ({
      id,
      score: Object.entries(RETURN_CHALLENGE.skills).reduce((total, [key, weight]) => total + Number(currentSkill(id, key) || DEFAULT_STAT) * weight, 0)
        + randomInteger(1, 15) * .22
        + runtimeFor(id).confidence * .025,
      tieBreaker: Math.random()
    })).sort((first, second) => second.score - first.score || second.tieBreaker - first.tieBreaker);
    const winnerId = scored[0]?.id || '';
    const performances = Object.fromEntries(scored.map(entry => [entry.id, clampRange(((entry.score - 1) / 14) * 100, 0, 100)]));
    const arrival = addContestantToGame(winnerId, 'return-challenge');
    const result = {
      challengeId: RETURN_CHALLENGE.id,
      competitors: scored.map(entry => entry.id),
      rankedIds: scored.map(entry => entry.id),
      winnerId,
      performances,
      teamName: arrival?.teamName || '',
      revealed: false
    };
    state.episodeOutcome.returnChallenge = result;
    state.returnChallengeRevealed = false;
    recordMajorTwist('returnChallenge');
    state.twistState.returnChallengeEpisode = state.episodeNumber;
    return result;
  }

  function simulateOneStandardEpisode({ merged = false, mergeOpening = false } = {}) {
    state.merged = Boolean(merged);
    state.mergeOpening = Boolean(mergeOpening);
    state.episodeType = 'regular';
    state.autoSimulating = true;
    clearEpisodeProgress();
    state.episodeType = 'regular';
    if (!state.merged) maybeApplyTeamSwap();
    resolveReturnChallengeForEpisode();
    prepareEpisodeOpeningTwists({ mergeOpening });
    state.statusSnapshot = captureStatusSnapshot();
    chooseEpisodeStructuralTwist();
    generateEventBatch('preChallenge');
    completePrecomputedChallenge();
    resolveAfterChallengeTwists();
    generateEventBatch('preVote');
    completePrecomputedVote();
    storePrecomputedEpisode();
    advanceSimulationEpisode();
  }

  function simulateOneTeamEpisode() {
    simulateOneStandardEpisode({ merged: false, mergeOpening: false });
  }

  function simulateSoleVoteSemifinal({ juryFinale = false } = {}) {
    state.merged = true;
    state.mergeOpening = false;
    state.episodeType = 'semifinal-sole-vote';
    state.autoSimulating = true;
    clearEpisodeProgress();
    state.episodeType = 'semifinal-sole-vote';
    generateEventBatch('preChallenge');
    completePrecomputedChallenge();
    generateEventBatch('preVote');
    const vote = completePrecomputedVote();

    storePrecomputedEpisode();
    advanceSimulationEpisode();
    if (juryFinale) {
      simulateFinalJuryEpisode();
    } else {
      simulateFinalRaceEpisode();
    }
  }

  function simulateFinalFourShowdown() {
    state.merged = true;
    state.mergeOpening = false;
    state.episodeType = 'final-four-showdown';
    state.autoSimulating = true;
    clearEpisodeProgress();
    state.episodeType = 'final-four-showdown';
    generateEventBatch('preChallenge');
    const challenge = completePrecomputedChallenge();
    state.automaticEliminatedId = challenge?.rankedIds?.at(-1) || '';
    applyAutomaticElimination(state.automaticEliminatedId);
    generateEventBatch('preVote');
    completePrecomputedVote();
    storePrecomputedEpisode();
    advanceSimulationEpisode();
    simulateFinalRaceEpisode();
  }

  function simulateFinalRaceEpisode() {
    state.merged = true;
    state.mergeOpening = false;
    state.episodeType = 'finale-race';
    state.autoSimulating = true;
    clearEpisodeProgress();
    state.episodeType = 'finale-race';
    selectFinalRaceChallenge();
    generateEventBatch('preChallenge');
    const challenge = completePrecomputedChallenge();
    state.seasonWinnerId = challenge?.individualWinner || challenge?.winner || state.activeIds[0] || '';
    state.seasonComplete = true;
    state.finalPlacements = [...(challenge?.rankedIds || state.activeIds)];
    storePrecomputedEpisode();
  }

  function simulateFinalJuryEpisode() {
    state.merged = true;
    state.mergeOpening = false;
    state.episodeType = 'finale-jury';
    state.autoSimulating = true;
    clearEpisodeProgress();
    state.episodeType = 'finale-jury';
    generateEventBatch('preChallenge');
    const finalists = [...state.activeIds];
    state.juryResult = buildJuryResult(finalists);
    state.juryRevealIndex = 0;
    state.juryRevealActive = false;
    state.juryRevealed = false;
    state.seasonWinnerId = state.juryResult.winnerId;
    state.seasonComplete = true;
    state.finalPlacements = [
      state.seasonWinnerId,
      ...finalists
        .filter(id => id !== state.seasonWinnerId)
        .sort((first, second) =>
          Number(state.juryResult.tally[second] || 0) - Number(state.juryResult.tally[first] || 0)
          || finalistMeritScore(second) - finalistMeritScore(first)
        )
    ];
    storePrecomputedEpisode();
  }

  function simulateFinalThreeJuryEpisode() {
    simulateFinalJuryEpisode();
  }

  function simulateSeasonToFinale() {
    const mergeTarget = Number(elements.mergeAt?.value || 9);
    let safety = Math.max(24, state.selectedIds.length + 42);
    while (state.activeIds.length > mergeTarget && safety > 0) {
      simulateOneTeamEpisode();
      safety -= 1;
    }

    state.merged = true;
    state.mergedTeamName = nextUnusedMergedTeamName();
    const regularStop = finaleTargetCount(state.finaleFormat);
    let mergeOpening = true;
    while (state.activeIds.length > regularStop && safety > 0) {
      simulateOneStandardEpisode({ merged: true, mergeOpening });
      mergeOpening = false;
      safety -= 1;
    }

    if (state.finaleFormat === 'final-two-race') {
      simulateSoleVoteSemifinal({ juryFinale: false });
    } else if (state.finaleFormat === 'final-two-jury') {
      simulateSoleVoteSemifinal({ juryFinale: true });
    } else if (state.finaleFormat === 'final-three-race') {
      simulateFinalRaceEpisode();
    } else if (state.finaleFormat === 'final-three-jury') {
      simulateFinalThreeJuryEpisode();
    } else if (state.finaleFormat === 'final-four-showdown') {
      simulateFinalFourShowdown();
    }

    state.currentEpisodeIndex = 0;
    state.isHistoricalView = false;
    updateRoundSelect();
  }

  async function simulateSeasonToFinaleAsync(onProgress = () => {}) {
    const total = seasonPreparationEstimate();
    const report = message => onProgress(message, state.episodes.length, total);
    const runEpisode = async (message, callback) => {
      report(message);
      await yieldSeasonPreparation();
      callback();
      onProgress(`Finished ${state.episodes.length} of about ${total} episodes…`, state.episodes.length, total);
      await yieldSeasonPreparation();
    };

    const mergeTarget = Number(elements.mergeAt?.value || 9);
    let safety = Math.max(24, state.selectedIds.length + 42);
    while (state.activeIds.length > mergeTarget && safety > 0) {
      await runEpisode(`Simulating Episode ${state.episodeNumber}: team challenge…`, simulateOneTeamEpisode);
      safety -= 1;
    }

    state.merged = true;
    state.mergedTeamName = nextUnusedMergedTeamName();
    const regularStop = finaleTargetCount(state.finaleFormat);
    let mergeOpening = true;
    while (state.activeIds.length > regularStop && safety > 0) {
      const isMerge = mergeOpening;
      await runEpisode(
        isMerge ? `Simulating Episode ${state.episodeNumber}: the merge…` : `Simulating Episode ${state.episodeNumber}: individual game…`,
        () => simulateOneStandardEpisode({ merged: true, mergeOpening: isMerge })
      );
      mergeOpening = false;
      safety -= 1;
    }

    if (state.finaleFormat === 'final-two-race') {
      await runEpisode('Simulating the semifinal and final race…', () => simulateSoleVoteSemifinal({ juryFinale: false }));
    } else if (state.finaleFormat === 'final-two-jury') {
      await runEpisode('Simulating the semifinal and final jury decision…', () => simulateSoleVoteSemifinal({ juryFinale: true }));
    } else if (state.finaleFormat === 'final-three-race') {
      await runEpisode('Simulating the final race…', simulateFinalRaceEpisode);
    } else if (state.finaleFormat === 'final-three-jury') {
      await runEpisode('Simulating the final jury decision…', simulateFinalThreeJuryEpisode);
    } else if (state.finaleFormat === 'final-four-showdown') {
      await runEpisode('Simulating the Final Four Showdown and final race…', simulateFinalFourShowdown);
    }

    state.currentEpisodeIndex = 0;
    state.isHistoricalView = false;
    updateRoundSelect();
  }

  function simulateSeasonToMerge() {
    simulateSeasonToFinale();
  }

  function renderSeasonOverview() {
    if (!elements.seasonTeamOverview) return;
    elements.seasonTeamOverview.replaceChildren();
    const snapshotTeams = state.statusSnapshot?.length ? state.statusSnapshot : captureStatusSnapshot();
    const activeTeamGrid = document.createElement('div');
    activeTeamGrid.className = 'season-active-team-grid';
    activeTeamGrid.style.setProperty('--status-team-count', String(Math.max(1, snapshotTeams.length)));
    elements.seasonTeamOverview.append(activeTeamGrid);
    snapshotTeams.forEach(team => {
      const data = teamOption(team.name);
      const card = document.createElement('article');
      card.className = 'season-team-card';
      card.style.setProperty('--team-color', data.color);

      const head = document.createElement('div');
      head.className = 'season-team-card-head';
      const emblem = document.createElement('img');
      emblem.className = 'season-team-emblem';
      emblem.alt = `${team.name} emblem`;
      setTeamEmblemWithFallback(emblem, data);
      const title = document.createElement('h3');
      title.textContent = team.name;
      head.append(emblem, title);

      const members = document.createElement('div');
      members.className = 'season-team-members';
      team.members.forEach(id => {
        const contestant = state.contestantById.get(id);
        if (!contestant) return;
        const member = document.createElement('div');
        member.className = 'season-team-member';
        const image = document.createElement('img');
        image.alt = contestant.fullName || contestant.nickname || 'Contestant';
        setImageWithFallback(image, contestant);
        const name = document.createElement('span');
        name.textContent = contestant.nickname || contestant.fullName || 'Unnamed';
        member.append(image, name);
        members.append(member);
      });
      card.append(head, members);
      activeTeamGrid.append(card);
    });

    const eliminatedIds = eliminatedBeforeCurrentEpisode();
    if (!eliminatedIds.length) return;
    const eliminatedCard = document.createElement('article');
    eliminatedCard.className = 'season-eliminated-card';
    const eliminatedHead = document.createElement('div');
    eliminatedHead.className = 'season-eliminated-head';
    const eyebrow = document.createElement('p');
    eyebrow.className = 'eyebrow';
    eyebrow.textContent = 'Season departures';
    const heading = document.createElement('h3');
    heading.textContent = 'Eliminated';
    eliminatedHead.append(eyebrow, heading);

    const grid = document.createElement('div');
    grid.className = 'season-eliminated-grid';
    eliminatedIds.forEach((id, index) => {
      const contestant = state.contestantById.get(id);
      if (!contestant) return;
      const item = document.createElement('article');
      item.className = 'season-eliminated-contestant';
      const portraitWrap = document.createElement('div');
      portraitWrap.className = 'season-eliminated-portrait-wrap';
      const image = document.createElement('img');
      image.alt = contestant.fullName || contestant.nickname || 'Eliminated contestant';
      setImageWithFallback(image, contestant);
      const placement = document.createElement('span');
      placement.className = 'season-eliminated-placement';
      placement.textContent = ordinalPlacement(state.selectedIds.length - index);
      portraitWrap.append(image, placement);
      const name = document.createElement('strong');
      name.textContent = contestantDisplayName(id);
      item.append(portraitWrap, name);
      grid.append(item);
    });
    eliminatedCard.append(eliminatedHead, grid);
    elements.seasonTeamOverview.append(eliminatedCard);
  }

  const EVENT_COUNT_RANGES = [
    { min: 18, max: 24, preChallenge: [8, 12], preVote: [7, 11] },
    { min: 15, max: 17, preChallenge: [6, 9], preVote: [5, 8] },
    { min: 12, max: 14, preChallenge: [8, 9], preVote: [5, 6] },
    { min: 9, max: 11, preChallenge: [6, 8], preVote: [5, 6] },
    { min: 7, max: 8, preChallenge: [6, 7], preVote: [4, 5] },
    { min: 5, max: 6, preChallenge: [4, 5], preVote: [3, 4] },
    { min: 4, max: 4, preChallenge: [4, 5], preVote: [3, 4] },
    { min: 3, max: 3, preChallenge: [2, 4], preVote: [2, 3] }
  ];

  let activeEditorialContext = null;

  function eventCountRangeForCast(count, stage = 'preChallenge') {
    const normalized = Math.max(0, Number(count || 0));
    const range = EVENT_COUNT_RANGES.find(item => normalized >= item.min && normalized <= item.max);
    if (range) return range[stage] || range.preChallenge;
    if (normalized <= 2) return stage === 'preVote' ? [1, 2] : [2, 3];
    return stage === 'preVote' ? [7, 11] : [8, 12];
  }

  function eventCountForCast(count, stage = 'preChallenge') {
    const [minimum, maximum] = eventCountRangeForCast(count, stage);
    return randomInteger(minimum, maximum);
  }

  function eventIntensity(template) {
    if (!template) return 'standard';
    const source = eventSource(template);
    if (isFormalQuitTemplate(template) || isQuitResolutionTemplate(template) || isAllianceCollapseTemplate(template)) return 'resolution';
    if (template.category === 'Major Interpersonal Conflict') return 'major';
    if (template.category === 'Alliance Tension and Collapse') return 'major';
    if (template.category === 'Quitting and Withdrawal' && !isQuitInterventionTemplate(template)) return 'major';
    if (template.category === 'Emotional and Personal' && (isDeepPersonalTemplate(template) || /breakdown|identity crisis|confession|secret|trauma/.test(source))) return 'major';
    if (template.category === 'Around Camp' || template.category === 'Bonding and Friendship') return 'minor';
    return 'standard';
  }

  function editorialIntensityLimits(count, stage, eventTarget) {
    const smallCast = count <= 8;
    return {
      resolution: 1,
      major: smallCast ? 1 : Math.max(1, Math.min(2, Math.ceil(eventTarget / 6))),
      standard: eventTarget,
      minor: eventTarget
    };
  }

  function editorialIntensityAllowed(template, context = activeEditorialContext) {
    if (!context) return true;
    const intensity = eventIntensity(template);
    const used = Number(context.intensityCounts?.[intensity] || 0);
    const limit = Number(context.intensityLimits?.[intensity] ?? context.eventTarget);
    return used < limit;
  }

  function recentContestantEventCount(id, episodeWindow = 2) {
    const earliestEpisode = Math.max(1, state.episodeNumber - episodeWindow);
    return state.eventHistory.filter(event =>
      Number(event.episode || 0) >= earliestEpisode
      && Number(event.episode || 0) < state.episodeNumber
      && event.participants?.includes(id)
    ).length;
  }

  function editorialStorylineMomentum(id) {
    const runtime = runtimeFor(id);
    let score = 0;
    Object.values(runtime.storylines || {}).forEach(storyline => {
      if (!storyline || storyline.status === 'resolved') return;
      const progress = Number(storyline.progress || 0);
      const age = Math.max(0, state.episodeNumber - Number(storyline.lastEpisode || storyline.startedEpisode || state.episodeNumber));
      const recency = clampRange(1 - age * .14, .35, 1);
      score += progress * 3.2 * recency;
    });
    const opportunities = activeEventOpportunities().filter(item => String(item.ownerId) === String(id));
    score += Math.min(8, opportunities.reduce((sum, item) => sum + Number(item.weight || 1) * 2, 0));
    return clampRange(score, 0, 30);
  }

  function editorialStrategicImportance(id, pool) {
    const traits = traitsFor(id);
    const runtime = runtimeFor(id);
    const alliancePower = activeAllianceMemberships(id, pool).reduce((maximum, alliance) => Math.max(maximum, Number(alliance.strength || 0)), 0);
    return clampRange(
      (traits.strategy - 4) * 1.35
      + (traits.influence - 4) * 1.1
      + (traits.leadership - 4) * .7
      + runtime.strategicInfluence * .12
      + alliancePower * .055,
      0,
      20
    );
  }

  function editorialSocialImportance(id, pool) {
    const others = pool.filter(otherId => otherId !== id);
    if (!others.length) return 0;
    const strongBonds = others.filter(otherId => relationshipAverage(id, otherId) >= 3).length;
    const rivalries = others.filter(otherId => relationshipAverage(id, otherId) <= -3 || grudgeAverage(id, otherId) >= 30).length;
    const visibility = runtimeFor(id).socialVisibility;
    return clampRange(strongBonds * 2.4 + rivalries * 2.1 + visibility * .045, 0, 15);
  }

  function editorialChallengeImportance(id) {
    if (!state.challengeResult?.performances) return 0;
    const performance = Number(state.challengeResult.performances[id] ?? 50);
    const deviation = Math.abs(performance - 50);
    const highlighted = state.challengeResult.highlights?.some(highlight => highlight.subjectId === id);
    return clampRange(deviation * .22 + (highlighted ? 5 : 0), 0, 15);
  }

  function editorialDevelopmentNeed(id) {
    const recent = recentContestantEventCount(id, 2);
    const runtime = runtimeFor(id);
    const seasonVisibility = Math.max(0, Number(runtime.eventAppearances || 0));
    return clampRange(16 - recent * 4.5 - Math.min(5, seasonVisibility * .08), 0, 20);
  }

  function initialEditorialDangerScores(stage, pool) {
    const scores = new Map(pool.map(id => [id, 0]));
    if (stage !== 'preVote') return scores;
    const landscape = prepareVoteLandscape();
    if (!landscape) return scores;
    const order = landscape.targetOrder || [];
    order.slice(0, 4).forEach((id, index) => {
      if (!scores.has(id)) return;
      const orderBonus = [18, 13, 8, 4][index] || 0;
      const vulnerability = Number(landscape.vulnerability?.[id] || 0);
      scores.set(id, clampRange(orderBonus + vulnerability * .07, 0, 25));
    });
    return scores;
  }

  function buildEpisodeEditorialContext(stage, eventTarget) {
    const stagePool = stage === 'preVote' && state.challengeResult ? votePool() : [...state.activeIds];
    const pool = stagePool.length ? stagePool : [...state.activeIds];
    const dangerScores = initialEditorialDangerScores(stage, pool);
    const entries = pool.map(id => {
      const components = {
        danger: Number(dangerScores.get(id) || 0),
        storyline: editorialStorylineMomentum(id),
        strategic: editorialStrategicImportance(id, pool),
        social: editorialSocialImportance(id, pool),
        challenge: stage === 'preVote' ? editorialChallengeImportance(id) : 0,
        development: editorialDevelopmentNeed(id),
        wildcard: Math.random() * 15
      };
      const priority = Object.values(components).reduce((sum, value) => sum + Number(value || 0), 0);
      return { id, components, priority };
    }).sort((first, second) => second.priority - first.priority);

    const focusCount = clampRange(Math.round(Math.sqrt(Math.max(1, pool.length)) + 1), 3, Math.min(6, pool.length));
    const focusIds = entries.slice(0, focusCount).map(entry => entry.id);
    const desiredFocus = new Map();
    entries.slice(0, focusCount).forEach((entry, index) => {
      desiredFocus.set(entry.id, clampRange(2.35 - index * .18, 1.35, 2.35));
    });

    let primaryDangerId = '';
    let secondaryDangerId = '';
    if (stage === 'preVote') {
      const dangerOrder = [...entries].sort((first, second) => second.components.danger - first.components.danger);
      primaryDangerId = dangerOrder[0]?.components.danger > 0 ? dangerOrder[0].id : '';
      secondaryDangerId = dangerOrder[1]?.components.danger > 0 ? dangerOrder[1].id : '';
      if (primaryDangerId) desiredFocus.set(primaryDangerId, Math.max(Number(desiredFocus.get(primaryDangerId) || 0), 1.55));
      if (secondaryDangerId) desiredFocus.set(secondaryDangerId, Math.max(Number(desiredFocus.get(secondaryDangerId) || 0), .9));
    }

    const context = {
      stage, eventTarget, pool, entries, focusIds, desiredFocus,
      primaryDangerId, secondaryDangerId, dangerScores,
      exposure: new Map(pool.map(id => [id, 0])),
      directAppearances: new Map(pool.map(id => [id, 0])),
      intensityCounts: { minor: 0, standard: 0, major: 0, resolution: 0 },
      intensityLimits: editorialIntensityLimits(state.activeIds.length, stage, eventTarget),
      remainingSlots: eventTarget,
      forceFocusId: ''
    };

    if (stage === 'preVote') {
      (state.episodeEvents.preChallenge || []).forEach(event => {
        const intensity = eventIntensity(event);
        (event.participants || []).forEach((id, role) => {
          if (!context.exposure.has(id)) return;
          const carry = editorialExposureForRole(role, intensity) * .35;
          context.exposure.set(id, Number(context.exposure.get(id) || 0) + carry);
          context.directAppearances.set(id, Number(context.directAppearances.get(id) || 0) + .35);
        });
      });
      context.entries.forEach(entry => {
        entry.priority = Math.max(0, entry.priority - Number(context.exposure.get(entry.id) || 0) * 3.5);
      });
    }
    return context;
  }

  function refreshEditorialDanger(context = activeEditorialContext) {
    if (!context || context.stage !== 'preVote') return;
    const pool = votePool();
    const eligible = new Set(eligibleVoteTargets());
    const ranked = pool.filter(id => eligible.has(id)).map(id => {
      const vulnerability = Number(state.voteLandscape?.vulnerability?.[id] || 0);
      const heat = publicTargetHeat(id, pool);
      const pressure = pool.filter(voterId => voterId !== id).reduce((sum, voterId) => sum + getDirectional(state.targetPriority, voterId, id), 0) / Math.max(1, pool.length - 1);
      return { id, score: vulnerability * .33 + heat * .47 + pressure * .20 };
    }).sort((first, second) => second.score - first.score);
    context.primaryDangerId = ranked[0]?.id || context.primaryDangerId;
    context.secondaryDangerId = ranked[1]?.id || context.secondaryDangerId;
    ranked.slice(0, 4).forEach((item, index) => {
      const entry = context.entries.find(candidate => candidate.id === item.id);
      if (!entry) return;
      const danger = clampRange(([18, 13, 8, 4][index] || 0) + item.score * .07, 0, 25);
      entry.priority += danger - Number(entry.components.danger || 0);
      entry.components.danger = danger;
      context.dangerScores.set(item.id, danger);
    });
    if (context.primaryDangerId) context.desiredFocus.set(context.primaryDangerId, Math.max(Number(context.desiredFocus.get(context.primaryDangerId) || 0), 1.55));
    if (context.secondaryDangerId) context.desiredFocus.set(context.secondaryDangerId, Math.max(Number(context.desiredFocus.get(context.secondaryDangerId) || 0), .9));
  }

  function editorialExposureForRole(role, intensity = 'standard') {
    const roleValue = role === 0 ? 1 : role === 1 ? .75 : .30;
    const intensityScale = intensity === 'minor' ? .70 : intensity === 'major' ? 1.10 : intensity === 'resolution' ? 1.15 : 1;
    return roleValue * intensityScale;
  }

  function recordEditorialExposure(participants, templateOrEvent, voteMeta = null, context = activeEditorialContext) {
    if (!context) return;
    const intensity = eventIntensity(templateOrEvent);
    (participants || []).forEach((id, role) => {
      if (!context.exposure.has(id)) return;
      context.exposure.set(id, Number(context.exposure.get(id) || 0) + editorialExposureForRole(role, intensity));
      context.directAppearances.set(id, Number(context.directAppearances.get(id) || 0) + 1);
    });
    const direct = new Set(participants || []);
    const addIndirect = (id, amount) => {
      if (!id || direct.has(id) || !context.exposure.has(id)) return;
      context.exposure.set(id, Number(context.exposure.get(id) || 0) + amount);
    };
    addIndirect(voteMeta?.primaryTargetId, .65);
    addIndirect(voteMeta?.backupTargetId, .42);
    addIndirect(voteMeta?.decoyTargetId, .30);
    (voteMeta?.discussionTargetIds || []).forEach(id => addIndirect(id, .45));
    (voteMeta?.pairTargetIds || []).forEach(id => addIndirect(id, .35));
    context.intensityCounts[intensity] = Number(context.intensityCounts[intensity] || 0) + 1;
    refreshEditorialDanger(context);
  }

  function editorialUrgentFocusId(context = activeEditorialContext) {
    if (!context || context.remainingSlots > 2) return '';
    const required = [];
    if (context.primaryDangerId) required.push(context.primaryDangerId);
    if (context.secondaryDangerId && context.remainingSlots > 1) required.push(context.secondaryDangerId);
    context.focusIds.forEach(id => required.push(id));
    return [...new Set(required)].map(id => ({
      id,
      deficit: Number(context.desiredFocus.get(id) || 0) - Number(context.exposure.get(id) || 0),
      direct: Number(context.directAppearances.get(id) || 0)
    })).filter(item => item.deficit > .25 || (item.id === context.primaryDangerId && item.direct < 1))
      .sort((first, second) => {
        const firstDanger = first.id === context.primaryDangerId ? 1 : 0;
        const secondDanger = second.id === context.primaryDangerId ? 1 : 0;
        return (secondDanger - firstDanger) || (second.deficit - first.deficit);
      })[0]?.id || '';
  }

  function editorialRoleBonus(id, role, template, context = activeEditorialContext) {
    if (!context || !context.exposure.has(id)) return 0;
    const entry = context.entries.find(candidate => candidate.id === id);
    if (!entry) return 0;
    const current = Number(context.exposure.get(id) || 0);
    const desired = Number(context.desiredFocus.get(id) || 0);
    const deficit = Math.max(0, desired - current);
    const roleScale = role === 0 ? 1 : role === 1 ? .72 : .38;
    let bonus = Math.min(8, entry.priority * .085) * roleScale;
    if (deficit > 0) bonus += Math.min(9, deficit * 4.2) * roleScale;
    if (id === context.primaryDangerId && current < 1.55) bonus += 3.2 * roleScale;
    else if (id === context.secondaryDangerId && current < .9) bonus += 1.6 * roleScale;
    if (context.forceFocusId === id) bonus += role === 0 ? 24 : 15;

    const softMaximum = id === context.primaryDangerId
      ? Math.max(2.25, context.eventTarget * .42)
      : Math.max(2.1, desired + 1.1);
    if (current > softMaximum) bonus -= (current - softMaximum) * 7;
    return bonus;
  }

  function quitRuleEnabled() {
    return [...document.querySelectorAll('.switch-row')].some(row => {
      const label = row.querySelector('span')?.textContent?.trim().toLowerCase();
      return label === 'contestants may quit' && row.querySelector('input')?.checked;
    });
  }

  function existingAllianceFor(ids) {
    const required = new Set(ids);
    return state.alliances.find(alliance =>
      alliance.active
      && [...required].every(id => alliance.members.includes(id))
    ) || null;
  }

  function exactAllianceFor(ids) {
    const members = [...new Set(ids)].sort(naturalCompare);
    return state.alliances.find(alliance =>
      alliance.active
      && alliance.members.length === members.length
      && members.every(id => alliance.members.includes(id))
    ) || null;
  }

