  function teamDisruptionScore(targetId, pool = votePool()) {
    const runtime = runtimeFor(targetId);
    const observers = pool.filter(id => id !== targetId);
    const irritation = observers.length
      ? average(observers.map(id => getDirectional(state.irritation, id, targetId)), 0)
      : 0;
    const recentConflictCount = recentEvents(30).filter(event =>
      event.participants?.includes(targetId)
      && ['Minor Conflict', 'Major Interpersonal Conflict', 'Team Dysfunction', 'Alliance Tension and Collapse'].includes(event.category)
    ).length;
    const reputations = runtime.reputations || {};
    const disruptiveReputation = (
      Number(reputations.Chaotic || 0)
      + Number(reputations.Volatile || 0)
      + Number(reputations.Bossy || 0)
      + Number(reputations.Unreliable || 0)
      + Number(reputations.Difficult || 0)
    ) * 6;
    const traits = traitsFor(targetId);
    const personalityFriction = Math.max(0, traits.aggression - 5) * 3
      + Math.max(0, 6 - traits.patience) * 2
      + Math.max(0, 6 - skillToTen(currentSkill(targetId, 'teamwork'))) * 2;
    return clampRange(
      irritation * .48
      + recentConflictCount * 11
      + disruptiveReputation
      + personalityFriction,
      0,
      100
    );
  }

  function averageSuspicionToward(targetId, pool = votePool()) {
    const observers = pool.filter(id => id !== targetId);
    return observers.length
      ? average(observers.map(id => getDirectional(state.suspicion, id, targetId)), 0)
      : 0;
  }

  function averageHostilityToward(targetId, pool = votePool()) {
    const observers = pool.filter(id => id !== targetId);
    if (!observers.length) return 0;
    return average(observers.map(id => {
      const relation = currentRelationship(id, targetId);
      return clampRange(
        Math.max(0, -relation) * 7
        + getDirectional(state.irritation, id, targetId) * .28
        + currentGrudge(id, targetId) * .22,
        0,
        100
      );
    }), 0);
  }

  function targetVulnerabilityScore(targetId, pool = votePool()) {
    const existingPressure = pool.filter(id => id !== targetId).length
      ? average(pool.filter(id => id !== targetId).map(id => getDirectional(state.targetPriority, id, targetId)), 0)
      : 0;
    const components = {
      challengeLiability: challengeLiability(targetId) * .25,
      teamDisruption: teamDisruptionScore(targetId, pool) * .20,
      socialIsolation: socialIsolationScore(targetId, pool) * .15,
      strategicThreat: strategicThreat(targetId, pool) * .15,
      suspicion: averageSuspicionToward(targetId, pool) * .10,
      publicPressure: existingPressure * .10,
      hostility: averageHostilityToward(targetId, pool) * .05
    };
    return {
      targetId,
      score: clampRange(Object.values(components).reduce((sum, value) => sum + value, 0), 0, 100),
      components
    };
  }

  function personalProtectionScore(voterId, targetId, pool = votePool()) {
    const traits = traitsFor(voterId);
    const relation = currentRelationship(voterId, targetId);
    const trust = currentTrust(voterId, targetId);
    const alliance = sameVotingAlliance(voterId, targetId, pool);
    let protection = Math.max(0, relation) * 3.2
      + Math.max(0, trust - 48) * .36;
    if (relation >= 4 && trust >= 62) protection += 18 + traits.loyalty * 1.2;
    if (alliance) {
      const loyalty = Number(alliance.memberLoyalty?.[voterId] ?? 50);
      protection += 24 + alliance.strength * .18 + loyalty * .14 - alliance.tension * .12;
    }
    if (pairHadSeriousBetrayal(voterId, targetId, 25)) protection *= .3;
    return clampRange(protection, 0, 72);
  }

  function provisionalVotePreference(voterId, targetId, pool, vulnerabilityById) {
    const traits = traitsFor(voterId);
    const vulnerability = vulnerabilityById.get(targetId)?.score || 0;
    const relationship = currentRelationship(voterId, targetId);
    const irritation = getDirectional(state.irritation, voterId, targetId);
    const grudge = currentGrudge(voterId, targetId);
    const suspicion = getDirectional(state.suspicion, voterId, targetId);
    const threat = strategicThreat(targetId, pool);
    const personalHostility = clampRange(
      Math.max(0, -relationship) * 4
      + irritation * .12
      + grudge * .10,
      0,
      28
    );
    let score = vulnerability * .66
      + suspicion * .08
      + threat * (.04 + Math.max(0, traits.strategy - 5) * .012)
      + personalHostility * (.10 + Math.max(0, traits.aggression - 6) * .015)
      + selfPreservationScore(voterId, targetId, pool) * .06;
    score -= personalProtectionScore(voterId, targetId, pool);
    return clampRange(score, -50, 100);
  }

  function reasonForProvisionalTarget(targetId, vulnerabilityById) {
    const components = vulnerabilityById.get(targetId)?.components || {};
    const key = Object.entries(components).sort((a, b) => b[1] - a[1])[0]?.[0] || 'challengeLiability';
    const reasons = {
      challengeLiability: 'challengeLiability',
      teamDisruption: 'teamDisruption',
      socialIsolation: 'isolation',
      strategicThreat: 'strategicThreat',
      suspicion: 'suspicion',
      publicPressure: 'publicPressure',
      hostility: 'hostility'
    };
    return reasons[key] || 'vulnerability';
  }

  function prepareVoteLandscape(force = false) {
    const pool = votePool();
    const signature = `${state.episodeNumber}:${pool.slice().sort().join('|')}`;
    if (!force && state.voteLandscape?.signature === signature) return state.voteLandscape;
    if (!pool.length) {
      state.votePlans = new Map();
      state.voteLandscape = null;
      return null;
    }

    state.votePlans = new Map();
    const eligibleTargets = eligibleVoteTargets();
    const vulnerabilityById = new Map(eligibleTargets.map(id => [id, targetVulnerabilityScore(id, pool)]));
    const preferenceScores = new Map();

    pool.forEach(voterId => {
      const rankings = eligibleTargets.filter(targetId => targetId !== voterId).map(targetId => ({
        targetId,
        score: provisionalVotePreference(voterId, targetId, pool, vulnerabilityById)
      })).sort((first, second) => second.score - first.score);
      preferenceScores.set(voterId, Object.fromEntries(rankings.map(item => [item.targetId, item.score])));
      const plan = votePlanFor(voterId);
      plan.preferredTarget = rankings[0]?.targetId || '';
      plan.backupTarget = rankings[1]?.targetId || '';
      plan.publicTarget = plan.preferredTarget;
      plan.actualTarget = plan.preferredTarget;
      plan.commitment = 0;
      plan.reasonKey = reasonForProvisionalTarget(plan.preferredTarget, vulnerabilityById);
    });

    const blocs = [];
    state.alliances.filter(alliance => alliance.active).forEach(alliance => {
      const members = alliance.members.filter(id => pool.includes(id));
      if (members.length < 2) return;
      const candidates = eligibleTargets.filter(id => !members.includes(id));
      if (!candidates.length) return;
      const targetId = candidates.map(id => ({
        id,
        score: average(members.map(memberId => preferenceScores.get(memberId)?.[id] ?? -50), -50)
          + (vulnerabilityById.get(id)?.score || 0) * .18
      })).sort((a, b) => b.score - a.score)[0]?.id;
      if (!targetId) return;
      blocs.push({
        id: `alliance-bloc-${alliance.id}`,
        type: 'alliance',
        allianceId: alliance.id,
        members,
        targetId,
        strength: clampRange(alliance.strength + 18 - alliance.tension * .25, 20, 110)
      });
    });

    for (let firstIndex = 0; firstIndex < pool.length; firstIndex += 1) {
      for (let secondIndex = firstIndex + 1; secondIndex < pool.length; secondIndex += 1) {
        const firstId = pool[firstIndex];
        const secondId = pool[secondIndex];
        if (sameVotingAlliance(firstId, secondId, pool)) continue;
        if (!canPlanVoteTogether(firstId, secondId, pool, false)) continue;
        const candidates = eligibleTargets.filter(id => id !== firstId && id !== secondId);
        if (!candidates.length) continue;
        const targetId = candidates.map(id => ({
          id,
          score: (preferenceScores.get(firstId)?.[id] ?? -50)
            + (preferenceScores.get(secondId)?.[id] ?? -50)
        })).sort((a, b) => b.score - a.score)[0]?.id;
        if (!targetId) continue;
        blocs.push({
          id: `friend-bloc-${firstId}-${secondId}`,
          type: 'friends',
          members: [firstId, secondId],
          targetId,
          strength: clampRange(planningConnectionScore(firstId, secondId, pool), 20, 95)
        });
      }
    }

    blocs.sort((a, b) => b.strength - a.strength);
    blocs.forEach(bloc => {
      bloc.members.forEach(memberId => {
        const plan = votePlanFor(memberId);
        if (!plan.blocTargets.includes(bloc.targetId)) plan.blocTargets.push(bloc.targetId);
        const personalScore = preferenceScores.get(memberId)?.[plan.preferredTarget] ?? -50;
        const blocScore = preferenceScores.get(memberId)?.[bloc.targetId] ?? -50;
        const alliance = bloc.type === 'alliance'
          ? state.alliances.find(item => item.id === bloc.allianceId)
          : null;
        const loyalty = alliance ? Number(alliance.memberLoyalty?.[memberId] ?? 50) : traitsFor(memberId).loyalty * 10;
        if (blocScore >= personalScore - 12 || loyalty >= 65) {
          plan.actualTarget = bloc.targetId;
          plan.publicTarget = bloc.targetId;
          adjustDirectional(state.targetPriority, memberId, bloc.targetId, bloc.type === 'alliance' ? 20 : 12, 0, 100);
        }
      });
    });

    const support = new Map(pool.map(id => [id, vulnerabilityById.get(id)?.score || 0]));
    pool.forEach(voterId => {
      const plan = votePlanFor(voterId);
      if (plan.preferredTarget) support.set(plan.preferredTarget, (support.get(plan.preferredTarget) || 0) + 18);
      if (plan.actualTarget) support.set(plan.actualTarget, (support.get(plan.actualTarget) || 0) + 12);
    });
    blocs.forEach(bloc => support.set(bloc.targetId, (support.get(bloc.targetId) || 0) + bloc.strength * .45));
    const targetOrder = [...support.entries()].sort((a, b) => b[1] - a[1]).map(([id]) => id);

    state.voteLandscape = {
      signature,
      episode: state.episodeNumber,
      pool: [...pool],
      primaryTarget: targetOrder[0] || '',
      secondaryTarget: targetOrder[1] || '',
      vulnerability: Object.fromEntries([...vulnerabilityById.entries()].map(([id, item]) => [id, item.score])),
      preferenceScores: Object.fromEntries([...preferenceScores.entries()]),
      targetOrder: [...targetOrder],
      blocs
    };
    return state.voteLandscape;
  }

  function voteEventRoleConfig(template) {
    const number = votingTemplateNumber(template);
    const configs = {
      1: ['planner', 'planner', 'primary'],
      2: ['planner', 'planner', 'planner'],
      3: ['planner', 'planner', 'planner'],
      4: ['planner', 'recruit', 'primary'],
      5: ['planner', 'planner', 'planner', 'planner'],
      6: ['planner', 'planner', 'planner', 'primary'],
      7: ['planner', 'planner', 'planner'],
      8: ['planner', 'planner', 'planner', 'planner'],
      9: ['planner', 'planner'],
      10: ['planner', 'planner', 'planner', 'planner'],
      11: ['planner', 'planner', 'swing'],
      12: ['planner', 'swing'],
      13: ['swing', 'blocOne', 'blocOne', 'blocTwo', 'blocTwo'],
      14: ['planner', 'planner', 'swing'],
      15: ['planner', 'swing'],
      16: ['planner', 'planner', 'primary', 'planner'],
      17: ['planner', 'planner', 'planner', 'primary'],
      18: ['planner', 'recruit', 'backup', 'primary'],
      19: ['planner', 'planner', 'planner', 'pairOne', 'pairTwo'],
      20: ['planner', 'planner', 'planner', 'planner', 'primary'],
      21: ['planner', 'planner', 'primary'],
      22: ['planner', 'planner', 'planner', 'decoy', 'primary'],
      23: ['planner', 'planner'],
      24: ['planner', 'planner', 'planner', 'planner', 'primary', 'backup'],
      25: ['planner', 'planner', 'carrier', 'decoy'],
      26: ['planner', 'planner', 'planner', 'decoy'],
      27: ['planner', 'recruit', 'primary'],
      28: ['planner', 'recruit'],
      29: ['planner', 'planner', 'planner'],
      30: ['planner', 'recruit'],
      31: ['planner', 'hesitant'],
      32: ['planner', 'planner', 'planner'],
      33: ['planner', 'planner', 'planner'],
      34: ['planner', 'planner', 'planner', 'planner'],
      35: ['planner', 'planner', 'planner', 'planner']
    };
    return configs[number] || Array.from({ length: Math.max(template.min, requiredEventParticipantCount(template)) }, () => 'planner');
  }

  function blocTargetScore(bloc, targetId, landscape) {
    if (!targetId || bloc.members.includes(targetId)) return -100;
    return average(bloc.members.map(memberId => landscape.preferenceScores?.[memberId]?.[targetId] ?? -50), -50)
      + Number(landscape.vulnerability?.[targetId] || 0) * .18;
  }

  function chooseVotingPreparationParticipants(template, usage) {
    const landscape = prepareVoteLandscape();
    if (!landscape) return [];
    const pool = landscape.pool.filter(id => participantAvailableForBatch(id, usage));
    const roles = voteEventRoleConfig(template);
    if (pool.length < roles.length) return [];
    const number = votingTemplateNumber(template);
    const relaxed = [7, 8, 10, 32, 33, 34, 35].includes(number);
    let blocs = landscape.blocs.map(bloc => ({
      ...bloc,
      members: bloc.members.filter(id => pool.includes(id))
    })).filter(bloc => bloc.members.length >= 2 && pool.includes(bloc.targetId));

    if (number === 13) {
      const disjointPairs = [];
      for (let i = 0; i < blocs.length; i += 1) {
        for (let j = i + 1; j < blocs.length; j += 1) {
          const first = blocs[i];
          const second = blocs[j];
          if (first.targetId === second.targetId) continue;
          if (first.members.some(id => second.members.includes(id))) continue;
          disjointPairs.push([first, second]);
        }
      }
      const pair = weightedChoice(disjointPairs, item => item[0].strength + item[1].strength);
      if (!pair) return [];
      const used = new Set();
      const firstMembers = pair[0].members.slice(0, 2);
      const secondMembers = pair[1].members.slice(0, 2);
      firstMembers.concat(secondMembers).forEach(id => used.add(id));
      const swingCandidates = pool.filter(id => !used.has(id)).sort((a, b) => {
        const aPlan = votePlanFor(a);
        const bPlan = votePlanFor(b);
        return aPlan.commitment - bPlan.commitment;
      });
      const swing = swingCandidates[0];
      if (!swing || firstMembers.length < 2 || secondMembers.length < 2) return [];
      const participants = [swing, ...firstMembers, ...secondMembers];
      participants.voteMeta = {
        number,
        type: 'twoBlocs',
        planners: [...firstMembers, ...secondMembers],
        swingVoters: [swing],
        primaryTargetId: pair[0].targetId,
        backupTargetId: pair[1].targetId,
        blocOne: firstMembers,
        blocTwo: secondMembers
      };
      return participants;
    }

    if (!blocs.length) {
      const trustedPairs = [];
      for (let i = 0; i < pool.length; i += 1) {
        for (let j = i + 1; j < pool.length; j += 1) {
          if (canPlanVoteTogether(pool[i], pool[j], landscape.pool, relaxed)) {
            trustedPairs.push({
              id: `ad-hoc-${pool[i]}-${pool[j]}`,
              type: 'friends',
              members: [pool[i], pool[j]],
              targetId: votePlanFor(pool[i]).preferredTarget === votePlanFor(pool[j]).preferredTarget
                ? votePlanFor(pool[i]).preferredTarget
                : landscape.primaryTarget,
              strength: planningConnectionScore(pool[i], pool[j], landscape.pool)
            });
          }
        }
      }
      blocs = trustedPairs.filter(bloc => pool.includes(bloc.targetId));
    }
    const bloc = weightedChoice(blocs, item => Math.max(1, item.strength));
    if (!bloc) return [];

    let primaryTargetId = bloc.targetId;
    if (!pool.includes(primaryTargetId) || bloc.members.includes(primaryTargetId)) {
      primaryTargetId = [landscape.primaryTarget, landscape.secondaryTarget]
        .find(id => pool.includes(id) && !bloc.members.includes(id)) || '';
    }
    if (!primaryTargetId) return [];
    let backupTargetId = [landscape.secondaryTarget, landscape.primaryTarget]
      .find(id => id && id !== primaryTargetId && pool.includes(id) && !bloc.members.includes(id)) || '';
    if (!backupTargetId) {
      backupTargetId = pool.filter(id => id !== primaryTargetId && !bloc.members.includes(id))
        .sort((a, b) => blocTargetScore(bloc, b, landscape) - blocTargetScore(bloc, a, landscape))[0] || '';
    }

    const plannerSlots = roles.filter(role => role === 'planner').length;
    const planners = [...bloc.members];
    const leader = planners.sort((a, b) => {
      const aTraits = traitsFor(a);
      const bTraits = traitsFor(b);
      return (bTraits.strategy + bTraits.leadership + runtimeFor(b).strategicInfluence / 10)
        - (aTraits.strategy + aTraits.leadership + runtimeFor(a).strategicInfluence / 10);
    })[0];
    const extensionCandidates = pool.filter(id =>
      id !== primaryTargetId
      && id !== backupTargetId
      && !planners.includes(id)
      && canPlanVoteTogether(leader, id, landscape.pool, relaxed)
    ).sort((a, b) => planningConnectionScore(leader, b, landscape.pool) - planningConnectionScore(leader, a, landscape.pool));
    while (planners.length < plannerSlots && extensionCandidates.length) planners.push(extensionCandidates.shift());
    if (planners.length < plannerSlots) return [];

    const used = new Set();
    const plannerQueue = planners.slice(0, plannerSlots);
    const pickSwing = () => pool.filter(id =>
      !used.has(id)
      && id !== primaryTargetId
      && id !== backupTargetId
      && !plannerQueue.includes(id)
      && currentTrust(id, leader) >= 28
      && relationshipAverage(id, leader) >= -1
      && personalProtectionScore(id, primaryTargetId, landscape.pool) < 48
    ).sort((a, b) => {
      const aPlan = votePlanFor(a);
      const bPlan = votePlanFor(b);
      const aUncertainty = Math.abs((landscape.preferenceScores?.[a]?.[primaryTargetId] ?? 0) - (landscape.preferenceScores?.[a]?.[backupTargetId] ?? 0));
      const bUncertainty = Math.abs((landscape.preferenceScores?.[b]?.[primaryTargetId] ?? 0) - (landscape.preferenceScores?.[b]?.[backupTargetId] ?? 0));
      return (aPlan.commitment + aUncertainty) - (bPlan.commitment + bUncertainty);
    })[0];

    let pairTargets = [];
    if (roles.includes('pairOne')) {
      const candidates = [];
      const outside = pool.filter(id => !plannerQueue.includes(id));
      for (let i = 0; i < outside.length; i += 1) {
        for (let j = i + 1; j < outside.length; j += 1) {
          const relation = relationshipAverage(outside[i], outside[j]);
          const trust = (currentTrust(outside[i], outside[j]) + currentTrust(outside[j], outside[i])) / 2;
          candidates.push({ ids: [outside[i], outside[j]], score: relation * 8 + trust * .3 + strategicThreat(outside[i], landscape.pool) + strategicThreat(outside[j], landscape.pool) });
        }
      }
      pairTargets = candidates.sort((a, b) => b.score - a.score)[0]?.ids || [];
      if (pairTargets.length < 2) return [];
      primaryTargetId = pairTargets[0];
      backupTargetId = pairTargets[1];
    }

    const participants = [];
    let plannerIndex = 0;
    let swingId = '';
    roles.forEach(role => {
      let id = '';
      if (role === 'planner') id = plannerQueue[plannerIndex++];
      else if (['recruit', 'swing', 'hesitant'].includes(role)) {
        id = swingId || pickSwing();
        swingId = id;
      } else if (role === 'primary') id = primaryTargetId;
      else if (role === 'backup' || role === 'decoy') id = backupTargetId;
      else if (role === 'carrier') {
        id = pool.filter(candidateId =>
          !used.has(candidateId)
          && candidateId !== primaryTargetId
          && candidateId !== backupTargetId
          && !plannerQueue.includes(candidateId)
        ).sort((a, b) => runtimeFor(b).socialVisibility - runtimeFor(a).socialVisibility)[0];
      } else if (role === 'pairOne') id = pairTargets[0];
      else if (role === 'pairTwo') id = pairTargets[1];
      if (!id || used.has(id)) return;
      participants.push(id);
      used.add(id);
    });
    if (participants.length !== roles.length) return [];

    participants.voteMeta = {
      number,
      type: number === 22 ? 'decoy'
        : [23, 25, 26, 30].includes(number) ? 'misdirection'
          : [11, 12, 14, 15].includes(number) ? 'recruitment'
            : [32, 33].includes(number) ? 'flip'
              : 'coordination',
      planners: plannerQueue,
      recruits: roles.map((role, index) => ['recruit', 'hesitant'].includes(role) ? participants[index] : '').filter(Boolean),
      swingVoters: roles.map((role, index) => role === 'swing' ? participants[index] : '').filter(Boolean),
      primaryTargetId,
      backupTargetId,
      decoyTargetId: roles.includes('decoy') ? backupTargetId : '',
      pairTargetIds: pairTargets
    };
    return participants;
  }

  function chooseParticipants(template, stage, usage, usedPairs = new Map()) {
    if (template.category === 'Voting Preparation' && stage === 'preVote') {
      return chooseVotingPreparationParticipants(template, usage);
    }
    const attemptLimit = state.autoSimulating ? 6 : 30;
    for (let attempt = 0; attempt < attemptLimit; attempt += 1) {
      let pool = groupPoolForCategory(template.category, stage, template.min);
      if (pool.length < template.min) pool = [...state.activeIds];
      pool = pool.filter(id => participantAvailableForBatch(id, usage));
      if (pool.length < template.min) return [];

      if (['Alliance Maintenance', 'Alliance Tension and Collapse'].includes(template.category)) {
        const eligible = state.alliances.filter(alliance =>
          allianceEligibleForTemplate(alliance, template, stage, pool)
        );
        const alliance = weightedChoice(eligible, item => {
          if (template.category === 'Alliance Maintenance') {
            return Math.max(1, 105 - item.strength + item.tension);
          }
          return Math.max(1, 105 - item.strength + item.tension * 1.5);
        });
        if (!alliance) return [];
        pool = alliance.members.filter(id =>
          state.activeIds.includes(id) && participantAvailableForBatch(id, usage)
        );
        if (pool.length < template.min) continue;
      }

      const castParticipantCap = state.activeIds.length <= 4 ? 3 : state.activeIds.length <= 6 ? 4 : state.activeIds.length <= 8 ? 5 : 6;
      const maximum = Math.min(template.max, pool.length, castParticipantCap);
      const minimum = Math.min(Math.max(template.min, requiredEventParticipantCount(template)), maximum);
      const count = randomInteger(minimum, maximum);
      const selected = [];

      for (let role = 0; role < count; role += 1) {
        const available = pool.filter(id => !selected.includes(id) && participantAvailableForBatch(id, usage));
        if (!available.length) break;
        const isTargetRole = role === count - 1
          && count >= 2
          && ['Voting Preparation', 'Strategic Conversation'].includes(template.category);

        const roleCandidates = isTargetRole && stage === 'preVote'
          ? available.filter(id => eligibleVoteTargets().includes(id))
          : available;
        if (!roleCandidates.length) break;
        const chosen = weightedChoice(roleCandidates, id => {
          if (!isTargetRole) return roleScore(id, template.category, role, selected, usage, template);
          const runtime = runtimeFor(id);
          const challengePerformance = state.challengeResult?.performances?.[id] ?? 50;
          const accumulatedPressure = selected.reduce((sum, voterId) =>
            sum + getDirectional(state.targetPriority, voterId, id), 0
          );
          const allianceProtection = state.alliances.some(alliance =>
            alliance.active
            && alliance.members.includes(id)
            && selected.some(voterId => alliance.members.includes(voterId))
          ) ? 12 : 0;
          const baseTargetScore = 14
            + (100 - challengePerformance) / 7
            + runtime.isolation / 7
            + accumulatedPressure / 10
            + Math.max(0, -averageRelationship(id, pool)) * 2
            - allianceProtection
            + editorialRoleBonus(id, role, template);
          return Math.max(.2, baseTargetScore * participantUsageWeight(id, usage));
        });
        if (chosen) selected.push(chosen);
      }

      if (selected.length < template.min) continue;
      const key = primaryPair(selected);
      if (key && (usedPairs.get(key) || 0) >= 1) continue;
      if (!participantCombinationEligible(template, selected, stage)) continue;
      return selected;
    }
    return [];
  }

  function templateSentiment(template) {
    const source = eventSource(template);
    const positive = /increase|improve|praise|proud|comfort|support|bond|friend|reassur|celebrat|respect|successful|better than|nailed|impressed|strongest/.test(source);
    const negative = /decrease|loss|blame|anger|fight|conflict|collapse|betray|isolat|embarrass|crash|quit|distrust|suspicion|terrible|weakest|failed/.test(source);
    if (positive && !negative) return 1;
    if (negative && !positive) return -1;
    return 0;
  }

  function storylineContinuationBonus(template, participants) {
    if (participants.length < 2) return 0;
    const recent = recentPairEvents(participants[0], participants[1], 35);
    if (!recent.length) return 0;
    const previous = recent.at(-1)?.category;
    const current = template.category;
    const chains = {
      'Minor Conflict': ['Major Interpersonal Conflict', 'Isolation and Social Exclusion', 'Team Dysfunction'],
      'Bonding and Friendship': ['Emotional and Personal', 'Alliance Formation'],
      'Emotional and Personal': ['Bonding and Friendship', 'Alliance Formation'],
      'Alliance Formation': ['Alliance Maintenance'],
      'Manipulation and Deception': ['Major Interpersonal Conflict', 'Alliance Tension and Collapse', 'Voting Preparation'],
      'Post-Challenge Reaction': ['Voting Preparation', 'Strategic Conversation', 'Team Dysfunction'],
      'Isolation and Social Exclusion': ['Alliance Formation', 'Emotional and Personal', 'Quitting and Withdrawal']
    };
    return chains[previous]?.includes(current) ? 5 : 0;
  }

  function participantFit(template, participants, stage, usage) {
    if (!participantCombinationEligible(template, participants, stage)) return 0;
    const category = template.category;
    const first = participants[0];
    const second = participants[1];
    let fit = 14;

    if (second) {
      const relation = relationshipAverage(first, second);
      const trust = (currentTrust(first, second) + currentTrust(second, first)) / 2;
      const irritation = (
        getDirectional(state.irritation, first, second)
        + getDirectional(state.irritation, second, first)
      ) / 2;
      const grudge = grudgeAverage(first, second);

      if (['Bonding and Friendship', 'Team Bonding', 'Emotional and Personal', 'Alliance Formation'].includes(category)) {
        fit += relation * 2 + trust / 14;
      }
      if (['Minor Conflict', 'Major Interpersonal Conflict', 'Team Dysfunction', 'Alliance Tension and Collapse'].includes(category)) {
        fit += -relation * 2 + irritation / 8 + grudge / 10;
      }
      if (category === 'Manipulation and Deception') fit += currentTrust(second, first) / 12;
    }

    if (category === 'Post-Challenge Reaction' && state.challengeResult) {
      const performance = state.challengeResult.performances[first] ?? 50;
      fit += templateSentiment(template) > 0 ? performance / 8 : (100 - performance) / 8;
    }
    if (category === 'Voting Preparation' && participants.voteMeta) {
      const meta = participants.voteMeta;
      fit += Number(state.voteLandscape?.vulnerability?.[meta.primaryTargetId] || 0) / 7;
      if (meta.planners?.length >= 2) {
        fit += average(meta.planners.slice(1).map(id => planningConnectionScore(meta.planners[0], id, votePool())), 0) / 12;
      }
    }

    fit += storylineContinuationBonus(template, participants);
    fit += participants.reduce((sum, id) => sum + narrativeContinuityFitBonus(template, id), 0) / Math.max(1, participants.length);
    fit += opportunityFitBonus(template, participants);
    fit += participants.reduce((sum, id, role) => sum + Math.max(0, editorialRoleBonus(id, role, template)) * .45, 0);
    fit -= participants.reduce((sum, id) => sum + (usage.get(id) || 0) * 2.5, 0);

    if (state.eventHistory.slice(-26).some(event => event.templateId === template.id)) fit -= 24;
    if (state.eventHistory.slice(-8).some(event => event.category === category)) fit -= 3;
    if (stage === 'preVote' && ['Voting Preparation', 'Post-Challenge Reaction', 'Strategic Conversation'].includes(category)) fit += 6;
    return Math.max(0, fit);
  }


  function chooseForcedVotingPreparationCandidate(stage, usage, usedTemplateIds, usedPairs) {
    if (stage !== 'preVote') return null;
    const preferredNumbers = new Set([1, 2, 4, 11, 16, 17, 20, 21, 27, 28, 29, 34, 35]);
    const poolSize = votePool().length;
    const templates = shuffled(EVENT_LIBRARY.filter(template =>
      template.category === 'Voting Preparation'
      && preferredNumbers.has(votingTemplateNumber(template))
      && !usedTemplateIds.has(template.id)
      && eventTemplateAllowed(template, stage, poolSize)
    )).slice(0, state.autoSimulating ? 18 : 40);
    const candidates = templates.map(template => {
      const participants = chooseParticipants(template, stage, usage, usedPairs);
      return {
        template,
        participants,
        fit: participantFit(template, participants, stage, usage) + 18
      };
    }).filter(candidate => candidate.fit > 0);
    return weightedChoice(candidates, candidate => candidate.fit);
  }

  function chooseAllianceFormationCandidate(stage, usage, usedTemplateIds, usedPairs) {
    const poolSize = groupPoolForCategory('Alliance Formation', stage, 2).length;
    const templates = shuffled(EVENT_LIBRARY.filter(template =>
      template.category === 'Alliance Formation'
      && !usedTemplateIds.has(template.id)
      && eventTemplateAllowed(template, stage, poolSize)
    )).slice(0, state.autoSimulating ? 16 : 42);
    const candidates = templates.map(template => {
      const participants = chooseParticipants(template, stage, usage, usedPairs);
      return {
        template,
        participants,
        fit: participantFit(template, participants, stage, usage) + 12
      };
    }).filter(candidate => candidate.fit > 0);
    return weightedChoice(candidates, candidate => candidate.fit);
  }

  function chooseGeneralPreVoteCandidate(usage, usedTemplateIds, categoryCounts, usedPairs) {
    const generalCategories = new Set([
      'Bonding and Friendship', 'Minor Conflict', 'Major Interpersonal Conflict',
      'Team Dysfunction', 'Emotional and Personal', 'Post-Challenge Reaction',
      'Around Camp', 'Reputation', 'Isolation and Social Exclusion', 'Quitting and Withdrawal'
    ]);
    const poolSize = votePool().length;
    const templates = shuffled(EVENT_LIBRARY.filter(template =>
      generalCategories.has(template.category)
      && !usedTemplateIds.has(template.id)
      && eventTemplateAllowed(template, 'preVote', poolSize)
      && (categoryCounts.get(template.category) || 0) < (EVENT_CATEGORY_LIMITS.preVote[template.category] || 99)
    )).slice(0, state.autoSimulating ? 18 : 54);
    const candidates = templates.map(template => {
      const participants = chooseParticipants(template, 'preVote', usage, usedPairs);
      return {
        template,
        participants,
        fit: participantFit(template, participants, 'preVote', usage) + 10
      };
    }).filter(candidate => candidate.fit > 0);
    return weightedChoice(candidates, candidate => candidate.fit);
  }

  function chooseFastAutoEventCandidate(stage, usage, usedTemplateIds, categoryCounts, usedPairs) {
    const preferredCategories = stage === 'preVote'
      ? [
          'Post-Challenge Reaction', 'Bonding and Friendship', 'Minor Conflict',
          'Emotional and Personal', 'Around Camp', 'Reputation',
          'Isolation and Social Exclusion', 'Team Dysfunction'
        ]
      : [
          'Bonding and Friendship', 'Minor Conflict', 'Emotional and Personal',
          'Around Camp', 'Reputation', 'Team Bonding', 'Team Dysfunction',
          'Isolation and Social Exclusion'
        ];
    const categoryOrder = shuffled(preferredCategories.filter(category => {
      const limit = EVENT_CATEGORY_LIMITS[stage]?.[category] ?? 3;
      return (categoryCounts.get(category) || 0) < limit;
    }));

    for (const category of categoryOrder) {
      const poolSize = groupPoolForCategory(category, stage).length || state.activeIds.length;
      const templates = shuffled(EVENT_LIBRARY.filter(template =>
        template.category === category
        && !usedTemplateIds.has(template.id)
        && eventTemplateAllowed(template, stage, poolSize)
      )).slice(0, 8);
      for (const template of templates) {
        const participants = chooseParticipants(template, stage, usage, usedPairs);
        if (!participants.length || !participantCombinationEligible(template, participants, stage)) continue;
        return { template, participants, fit: 1 };
      }
    }
    return null;
  }

  function chooseEventCandidate(stage, usage, usedTemplateIds, categoryCounts, usedPairs) {
    const categories = Object.keys(EVENT_STAGE_WEIGHTS[stage]);
    const attemptLimit = state.autoSimulating ? 8 : 90;
    const sampleLimit = state.autoSimulating ? 7 : 48;
    const dynamicWeights = new Map(categories.map(name => [name, categoryDynamicWeight(name, stage)]));
    const startedAt = typeof performance !== 'undefined' ? performance.now() : Date.now();
    const timeBudget = state.autoSimulating ? 35 : 320;
    for (let attempt = 0; attempt < attemptLimit; attempt += 1) {
      const now = typeof performance !== 'undefined' ? performance.now() : Date.now();
      if (now - startedAt > timeBudget) break;
      const category = weightedChoice(categories, name => {
        const repetition = categoryCounts.get(name) || 0;
        const limit = EVENT_CATEGORY_LIMITS[stage]?.[name] ?? 3;
        if (repetition >= limit) return 0;
        return Number(dynamicWeights.get(name) || 0) / (1 + repetition * 1.5);
      });
      if (!category) continue;

      const poolSize = groupPoolForCategory(category, stage).length || state.activeIds.length;
      const templates = EVENT_LIBRARY.filter(template =>
        template.category === category
        && !usedTemplateIds.has(template.id)
        && eventTemplateAllowed(template, stage, poolSize)
      );
      if (!templates.length) continue;

      const sampled = shuffled(templates).slice(0, Math.min(sampleLimit, templates.length));
      const candidates = sampled.map(template => {
        const participants = chooseParticipants(template, stage, usage, usedPairs);
        return {
          template,
          participants,
          fit: participantFit(template, participants, stage, usage)
        };
      }).filter(candidate => candidate.fit > 0);

      const chosen = weightedChoice(candidates, candidate => candidate.fit);
      if (chosen) return chosen;
    }
    return null;
  }

  function relationshipChangeText(fromId, toId, delta, mutual = false) {
    const first = state.contestantById.get(fromId)?.nickname || 'Contestant';
    const second = state.contestantById.get(toId)?.nickname || 'Contestant';
    if (mutual) {
      return delta > 0
        ? `${first} and ${second} have improved their relationship.`
        : `${first} and ${second}'s relationship has worsened.`;
    }
    return delta > 0
      ? `${first} feels closer to ${second}.`
      : `${first} feels less positively toward ${second}.`;
  }

  function adjustRelationship(fromId, toId, delta, mutual = false) {
    adjustDirectional(state.directionalRelationships, fromId, toId, delta, -10, 10);
    if (mutual) adjustDirectional(state.directionalRelationships, toId, fromId, delta, -10, 10);
  }


  function nextAllianceName() {
    const used = new Set(state.usedAllianceNames || []);
    const available = ALLIANCE_NAMES.filter(name => !used.has(name));
    let name;
    if (available.length) {
      name = available[Math.floor(Math.random() * available.length)];
    } else {
      let number = 1;
      do {
        name = `Alliance #${number}`;
        number += 1;
      } while (used.has(name));
    }
    state.usedAllianceNames ||= [];
    state.usedAllianceNames.push(name);
    return name;
  }

  function createAlliance(participants, strength = 55, stage = 'preChallenge') {
    const members = [...new Set(participants)].sort(naturalCompare);
    const existing = exactAllianceFor(members);
    if (existing) return existing;

    const compatibility = pairStats(members);
    const memberLoyalty = Object.fromEntries(members.map(id => {
      const traits = traitsFor(id);
      const others = members.filter(memberId => memberId !== id);
      const personalTrust = others.length
        ? others.reduce((sum, otherId) => sum + currentTrust(id, otherId), 0) / others.length
        : 45;
      return [id, clampRange(
        31
        + traits.loyalty * 3.7
        + traits.allianceDependence * 2.4
        + (personalTrust - 45) * .35
        + compatibility.averageRelationship * 3,
        15,
        95
      )];
    }));

    const averageAllianceDependence = average(members.map(id => traitsFor(id).allianceDependence), 5.5);
    const averageInfluence = average(members.map(id => traitsFor(id).influence), 5.5);

    const alliance = {
      id: `alliance-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
      name: nextAllianceName(),
      members,
      strength: clampRange(
        strength
        + compatibility.averageRelationship * 2
        + (compatibility.averageTrust - 45) * .2
        + (averageAllianceDependence - 5.5) * 2.2
        + (averageInfluence - 5.5) * .8
        - Math.max(0, members.length - 3) * 3,
        25,
        88
      ),
      tension: 0,
      memberLoyalty,
      active: true,
      formedEpisode: state.episodeNumber,
      formedStage: stage,
      lastEventEpisode: state.episodeNumber,
      lastEventStage: stage,
      lastMaintainedEpisode: null
    };
    state.alliances.push(alliance);
    return alliance;
  }

  function effectRelationshipDelta(template, fallback) {
    const normalized = String(template.effects || '').replace(/−/g, '-');
    const match = normalized.match(/Relationship(?:s)?[^`]*?([+-]\d+)/i);
    return match ? clampRange(Number(match[1]), -3, 2) : fallback;
  }

  function deriveReputationLabel(template) {
    const source = `${template.title} ${template.effects}`.toLowerCase();
    const labels = [
      ['Helpful', /help|support|comfort|defend|capable/], ['Funny', /funny|laugh|joke|entertain|comedy/],
      ['Strategic', /strategy|strategic|vote|plan|target/], ['Untrustworthy', /lie|deceiv|manipulat|untrust/],
      ['Loyal', /loyal|protect|faithful/], ['Bossy', /bossy|control|command/], ['Lazy', /lazy|chore|refus.*help/],
      ['Clumsy', /clumsy|trip|fall|break|accident/], ['Volatile', /anger|fight|outburst|meltdown/],
      ['Likeable', /friend|bond|popular|likeable/], ['Outsider', /isolat|excluded|alone|outcast/],
      ['Threatening', /threat|dominant|powerful|strong competitor/], ['Brave', /brave|fear|wildlife/]
    ];
    return labels.find(([, pattern]) => pattern.test(source))?.[0] || 'Noticeable';
  }


  function clearCompetingVoteCommitments(voterId, targetId, keepBelow = 18) {
    votePool().forEach(otherId => {
      if (otherId === voterId || otherId === targetId) return;
      const current = getDirectional(state.voteCommitment, voterId, otherId);
      if (current > keepBelow) setDirectional(state.voteCommitment, voterId, otherId, keepBelow, 0, 100);
    });
  }

  function establishVotePlan(voterId, targetId, commitment, source, options = {}) {
    if (!voterId || !targetId || voterId === targetId || !eligibleVoteTargets().includes(targetId)) return;
    const requestedLevel = clampRange(Number(commitment || 0), 0, 100);
    const level = options.hardLock
      ? requestedLevel
      : clampRange(requestedLevel - (requestedLevel >= 80 ? 12 : 6), 0, 90);
    const plan = votePlanFor(voterId);
    if (options.clearOthers !== false && level >= 76) clearCompetingVoteCommitments(voterId, targetId, level >= 88 ? 10 : 22);
    const existing = getDirectional(state.voteCommitment, voterId, targetId);
    setDirectional(state.voteCommitment, voterId, targetId, Math.max(existing, level), 0, 100);
    const existingPriority = getDirectional(state.targetPriority, voterId, targetId);
    setDirectional(state.targetPriority, voterId, targetId, Math.max(existingPriority, Math.min(100, level + 4)), 0, 100);
    plan.actualTarget = options.actualTarget || targetId;
    plan.publicTarget = options.publicTarget || targetId;
    plan.commitment = Math.max(plan.commitment || 0, level);
    plan.isPretending = Boolean(options.isPretending);
    if (source && !plan.sourceEvents.includes(source)) plan.sourceEvents.push(source);
    if (options.promisedTo) {
      const promised = Array.isArray(options.promisedTo) ? options.promisedTo : [options.promisedTo];
      promised.filter(Boolean).forEach(id => {
        if (!plan.promisedTo.includes(id)) plan.promisedTo.push(id);
      });
    }
  }

  function switchVotePlan(voterId, oldTargetId, newTargetId, commitment, source) {
    if (oldTargetId && oldTargetId !== newTargetId) {
      setDirectional(state.voteCommitment, voterId, oldTargetId, 0, 0, 100);
      adjustDirectional(state.targetPriority, voterId, oldTargetId, -20, 0, 100);
    }
    const plan = votePlanFor(voterId);
    plan.preferredTarget = newTargetId;
    plan.actualTarget = newTargetId;
    plan.publicTarget = newTargetId;
    plan.commitment = 0;
    establishVotePlan(voterId, newTargetId, commitment, source);
  }

  function votePitchAcceptance(listenerId, speakerId, targetId, pool = votePool()) {
    const plan = votePlanFor(listenerId);
    const relationship = relationshipAverage(listenerId, speakerId);
    const trust = currentTrust(listenerId, speakerId);
    const agreement = [plan.preferredTarget, plan.backupTarget, plan.actualTarget].includes(targetId) ? 100 : 35;
    const uncertainty = clampRange(100 - (plan.commitment || 0), 0, 100);
    const speakerRuntime = runtimeFor(speakerId);
    const speakerTraits = traitsFor(speakerId);
    const influence = clampRange(speakerRuntime.strategicInfluence + speakerRuntime.socialVisibility * .30 + speakerTraits.influence * 4.2 + speakerTraits.charisma * 2.8 + speakerTraits.intimidation * 1.0, 0, 100);
    const safety = selfPreservationScore(listenerId, targetId, pool);
    let score = trust * .30
      + clampRange((relationship + 5) * 10, 0, 100) * .20
      + agreement * .20
      + safety * .15
      + influence * .10
      + uncertainty * .05;
    score += (speakerTraits.subtlety - 5.5) * 1.2;
    score -= personalProtectionScore(listenerId, targetId, pool) * .70;
    if (pairHadSeriousBetrayal(listenerId, speakerId, 30)) score -= 35;
    const currentTarget = plan.actualTarget;
    if (currentTarget && currentTarget !== targetId && plan.commitment >= 65) score -= 25;
    return clampRange(score, 0, 100);
  }

  function voterNames(ids) {
    return ids.map(id => eventContestantName(id) || 'another camper');
  }

  function sentenceNameList(ids) {
    const names = voterNames(ids);
    if (!names.length) return 'The group';
    if (names.length === 1) return names[0];
    if (names.length === 2) return `${names[0]} and ${names[1]}`;
    return `${names.slice(0, -1).join(', ')}, and ${names.at(-1)}`;
  }

  function applyVotingPreparationEffects(template, participants, voteMeta, effects) {
    const meta = voteMeta || participants.voteMeta || {};
    const number = meta.number || votingTemplateNumber(template);
    const planners = meta.planners || participants.slice(0, -1);
    const primary = meta.primaryTargetId;
    const backup = meta.backupTargetId;
    const decoy = meta.decoyTargetId || backup;
    const source = template.id;
    const targetName = state.contestantById.get(primary)?.nickname || 'the target';
    const backupName = state.contestantById.get(backup)?.nickname || 'the backup target';
    const organizer = planners[0];

    const lockGroup = (ids, level, targetId = primary, options = {}) => {
      ids.filter(id => id && id !== targetId).forEach(id => establishVotePlan(id, targetId, level, source, {
        ...options,
        promisedTo: ids.filter(otherId => otherId !== id)
      }));
    };
    const attemptRecruit = (listenerId, level = 70, targetId = primary) => {
      if (!listenerId || !organizer || !targetId) return false;
      const plan = votePlanFor(listenerId);
      if ([plan.actualTarget, plan.preferredTarget].includes(targetId)) {
        establishVotePlan(listenerId, targetId, Math.max(65, level - 5), source, { promisedTo: organizer });
        effects.push(`${state.contestantById.get(listenerId)?.nickname || 'The undecided voter'} already preferred ${state.contestantById.get(targetId)?.nickname || 'the target'} and confirms the same vote for their own reasons.`);
        return true;
      }
      const acceptance = votePitchAcceptance(listenerId, organizer, targetId);
      if (acceptance >= 54) {
        establishVotePlan(listenerId, targetId, level, source, { promisedTo: organizer });
        effects.push(`${state.contestantById.get(listenerId)?.nickname || 'The undecided voter'} accepts the plan and agrees to vote for ${state.contestantById.get(targetId)?.nickname || 'the target'}.`);
        return true;
      }
      effects.push(`${state.contestantById.get(listenerId)?.nickname || 'The undecided voter'} remains unconvinced and keeps ${state.contestantById.get(plan.actualTarget)?.nickname || 'another option'} as their preferred target.`);
      return false;
    };

    if ([1, 2, 3, 5, 27, 28, 29, 35].includes(number)) {
      const level = number === 29 ? 96 : [1, 27, 28].includes(number) ? 90 : number === 35 ? 86 : 84;
      lockGroup(planners, level);
      if ([27, 28].includes(number) && meta.recruits?.[0]) attemptRecruit(meta.recruits[0], number === 27 ? 88 : 84);
      effects.push(`${sentenceNameList(planners)} ${planners.length === 1 ? 'is' : 'are'} now firmly committed to voting for ${targetName}.`);
      planners.slice(1).forEach(id => {
        adjustDirectional(state.trust, organizer, id, 3, 0, 100);
        adjustDirectional(state.trust, id, organizer, 3, 0, 100);
      });
      return;
    }

    if (number === 4) {
      lockGroup([organizer], 92);
      attemptRecruit(meta.recruits?.[0] || participants[1], 78);
      effects.push(`${state.contestantById.get(organizer)?.nickname || 'The organizer'} is locked on ${targetName}.`);
      return;
    }

    if ([6, 10].includes(number)) {
      lockGroup(planners, number === 6 ? 70 : 58);
      effects.push(`${sentenceNameList(planners)} count ${targetName} as their current target, though the plan is not completely secure.`);
      return;
    }

    if (number === 7) {
      lockGroup(planners, 67);
      const swing = votePool().filter(id => !planners.includes(id) && id !== primary)
        .sort((a, b) => (votePlanFor(a).commitment || 0) - (votePlanFor(b).commitment || 0))[0];
      if (swing) votePlanFor(swing).isSwingVote = true;
      effects.push(`${sentenceNameList(planners)} are leaning toward ${targetName}, but still need ${state.contestantById.get(swing)?.nickname || 'one more voter'} to secure the numbers.`);
      return;
    }

    if (number === 8) {
      planners.forEach(id => adjustDirectional(state.suspicion, id, organizer, 5, 0, 100));
      effects.push(`The promised numbers around ${targetName} do not add up, leaving the plan uncertain.`);
      return;
    }

    if (number === 9) {
      const second = participants[1];
      if (second && canPlanVoteTogether(organizer, second, votePool(), true)) {
        adjustDirectional(state.trust, organizer, second, 2, 0, 100);
        effects.push(`${state.contestantById.get(organizer)?.nickname || 'The organizer'} verifies that ${state.contestantById.get(second)?.nickname || 'their ally'} is genuinely working on the plan against ${targetName}.`);
      }
      return;
    }

    if ([11, 12, 14, 15].includes(number)) {
      lockGroup(planners, number === 15 ? 62 : 84);
      const recruit = meta.swingVoters?.[0] || meta.recruits?.[0] || participants.at(-1);
      votePlanFor(recruit).isSwingVote = true;
      attemptRecruit(recruit, number === 15 ? 55 : 72);
      return;
    }

    if (number === 13) {
      const swing = meta.swingVoters?.[0] || participants[0];
      votePlanFor(swing).isSwingVote = true;
      adjustDirectional(state.targetPriority, swing, primary, 18, 0, 100);
      if (backup) adjustDirectional(state.targetPriority, swing, backup, 18, 0, 100);
      effects.push(`${state.contestantById.get(swing)?.nickname || 'The swing voter'} is weighing ${targetName} against ${backupName} and has not promised either side a vote.`);
      return;
    }

    if (number === 16) {
      lockGroup([organizer], 91);
      planners.filter(id => id !== organizer).forEach(id => attemptRecruit(id, 74));
      return;
    }

    if ([17, 19, 21].includes(number)) {
      lockGroup(planners, number === 17 ? 82 : 78);
      effects.push(`${sentenceNameList(planners)} settle on ${targetName} because the vote appears achievable and unlikely to expose their own allies.`);
      return;
    }

    if (number === 18) {
      lockGroup([organizer], 88);
      const listener = meta.recruits?.[0] || participants[1];
      if (listener) {
        const oldTarget = backup || votePlanFor(listener).actualTarget;
        if (votePitchAcceptance(listener, organizer, primary) >= 52) {
          switchVotePlan(listener, oldTarget, primary, 76, source);
          effects.push(`${state.contestantById.get(listener)?.nickname || 'The listener'} stops pursuing ${state.contestantById.get(oldTarget)?.nickname || 'the personal target'} and switches to the more strategic vote against ${targetName}.`);
        } else {
          effects.push(`${state.contestantById.get(listener)?.nickname || 'The listener'} refuses to abandon their original target.`);
        }
      }
      return;
    }

    if (number === 20) {
      lockGroup([organizer], 90);
      planners.filter(id => id !== organizer).forEach(id => attemptRecruit(id, 72));
      effects.push(`${targetName}'s alliances and social reach are now driving the plan.`);
      return;
    }

    if (number === 22) {
      lockGroup(planners, 94, primary, { publicTarget: decoy, actualTarget: primary, isPretending: true });
      effects.push(`${sentenceNameList(planners)} will publicly name ${state.contestantById.get(decoy)?.nickname || 'the decoy'} while secretly remaining locked on ${targetName}.`);
      return;
    }

    if (number === 23) {
      const selfDecoy = participants[0];
      const ally = participants[1];
      if (ally) establishVotePlan(ally, primary, 88, source, { publicTarget: selfDecoy, actualTarget: primary, isPretending: true, promisedTo: selfDecoy });
      effects.push(`${state.contestantById.get(ally)?.nickname || 'Their ally'} will pretend that ${state.contestantById.get(selfDecoy)?.nickname || 'the volunteer'} is in danger while keeping the real vote on ${targetName}.`);
      return;
    }

    if (number === 24) {
      lockGroup(planners, 87, primary, { publicTarget: backup || primary, actualTarget: primary, isPretending: Boolean(backup) });
      effects.push(`${sentenceNameList(planners)} allow both ${targetName} and ${backupName} to circulate, but their real plan remains ${targetName}.`);
      return;
    }

    if ([25, 26].includes(number)) {
      lockGroup(planners, 88, primary, { publicTarget: decoy || backup, actualTarget: primary, isPretending: true });
      effects.push(`${sentenceNameList(planners)} redirect attention toward ${state.contestantById.get(decoy || backup)?.nickname || 'a false target'} while privately keeping ${targetName} as the real vote.`);
      return;
    }

    if (number === 30) {
      const tested = participants[1];
      if (tested) {
        votePlanFor(tested).publicTarget = backup || primary;
        adjustDirectional(state.suspicion, organizer, tested, 4, 0, 100);
      }
      effects.push(`${state.contestantById.get(organizer)?.nickname || 'The tester'} has not changed their real target; the false name is only a loyalty test.`);
      return;
    }

    if (number === 31) {
      const hesitant = meta.recruits?.[0] || participants[1];
      if (hesitant) {
        const plan = votePlanFor(hesitant);
        if (plan.actualTarget === primary) {
          establishVotePlan(hesitant, primary, 68, source, { promisedTo: organizer });
          effects.push(`${state.contestantById.get(hesitant)?.nickname || 'The hesitant voter'} finally confirms ${targetName}, though the promise is not fully locked.`);
        } else {
          adjustDirectional(state.suspicion, organizer, hesitant, 8, 0, 100);
          effects.push(`${state.contestantById.get(hesitant)?.nickname || 'The hesitant voter'} refuses to confirm ${targetName} and remains committed to ${state.contestantById.get(plan.actualTarget)?.nickname || 'another target'}.`);
        }
      }
      return;
    }

    if ([32, 33].includes(number)) {
      const newTarget = backup || primary;
      planners.forEach(id => switchVotePlan(id, votePlanFor(id).actualTarget, newTarget, number === 33 ? 70 : 78, source));
      effects.push(`${sentenceNameList(planners)} abandon the old plan and switch to ${state.contestantById.get(newTarget)?.nickname || 'the emergency target'}.`);
      return;
    }

    if (number === 34) {
      lockGroup(planners, 70);
      effects.push(`${sentenceNameList(planners)} form a temporary majority around ${targetName}; the agreement is real, but it does not create a lasting alliance.`);
      return;
    }

    lockGroup(planners, 72);
    effects.push(`${sentenceNameList(planners)} are now leaning toward ${targetName}.`);
  }

  function applySeasonEventDevelopment(template, participants, stage) {
    const category = template.category;
    const [first, second] = participants;
    const everyone = participants.filter(id => state.activeIds.includes(id));
    const each = (fn) => everyone.forEach((id, index) => fn(id, index));
    const sentiment = templateSentiment(template);

    if (category === 'Bonding and Friendship') {
      each(id => {
        adjustSeasonSkill(id, 'loyalty', .12);
        adjustSeasonSkill(id, 'honesty', .08);
        adjustSeasonSkill(id, 'aggression', -.04);
        adjustSeasonHidden(id, 'charisma', .10);
        adjustSeasonHidden(id, 'socialAwareness', .05);
      });
    } else if (category === 'Minor Conflict') {
      each(id => {
        adjustSeasonSkill(id, 'aggression', .10);
        adjustSeasonSkill(id, 'loyalty', -.04);
      });
    } else if (category === 'Major Interpersonal Conflict') {
      each(id => {
        adjustSeasonSkill(id, 'aggression', .24);
        adjustSeasonSkill(id, 'loyalty', -.12);
        adjustSeasonSkill(id, 'honesty', -.05);
        adjustSeasonHidden(id, 'charisma', -.06);
        adjustSeasonHidden(id, 'motivation', -.04);
      });
    } else if (category === 'Team Bonding') {
      each((id, index) => {
        adjustSeasonSkill(id, 'loyalty', .10);
        adjustSeasonHidden(id, 'charisma', .05);
        if (index === 0) adjustSeasonHidden(id, 'leadership', .08);
      });
    } else if (category === 'Team Dysfunction') {
      each(id => {
        adjustSeasonSkill(id, 'aggression', .10);
        adjustSeasonSkill(id, 'loyalty', -.08);
        adjustSeasonHidden(id, 'motivation', -.05);
      });
    } else if (category === 'Alliance Formation') {
      each((id, index) => {
        adjustSeasonSkill(id, 'strategy', .12);
        adjustSeasonSkill(id, 'loyalty', .10);
        adjustSeasonHidden(id, 'allianceDependence', .10);
        adjustSeasonHidden(id, 'socialAwareness', .05);
        if (index === 0) {
          adjustSeasonHidden(id, 'leadership', .08);
          adjustSeasonHidden(id, 'influence', .08);
        }
      });
    } else if (category === 'Alliance Maintenance') {
      each(id => {
        adjustSeasonSkill(id, 'loyalty', .14);
        adjustSeasonSkill(id, 'strategy', .05);
        adjustSeasonHidden(id, 'allianceDependence', .08);
        adjustSeasonHidden(id, 'influence', .04);
      });
    } else if (category === 'Alliance Tension and Collapse') {
      each(id => {
        adjustSeasonSkill(id, 'loyalty', -.16);
        adjustSeasonHidden(id, 'allianceDependence', -.10);
        adjustSeasonHidden(id, 'threatManagement', -.05);
      });
    } else if (category === 'Strategic Conversation') {
      each((id, index) => {
        adjustSeasonSkill(id, 'strategy', .17);
        adjustSeasonHidden(id, 'socialAwareness', .10);
        adjustSeasonHidden(id, 'threatManagement', .05);
        if (index === 0) {
          adjustSeasonHidden(id, 'influence', .10);
          adjustSeasonHidden(id, 'subtlety', .07);
        }
      });
    } else if (category === 'Manipulation and Deception') {
      if (first) {
        adjustSeasonSkill(first, 'strategy', .12);
        adjustSeasonSkill(first, 'honesty', -.16);
        adjustSeasonHidden(first, 'deception', .16);
        adjustSeasonHidden(first, 'subtlety', .10);
        adjustSeasonHidden(first, 'influence', .06);
      }
      if (second) adjustSeasonHidden(second, 'socialAwareness', .08);
    } else if (category === 'Voting Preparation') {
      each((id, index) => {
        adjustSeasonSkill(id, 'strategy', .14);
        adjustSeasonHidden(id, 'socialAwareness', .08);
        adjustSeasonHidden(id, 'threatManagement', .06);
        if (index === 0) adjustSeasonHidden(id, 'influence', .07);
      });
    } else if (category === 'Emotional and Personal') {
      each(id => {
        adjustSeasonSkill(id, 'honesty', .09);
        adjustSeasonSkill(id, 'loyalty', .06);
        adjustSeasonHidden(id, 'charisma', .04);
        adjustSeasonHidden(id, 'motivation', .05);
      });
    } else if (category === 'Isolation and Social Exclusion') {
      if (first) {
        adjustSeasonHidden(first, 'allianceDependence', -.08);
        adjustSeasonHidden(first, 'charisma', -.05);
        adjustSeasonHidden(first, 'motivation', -.07);
      }
    } else if (category === 'Post-Challenge Reaction') {
      if (first) {
        const performance = Number(state.challengeResult?.performances?.[first] ?? 50);
        if (sentiment > 0 && performance >= 50) {
          adjustSeasonHidden(first, 'motivation', .12);
          adjustSeasonHidden(first, 'threat', .12);
        } else if (sentiment < 0 || performance < 48) {
          adjustSeasonHidden(first, 'motivation', -.10);
          adjustSeasonHidden(first, 'threat', -.08);
        }
      }
    } else if (category === 'Reputation') {
      if (first) {
        const label = deriveReputationLabel(template);
        if (label === 'Strong Competitor') adjustSeasonHidden(first, 'threat', .15);
        if (label === 'Weak Link') adjustSeasonHidden(first, 'threat', -.10);
        if (label === 'Bossy') adjustSeasonHidden(first, 'leadership', .06);
        if (label === 'Untrustworthy') adjustSeasonHidden(first, 'threatManagement', -.08);
      }
    } else if (category === 'Quitting and Withdrawal') {
      if (first) {
        if (isQuitInterventionTemplate(template)) adjustSeasonHidden(first, 'motivation', .16);
        else adjustSeasonHidden(first, 'motivation', -.18);
      }
    } else if (category === 'Around Camp') {
      if (first && sentiment > 0) {
        adjustSeasonHidden(first, 'charisma', .04);
        adjustSeasonHidden(first, 'hostFavor', .03);
      } else if (first && sentiment < 0) {
        adjustSeasonHidden(first, 'charisma', -.03);
      }
    }
  }

  function applyEventEffects(template, participants, stage, voteMeta = null) {
    const category = template.category;
    const [first, second, third] = participants;
    const firstName = eventContestantName(first) || 'another camper';
    const secondName = eventContestantName(second) || 'another camper';
    const effects = [];
    const team = teamForContestant(first);

    participants.forEach(id => {
      runtimeFor(id).socialVisibility = clampRange(runtimeFor(id).socialVisibility + 2, 0, 100);
      runtimeFor(id).eventAppearances += 1;
      runtimeFor(id).recentCategories.push(category);
      runtimeFor(id).recentCategories = runtimeFor(id).recentCategories.slice(-6);
    });

    const mechanicsMode = template.mechanics?.mode || 'category';
    if (mechanicsMode !== 'replace') {
    if (category === 'Bonding and Friendship') {
      if (second) {
        const delta = Math.max(1, effectRelationshipDelta(template, 1));
        adjustRelationship(first, second, delta, true);
        adjustDirectional(state.trust, first, second, 5, 0, 100);
        adjustDirectional(state.trust, second, first, 5, 0, 100);
        effects.push(relationshipChangeText(first, second, delta, true), 'Mutual trust improved');
      }
      participants.slice(2).forEach(id => {
        adjustRelationship(first, id, 1, true);
        adjustDirectional(state.trust, first, id, 3, 0, 100);
        adjustDirectional(state.trust, id, first, 3, 0, 100);
      });
      participants.forEach(id => adjustRuntime(id, 'morale', 2));
    } else if (category === 'Minor Conflict') {
      if (second) {
        const source = template.effects || '';
        const closeFriends = relationshipAverage(first, second) >= 4
          && currentTrust(first, second) >= 60
          && currentTrust(second, first) >= 60;
        const requestedDelta = Math.min(-1, effectRelationshipDelta(template, -1));
        const delta = closeFriends && !seriousPairTrigger(first, second) ? 0 : requestedDelta;
        const fromId = /\[B\].*Relationship toward \[A\]/i.test(source) ? second : first;
        const toId = fromId === first ? second : first;
        if (delta) {
          adjustRelationship(fromId, toId, delta);
          effects.push(relationshipChangeText(fromId, toId, delta));
        } else {
          effects.push('The friendship holds, but irritation rises');
        }
        adjustDirectional(state.irritation, first, second, closeFriends ? 6 : 10, 0, 100);
        adjustDirectional(state.irritation, second, first, closeFriends ? 4 : 6, 0, 100);
        if (!closeFriends) {
          adjustDirectional(state.suspicion, fromId, toId, 3, 0, 100);
        }
        effects.push('Irritation increased');
      }
      participants.forEach(id => adjustRuntime(id, 'emotionalPressure', 2));
    } else if (category === 'Major Interpersonal Conflict') {
      if (second) {
        const delta = Math.min(-2, effectRelationshipDelta(template, -2));
        adjustRelationship(first, second, delta, true);
        adjustDirectional(state.trust, first, second, -16, 0, 100);
        adjustDirectional(state.trust, second, first, -16, 0, 100);
        adjustDirectional(state.suspicion, first, second, 14, 0, 100);
        adjustDirectional(state.suspicion, second, first, 14, 0, 100);
        adjustDirectional(state.irritation, first, second, 20, 0, 100);
        adjustDirectional(state.irritation, second, first, 20, 0, 100);
        adjustDirectional(state.grudges, first, second, 18, 0, 100);
        adjustDirectional(state.grudges, second, first, 18, 0, 100);
        effects.push(relationshipChangeText(first, second, delta, true), 'Trust dropped sharply', 'A grudge formed');
      }
      participants.forEach(id => adjustRuntime(id, 'emotionalPressure', 10));
      if (team) adjustTeam(team.name, 'cohesion', -5);
    } else if (category === 'Team Bonding') {
      if (team) {
        adjustTeam(team.name, 'cohesion', 5);
        adjustTeam(team.name, 'morale', 4);
        effects.push(`${team.name}: cohesion +5`, `${team.name}: morale +4`);
      }
      if (second) {
        adjustRelationship(first, second, 1, true);
        effects.push(relationshipChangeText(first, second, 1, true));
      }
    } else if (category === 'Team Dysfunction') {
      if (team) {
        adjustTeam(team.name, 'cohesion', -6);
        adjustTeam(team.name, 'morale', -4);
        effects.push(`${team.name}: cohesion -6`, `${team.name}: morale -4`);
      }
      if (second) {
        adjustRelationship(first, second, -1, true);
        adjustRuntime(second, 'isolation', 5);
        effects.push(relationshipChangeText(first, second, -1, true));
      }
    } else if (category === 'Alliance Formation') {
      const baseStrength = participants.length <= 3 ? 60 : 50;
      const alliance = createAlliance(participants, baseStrength, stage);
      for (let a = 0; a < participants.length; a += 1) {
        for (let b = a + 1; b < participants.length; b += 1) {
          adjustDirectional(state.trust, participants[a], participants[b], 5, 0, 100);
          adjustDirectional(state.trust, participants[b], participants[a], 5, 0, 100);
        }
      }
      effects.push(`New ${participants.length}-person alliance`, `Alliance strength ${Math.round(alliance.strength)}`);
    } else if (category === 'Alliance Maintenance') {
      const alliance = existingAllianceFor(participants);
      if (alliance) {
        alliance.strength = clampRange(alliance.strength + 7, 0, 100);
        alliance.tension = clampRange(alliance.tension - 7, 0, 100);
        alliance.lastEventEpisode = state.episodeNumber;
        alliance.lastEventStage = stage;
        alliance.lastMaintainedEpisode = state.episodeNumber;
        participants.forEach(id => {
          alliance.memberLoyalty ||= {};
          const dependence = traitsFor(id).allianceDependence;
          const loyaltyGain = clampRange(3.5 + (dependence - 5.5) * .65, 1.5, 6.5);
          alliance.memberLoyalty[id] = clampRange((alliance.memberLoyalty[id] || 50) + loyaltyGain, 0, 100);
        });
        participants.slice(1).forEach(id => {
          adjustDirectional(state.trust, first, id, 3, 0, 100);
          adjustDirectional(state.trust, id, first, 3, 0, 100);
          adjustDirectional(state.suspicion, first, id, -4, 0, 100);
          adjustDirectional(state.suspicion, id, first, -4, 0, 100);
        });
        effects.push('Alliance strength +7', 'Alliance tension eased');
      }
    } else if (category === 'Alliance Tension and Collapse') {
      const alliance = existingAllianceFor(participants);
      if (alliance) {
        const collapseEvent = isAllianceCollapseTemplate(template);
        const strengthLoss = collapseEvent ? 18 : 9;
        const tensionGain = collapseEvent ? 20 : 12;
        alliance.strength = clampRange(alliance.strength - strengthLoss, 0, 100);
        alliance.tension = clampRange(alliance.tension + tensionGain, 0, 100);
        alliance.lastEventEpisode = state.episodeNumber;
        alliance.lastEventStage = stage;
        participants.forEach(id => {
          alliance.memberLoyalty ||= {};
          const dependence = traitsFor(id).allianceDependence;
          const baseLoss = collapseEvent ? 12 : 6;
          const loyaltyLoss = clampRange(baseLoss + (5.5 - dependence) * .85, baseLoss * .55, baseLoss * 1.55);
          alliance.memberLoyalty[id] = clampRange((alliance.memberLoyalty[id] || 50) - loyaltyLoss, 0, 100);
        });
        if (collapseEvent && (alliance.strength <= 18 || alliance.tension >= 82)) alliance.active = false;
        effects.push(alliance.active ? `Alliance strength -${strengthLoss}` : 'Alliance collapsed');
      }
      if (second) {
        const collapseEvent = isAllianceCollapseTemplate(template);
        const loyaltyPromiseBroken = collapseEvent && (
          hasNarrativePromise(first, second, 'loyalty-promise')
          || hasNarrativePromise(second, first, 'loyalty-promise')
        );
        const relationshipLoss = (collapseEvent ? -2 : -1) + (loyaltyPromiseBroken ? -1 : 0);
        adjustRelationship(first, second, relationshipLoss);
        adjustDirectional(state.suspicion, first, second, 12, 0, 100);
        adjustDirectional(state.grudges, first, second, collapseEvent ? 15 : 7, 0, 100);
        if (loyaltyPromiseBroken) {
          adjustDirectional(state.trust, first, second, -10, 0, 100);
          adjustDirectional(state.trust, second, first, -10, 0, 100);
          adjustDirectional(state.grudges, first, second, 10, 0, 100);
          adjustDirectional(state.grudges, second, first, 10, 0, 100);
          [first, second].forEach(ownerId => {
            runtimeFor(ownerId).promises.forEach(promise => {
              if (promise.key === 'loyalty-promise' && String(promise.toId) === String(ownerId === first ? second : first)) {
                promise.active = false;
                promise.brokenEpisode = state.episodeNumber;
              }
            });
            addNarrativeMemory(ownerId, 'broken-loyalty-promise', {
              aboutId: ownerId === first ? second : first,
              valence: 'negative',
              strength: 3,
              sourceEvent: template.id
            });
          });
          effects.push('A loyalty promise was broken, deepening the betrayal');
        }
        effects.push(relationshipChangeText(first, second, relationshipLoss));
      }
    } else if (category === 'Strategic Conversation') {
      if (stage === 'preVote') prepareVoteLandscape();
      const sharedPlanTargets = participants.flatMap(id => {
        const plan = votePlanFor(id);
        return [plan.actualTarget, plan.preferredTarget, plan.backupTarget].filter(Boolean);
      });
      const targetCounts = sharedPlanTargets.reduce((counts, id) => counts.set(id, (counts.get(id) || 0) + 1), new Map());
      const sharedTarget = [...targetCounts.entries()]
        .filter(([id]) => !participants.includes(id))
        .sort((a, b) => b[1] - a[1])[0]?.[0];
      const target = participants.length >= 3 ? (third || participants.at(-1)) : (sharedTarget || state.voteLandscape?.primaryTarget || '');
      participants.forEach(id => {
        if (target && target !== id) adjustDirectional(state.targetPriority, id, target, 6, 0, 100);
        const influence = traitsFor(id).influence;
        adjustRuntime(id, 'strategicInfluence', clampRange(2.5 + (influence - 5.5) * .35, 1, 5));
      });
      if (target && !participants.includes(target)) effects.push(`${state.contestantById.get(target)?.nickname || 'A contestant'} became a possible target`);
      effects.push(`${firstName}: strategic influence increased`);
    } else if (category === 'Manipulation and Deception') {
      if (second) {
        const actor = traitsFor(first);
        const target = traitsFor(second);
        const successScore = actor.deception + actor.strategy + actor.charisma + (actor.subtlety - 5.5) * .85 + (actor.influence - 5.5) * .45 + currentTrust(second, first) / 12 - target.socialAwareness - getDirectional(state.suspicion, second, first) / 15 + Math.random() * 8;
        if (successScore >= 16) {
          const framed = third || first;
          if (framed !== first) {
            adjustDirectional(state.suspicion, second, framed, 12, 0, 100);
            adjustDirectional(state.targetPriority, second, framed, 10, 0, 100);
          }
          adjustRuntime(first, 'strategicInfluence', 5);
          effects.push(`${secondName} believed the story`, `${firstName}: influence +5`);
        } else {
          adjustRelationship(second, first, -2);
          adjustDirectional(state.trust, second, first, -15, 0, 100);
          adjustDirectional(state.suspicion, second, first, 15, 0, 100);
          addReputation(first, 'Untrustworthy', 2);
          effects.push(`${secondName} saw through it`, relationshipChangeText(second, first, -2));
        }
      }
    } else if (category === 'Voting Preparation') {
      applyVotingPreparationEffects(template, participants, voteMeta, effects);
    } else if (category === 'Emotional and Personal') {
      const pressureRelief = isDeepPersonalTemplate(template) ? -12 : -8;
      adjustRuntime(first, 'emotionalPressure', pressureRelief);
      adjustRuntime(first, 'morale', isDeepPersonalTemplate(template) ? 6 : 4);
      if (second) {
        adjustRelationship(first, second, 1);
        if (traitsFor(second).empathy >= 6) adjustRelationship(second, first, 1);
        adjustDirectional(state.trust, first, second, isDeepPersonalTemplate(template) ? 10 : 7, 0, 100);
        adjustDirectional(state.trust, second, first, 5, 0, 100);
        effects.push(`${firstName} trusts ${secondName} more`, `${firstName}: pressure ${pressureRelief}`);
      } else effects.push(`${firstName}: pressure ${pressureRelief}`, `${firstName}: morale improved`);
    } else if (category === 'Isolation and Social Exclusion') {
      const independence = traitsFor(first).independence;
      const isolationGain = independence >= 8 && template.subcategory === 'Quiet Isolation' ? 5 : 12;
      const moraleLoss = independence >= 8 && template.subcategory === 'Quiet Isolation' ? -2 : -7;
      adjustRuntime(first, 'isolation', isolationGain);
      adjustRuntime(first, 'morale', moraleLoss);
      adjustRuntime(first, 'emotionalPressure', independence >= 8 ? 2 : 6);
      participants.slice(1).forEach(id => {
        if (relationshipAverage(first, id) <= 1) adjustRelationship(first, id, -1);
      });
      effects.push(`${firstName}: isolation +${isolationGain}`, `${firstName}: morale ${moraleLoss}`);
    } else if (category === 'Post-Challenge Reaction') {
      const performance = state.challengeResult?.performances?.[first] ?? 50;
      const sentiment = templateSentiment(template);
      if (sentiment > 0 && performance >= 50) {
        adjustRuntime(first, 'confidence', 7);
        adjustRuntime(first, 'morale', 4);
        addReputation(first, 'Strong Competitor', 1);
        effects.push(`${firstName}: confidence +7`, 'Strong competitor reputation grew');
      } else if (sentiment < 0 || performance < 48) {
        adjustRuntime(first, 'confidence', -6);
        adjustRuntime(first, 'emotionalPressure', 7);
        const losingTeam = teamForContestant(first);
        losingTeam?.members.filter(id => id !== first).forEach(id => {
          adjustDirectional(state.targetPriority, id, first, 5, 0, 100);
        });
        addReputation(first, 'Weak Link', 1);
        effects.push(`${firstName}: confidence -6`, 'Weak-link pressure increased');
      } else {
        adjustRuntime(first, 'confidence', 2);
        adjustRuntime(first, 'emotionalPressure', -2);
        effects.push(`${firstName}: confidence +2`);
      }
    } else if (category === 'Around Camp') {
      const source = `${template.title} ${template.effects}`.toLowerCase();
      if (/fatigue|sleep|awake|exhaust/.test(source)) {
        participants.forEach(id => adjustRuntime(id, 'fatigue', 6));
        effects.push('Fatigue increased');
      }
      if (/morale.*increase|fun|laugh|successful|comfort/.test(source)) {
        participants.forEach(id => adjustRuntime(id, 'morale', 3));
        effects.push('Morale improved');
      }
      if (/morale.*decrease|disaster|broken|ruin|theft/.test(source)) {
        participants.forEach(id => adjustRuntime(id, 'morale', -3));
        effects.push('Morale decreased');
      }
      if (/relationship.*\+1|bond|help/.test(source) && second) {
        adjustRelationship(first, second, 1, true);
        effects.push(relationshipChangeText(first, second, 1, true));
      } else if (/relationship.*(?:-1|−1)|conflict|annoy/.test(source) && second) {
        adjustRelationship(first, second, -1);
        effects.push(relationshipChangeText(first, second, -1));
      }
      addReputation(first, deriveReputationLabel(template), 1);
    } else if (category === 'Reputation') {
      const label = deriveReputationLabel(template);
      addReputation(first, label, 2);
      runtimeFor(first).socialVisibility = clampRange(runtimeFor(first).socialVisibility + 8, 0, 100);
      if (['Untrustworthy', 'Bossy', 'Lazy', 'Volatile', 'Weak Link'].includes(label)) {
        participants.slice(1).forEach(id => adjustDirectional(state.targetPriority, id, first, 5, 0, 100));
      }
      effects.push(`${firstName}: ${label} reputation increased`);
    } else if (category === 'Quitting and Withdrawal') {
      const runtime = runtimeFor(first);
      if (isQuitInterventionTemplate(template)) {
        adjustRuntime(first, 'quitRisk', -16);
        adjustRuntime(first, 'morale', 7);
        adjustRuntime(first, 'isolation', -5);
        runtime.quitStage = Math.max(0, runtime.quitStage - 1);
        runtime.withdrawn = runtime.quitStage > 0;
        effects.push(`${firstName}: quit risk -16`, 'A support intervention helped');
      } else if (isFormalQuitTemplate(template)) {
        runtime.quitStage = 4;
        runtime.withdrawn = true;
        const detail = `${firstName} formally quits during ${stage === 'preChallenge' ? 'camp life before the challenge' : 'camp life before the vote'}.`;
        const departure = setSpecialDeparture('quit', first, detail, stage);
        if (departure) {
          handleDepartureReactions(departure, template, participants);
          effects.push(`${firstName} formally quit the season`, 'QUIT placement recorded', 'The scheduled vote is cancelled');
        }
      } else if (isQuitResolutionTemplate(template)) {
        const source = eventSource(template);
        if (/last-second return|withdrawn but staying/.test(source)) {
          runtime.quitStage = Math.max(1, runtime.quitStage - 1);
          runtime.withdrawn = true;
          adjustRuntime(first, 'quitRisk', -12);
          adjustRuntime(first, 'morale', 5);
          effects.push(`${firstName} remains in the competition`, `${firstName}: quit risk -12`);
        } else {
          runtime.quitStage = Math.max(3, runtime.quitStage);
          runtime.withdrawn = true;
          adjustRuntime(first, 'quitRisk', 6);
          adjustRuntime(first, 'emotionalPressure', 5);
          effects.push(`${firstName} is at critical quit risk`, 'A final intervention may still happen');
        }
      } else {
        const stageGain = runtime.quitRisk >= 70 || runtime.morale <= 25 ? 2 : 1;
        runtime.quitStage = Math.min(3, runtime.quitStage + stageGain);
        runtime.withdrawn = runtime.quitStage >= 1;
        adjustRuntime(first, 'quitRisk', runtime.quitStage >= 3 ? 15 : 10);
        adjustRuntime(first, 'morale', -6);
        adjustRuntime(first, 'isolation', 7);
        effects.push(`${firstName}: quit risk increased`, `Withdrawal stage ${runtime.quitStage}/3`);
      }
    }

    }

    applyStructuredEventMechanics(template, participants, stage, effects);
    applySeasonEventDevelopment(template, participants, stage);

    if (first && state.activeIds.includes(first)) {
      const attention = traitsFor(first).attentionSeeking;
      const categoryBoost = ['Reputation', 'Major Interpersonal Conflict', 'Post-Challenge Reaction'].includes(category) ? 1.2 : 0;
      const visibilityGain = Math.max(0, (attention - 5.5) * .32 + categoryBoost);
      if (visibilityGain > 0) adjustRuntime(first, 'socialVisibility', visibilityGain);
    }

    return [...new Set(effects.filter(Boolean))].slice(0, 4);
  }

  function eventContestantRecord(reference) {
    const id = reference && typeof reference === 'object' ? reference.id : reference;
    return state.contestantById.get(id)
      || state.contestantById.get(String(id))
      || state.contestants.find(contestant => String(contestant.id) === String(id))
      || null;
  }

  function eventContestantName(reference) {
    const contestant = eventContestantRecord(reference);
    return contestant?.nickname || contestant?.fullName || '';
  }

  function eventParticipantsAreValid(template, participants) {
    if (!Array.isArray(participants)) return false;
    const required = requiredEventParticipantCount(template);
    if (participants.length < required) return false;
    const unique = new Set();
    return participants.every(reference => {
      const contestant = eventContestantRecord(reference);
      const id = contestant?.id;
      const key = String(id);
      const isActive = state.activeIds.some(activeId => String(activeId) === key);
      if (!contestant || !isActive || unique.has(key)) return false;
      unique.add(key);
      return true;
    });
  }

  function requiredEventParticipantCount(template) {
    const source = `${template?.title || ''} ${template?.text || ''}`;
    let required = Number(template?.min || 1);
    for (const match of source.matchAll(/\[([A-F])\]/g)) {
      required = Math.max(required, match[1].charCodeAt(0) - 64);
    }
    return Math.min(Number(template?.max || required), required);
  }

  function renderEventTemplateText(source, participants) {
    const names = participants.map(eventContestantName);
    const quitAftermath = activeEventOpportunities('quit-aftermath')[0];
    const formerContestantName = quitAftermath?.aboutId ? eventContestantName(quitAftermath.aboutId) : '';
    const replacements = {
      A: names[0], B: names[1], C: names[2],
      D: names[3], E: names[4], F: names[5],
      Q: formerContestantName || 'a former contestant'
    };
    let text = String(source || '');
    Object.entries(replacements).forEach(([letter, name]) => {
      if (name) text = text.replace(new RegExp(`\\[${letter}\\]`, 'g'), name);
    });
    return text.replace(/\[([A-F])\]/g, (_, letter) => {
      const index = Math.max(0, letter.charCodeAt(0) - 65);
      return names[index] || names.at(-1) || names[0] || 'another camper';
    });
  }

  function renderEventText(template, participants) {
    return renderEventTemplateText(template.text, participants);
  }

  function appendBoldEventNames(container, text, participantIds) {
    const names = [...new Set(participantIds.map(eventContestantName).filter(Boolean))]
      .sort((first, second) => second.length - first.length);
    if (!names.length) {
      container.textContent = text;
      return;
    }
    const escapePattern = value => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const pattern = new RegExp(`(${names.map(escapePattern).join('|')})`, 'g');
    String(text || '').split(pattern).forEach(part => {
      if (!part) return;
      if (names.includes(part)) {
        const strong = document.createElement('strong');
        strong.className = 'event-contestant-name';
        strong.textContent = part;
        container.append(strong);
      } else {
        container.append(document.createTextNode(part));
      }
    });
  }

  function captureRuntimeSnapshot() {
    const cloneMap = map => new Map([...map.entries()].map(([key, value]) => [key, typeof value === 'object' && value !== null ? JSON.parse(JSON.stringify(value)) : value]));
    return {
      directionalRelationships: cloneMap(state.directionalRelationships), trust: cloneMap(state.trust),
      suspicion: cloneMap(state.suspicion), irritation: cloneMap(state.irritation),
      grudges: cloneMap(state.grudges),
      targetPriority: cloneMap(state.targetPriority), voteCommitment: cloneMap(state.voteCommitment),
      votePlans: cloneMap(state.votePlans || new Map()),
      voteLandscape: state.voteLandscape ? JSON.parse(JSON.stringify(state.voteLandscape)) : null,
      contestantRuntime: cloneMap(state.contestantRuntime), teamRuntime: cloneMap(state.teamRuntime),
      alliances: JSON.parse(JSON.stringify(state.alliances)), usedAllianceNames: [...(state.usedAllianceNames || [])], eventHistory: JSON.parse(JSON.stringify(state.eventHistory)),
      activeIds: [...state.activeIds], teams: JSON.parse(JSON.stringify(state.teams)), merged: state.merged,
      currentChallenge: state.currentChallenge,
      usedChallengeIds: [...(state.usedChallengeIds || [])],
      usedIndividualChallengeIds: [...(state.usedIndividualChallengeIds || [])],
      challengeRevealed: Boolean(state.challengeRevealed),
      challengeResult: state.challengeResult ? JSON.parse(JSON.stringify(state.challengeResult)) : null,
      voteResult: state.voteResult ? JSON.parse(JSON.stringify(state.voteResult)) : null,
      voteRevealIndex: state.voteRevealIndex || 0,
      voteCeremonyFinished: Boolean(state.voteCeremonyFinished)
    };
  }

  function restoreRuntimeSnapshot(snapshot) {
    if (!snapshot) return;
    state.directionalRelationships = new Map(snapshot.directionalRelationships);
    state.trust = new Map(snapshot.trust);
    state.suspicion = new Map(snapshot.suspicion);
    state.irritation = new Map(snapshot.irritation);
    state.grudges = new Map(snapshot.grudges || []);
    state.targetPriority = new Map(snapshot.targetPriority);
    state.voteCommitment = new Map(snapshot.voteCommitment);
    state.votePlans = new Map(snapshot.votePlans || []);
    state.voteLandscape = snapshot.voteLandscape ? JSON.parse(JSON.stringify(snapshot.voteLandscape)) : null;
    state.contestantRuntime = new Map(snapshot.contestantRuntime);
    state.teamRuntime = new Map(snapshot.teamRuntime);
    state.alliances = JSON.parse(JSON.stringify(snapshot.alliances));
    state.usedAllianceNames = [...(snapshot.usedAllianceNames || state.alliances.map(alliance => alliance.name).filter(Boolean))];
    state.eventHistory = JSON.parse(JSON.stringify(snapshot.eventHistory));
    state.activeIds = [...(snapshot.activeIds || state.activeIds)];
    state.teams = snapshot.teams ? JSON.parse(JSON.stringify(snapshot.teams)) : state.teams;
    state.merged = Boolean(snapshot.merged);
    state.currentChallenge = snapshot.currentChallenge || state.currentChallenge;
    state.usedChallengeIds = [...(snapshot.usedChallengeIds || state.usedChallengeIds || [])];
    state.usedIndividualChallengeIds = [...(snapshot.usedIndividualChallengeIds || state.usedIndividualChallengeIds || [])];
    state.challengeRevealed = Boolean(snapshot.challengeRevealed);
    state.challengeResult = snapshot.challengeResult ? JSON.parse(JSON.stringify(snapshot.challengeResult)) : null;
    state.voteResult = snapshot.voteResult ? JSON.parse(JSON.stringify(snapshot.voteResult)) : null;
    state.voteRevealIndex = Number(snapshot.voteRevealIndex || 0);
    state.voteCeremonyFinished = Boolean(snapshot.voteCeremonyFinished);
  }

  function recordSectionCheckpoint(name) {
    if (state.autoSimulating) return;
    if (!state.sectionCheckpoints) {
      state.sectionCheckpoints = { episodeStart: null, afterPreChallenge: null, afterChallenge: null, afterPreVote: null, afterVote: null };
    }
    state.sectionCheckpoints[name] = captureRuntimeSnapshot();
  }


  function voteDiscussionTargets(limit = 4) {
    const landscape = prepareVoteLandscape();
    const eligible = eligibleVoteTargets().filter(id => state.contestantById.has(id));
    if (!landscape || eligible.length < 2) return eligible;

    const ordered = [...new Set([
      ...(landscape.targetOrder || []),
      landscape.primaryTarget,
      landscape.secondaryTarget,
      ...eligible.sort((first, second) =>
        Number(landscape.vulnerability?.[second] || 0) - Number(landscape.vulnerability?.[first] || 0)
      )
    ].filter(id => eligible.includes(id)))];

    const expandedLimit = state.episodeOutcome?.doubleElimination ? Math.max(limit, 6) : limit;
    const maximum = Math.min(expandedLimit, eligible.length);
    const minimum = state.episodeOutcome?.doubleElimination ? Math.min(4, maximum) : Math.min(2, maximum);
    const desired = maximum <= minimum ? maximum : randomInteger(minimum, maximum);
    return ordered.slice(0, desired);
  }

  function softlyAdvanceVotePlan(voterId, targetId, strength = 28) {
    if (!voterId || !targetId || voterId === targetId) return;
    const plan = votePlanFor(voterId);
    const priority = getDirectional(state.targetPriority, voterId, targetId);
    const commitment = getDirectional(state.voteCommitment, voterId, targetId);
    setDirectional(state.targetPriority, voterId, targetId, Math.max(priority, strength + 8), 0, 100);
    setDirectional(state.voteCommitment, voterId, targetId, Math.max(commitment, strength), 0, 100);

    const targetFits = [plan.preferredTarget, plan.backupTarget, plan.actualTarget].includes(targetId);
    if (!plan.actualTarget || plan.commitment < 42 || targetFits) plan.actualTarget = targetId;
    plan.publicTarget = targetId;
    plan.commitment = Math.max(plan.commitment || 0, strength);
    if (!plan.sourceEvents.includes('vote-scramble')) plan.sourceEvents.push('vote-scramble');
  }

  function connectedVoteDiscussionGroups(pool, targets) {
    const groups = [];
    state.alliances.filter(alliance => alliance.active).forEach(alliance => {
      const members = alliance.members.filter(id => pool.includes(id) && !targets.includes(id));
      const availableTargets = targets.filter(id => !alliance.members.includes(id));
      if (members.length < 2 || !availableTargets.length) return;
      const targetId = availableTargets
        .map(id => ({
          id,
          score: average(members.map(memberId => Number(state.voteLandscape?.preferenceScores?.[memberId]?.[id] ?? -50)), -50)
            + Number(state.voteLandscape?.vulnerability?.[id] || 0) * .20
        }))
        .sort((first, second) => second.score - first.score)[0]?.id;
      if (!targetId) return;
      groups.push({
        type: 'alliance',
        alliance,
        members: members.slice(0, Math.min(4, members.length)),
        targetId,
        weight: alliance.strength + members.length * 9 - alliance.tension * .35
      });
    });

    for (let firstIndex = 0; firstIndex < pool.length; firstIndex += 1) {
      for (let secondIndex = firstIndex + 1; secondIndex < pool.length; secondIndex += 1) {
        const firstId = pool[firstIndex];
        const secondId = pool[secondIndex];
        if (targets.includes(firstId) || targets.includes(secondId)) continue;
        const relation = relationshipAverage(firstId, secondId);
        const trust = (currentTrust(firstId, secondId) + currentTrust(secondId, firstId)) / 2;
        if (relation < 2 || trust < 50 || pairHadSeriousBetrayal(firstId, secondId, 35)) continue;
        const availableTargets = targets.filter(id => id !== firstId && id !== secondId);
        if (!availableTargets.length) continue;
        const targetId = availableTargets
          .map(id => ({
            id,
            score: Number(state.voteLandscape?.preferenceScores?.[firstId]?.[id] ?? -50)
              + Number(state.voteLandscape?.preferenceScores?.[secondId]?.[id] ?? -50)
          }))
          .sort((first, second) => second.score - first.score)[0]?.id;
        if (!targetId) continue;
        groups.push({
          type: 'friends',
          members: [firstId, secondId],
          targetId,
          weight: 25 + relation * 7 + (trust - 45) * .65
        });
      }
    }
    return groups;
  }

  function buildConnectedVoteDiscussionEvent(group, index = 0) {
    if (!group?.members?.length || !group.targetId) return null;
    const planners = group.members.filter(id => id !== group.targetId);
    if (!planners.length) return null;
    planners.forEach(id => softlyAdvanceVotePlan(id, group.targetId, group.type === 'alliance' ? 42 : 34));
    const plannerNames = sentenceNameList(planners);
    const targetName = eventContestantName(group.targetId);
    const allianceName = group.type === 'alliance' ? group.alliance?.name || 'their alliance' : '';
    return {
      id: `preVote-${state.episodeNumber}-${Date.now()}-connected-${index}`,
      templateId: `dynamic-connected-vote-${group.type}-${index}`,
      category: 'Voting Preparation',
      subcategory: group.type === 'alliance' ? 'Alliance Vote Meeting' : 'Friends Compare Notes',
      title: group.type === 'alliance' ? 'The Alliance Checks Its Numbers' : 'Friends Compare Their Options',
      participants: [...new Set([...planners, group.targetId])],
      allianceName,
      voteMeta: {
        type: group.type,
        primaryTargetId: group.targetId,
        planners: [...planners],
        discussionTargetIds: [group.targetId]
      },
      text: group.type === 'alliance'
        ? `${plannerNames} meet as ${allianceName} and compare what they have heard around camp. They agree that ${targetName} is their most realistic target, but still need to make sure nobody has promised their vote elsewhere.`
        : `${plannerNames} speak privately because they trust each other more than the rest of the group. They compare the competing stories and decide that a vote against ${targetName} makes the most sense for both of them.`,
      effects: [
        `${plannerNames} are leaning toward ${targetName}`,
        group.type === 'alliance' ? `${allianceName} begins coordinating its vote` : 'A trusted friendship becomes part of the vote'
      ],
      stage: 'preVote',
      episode: state.episodeNumber
    };
  }

  function buildVoteScrambleEvents(maxEvents = 2) {
    const landscape = prepareVoteLandscape();
    if (!landscape) return [];

    const pool = landscape.pool.filter(id => state.activeIds.includes(id) && state.contestantById.has(id));
    let targets = voteDiscussionTargets(state.episodeOutcome?.doubleElimination ? 6 : 4);
    if (targets.length < 2 || pool.length < 3) return [];
    if (targets.length >= pool.length) targets = targets.slice(0, Math.max(2, pool.length - 1));
    const nonTargets = pool.filter(id => !targets.includes(id));
    if (!nonTargets.length) return [];

    const speakerByTarget = new Map();
    const usedSpeakers = new Set();
    targets.forEach((targetId, targetIndex) => {
      const candidates = nonTargets
        .map(id => ({
          id,
          score: Number(landscape.preferenceScores?.[id]?.[targetId] ?? -50)
            + Math.random() * 8
            - (usedSpeakers.has(id) ? 5 : 0)
        }))
        .sort((first, second) => second.score - first.score);
      const speakerId = candidates[0]?.id || nonTargets[0];
      speakerByTarget.set(targetId, speakerId);
      usedSpeakers.add(speakerId);
      softlyAdvanceVotePlan(speakerId, targetId, 24 + Math.min(9, targetIndex * 3));
    });

    const speakers = [...new Set([...speakerByTarget.values()])];
    const targetNames = targets.map(eventContestantName).filter(Boolean);
    const openingParticipants = [...new Set([...speakers, ...targets])].slice(0, 6);
    const openingText = targets.length === 2
      ? `${eventContestantName(speakerByTarget.get(targets[0]))} argues that ${targetNames[0]} is the safer vote, while ${eventContestantName(speakerByTarget.get(targets[1]))} pushes ${targetNames[1]} as the bigger long-term problem. Both names begin moving through camp, but neither side can prove it has a majority.`
      : `${sentenceNameList(speakers)} compare the competing plans they have heard around camp. The main names are ${sentenceNameList(targets)}, and each option has supporters, doubts, and at least one person claiming the numbers are already locked.`;

    const events = [{
      id: `preVote-${state.episodeNumber}-${Date.now()}-scramble-0`,
      templateId: 'dynamic-vote-scramble-opening',
      category: 'Voting Preparation',
      subcategory: 'Competing Plans',
      title: targets.length >= 3 ? 'Several Names Reach the Campfire' : 'Two Names Hit the Campfire',
      participants: openingParticipants,
      allianceName: '',
      voteMeta: {
        type: 'scramble',
        primaryTargetId: targets[0],
        backupTargetId: targets[1],
        discussionTargetIds: [...targets],
        planners: [...speakers]
      },
      text: openingText,
      effects: [
        `${sentenceNameList(targets)} are all being discussed as legitimate targets`,
        'No plan has a confirmed majority yet'
      ],
      stage: 'preVote',
      episode: state.episodeNumber
    }];

    const connectedGroups = connectedVoteDiscussionGroups(pool, targets);
    const selectedGroups = [];
    const availableSlots = Math.max(0, maxEvents - events.length);
    const allianceGroup = weightedChoice(connectedGroups.filter(group => group.type === 'alliance'), group => group.weight);
    const firstFriendGroup = weightedChoice(connectedGroups.filter(group => group.type === 'friends'), group => group.weight);

    if (availableSlots === 1) {
      const chosen = weightedChoice(
        [allianceGroup, firstFriendGroup].filter(Boolean),
        group => group.weight * (group.type === 'alliance' ? 1.08 : 1)
      );
      if (chosen) selectedGroups.push(chosen);
    } else if (availableSlots >= 2) {
      if (allianceGroup) selectedGroups.push(allianceGroup);
      const friendGroup = weightedChoice(
        connectedGroups.filter(group => group.type === 'friends'
          && !selectedGroups.some(selected => selected.members.some(id => group.members.includes(id)))),
        group => group.weight
      ) || firstFriendGroup;
      if (friendGroup) selectedGroups.push(friendGroup);
    }

    selectedGroups.slice(0, availableSlots).forEach((group, index) => {
      const event = buildConnectedVoteDiscussionEvent(group, index);
      if (event) events.push(event);
    });

    if (events.length < maxEvents) {
      const swingId = nonTargets
        .filter(id => !speakers.includes(id))
        .sort((first, second) => (votePlanFor(first).commitment || 0) - (votePlanFor(second).commitment || 0))[0]
        || nonTargets[0];
      const firstTarget = targets[0];
      const secondTarget = targets[1];
      if (swingId && firstTarget && secondTarget) {
        votePlanFor(swingId).isSwingVote = true;
        adjustDirectional(state.targetPriority, swingId, firstTarget, 10, 0, 100);
        adjustDirectional(state.targetPriority, swingId, secondTarget, 10, 0, 100);
        const swingPlan = votePlanFor(swingId);
        swingPlan.backupTarget = secondTarget;
        swingPlan.commitment = Math.max(22, Math.min(swingPlan.commitment || 0, 36));
        events.push({
          id: `preVote-${state.episodeNumber}-${Date.now()}-scramble-swing`,
          templateId: 'dynamic-vote-scramble-swing',
          category: 'Voting Preparation',
          subcategory: 'Swing Vote Doubts',
          title: 'Promises Without a Decision',
          participants: [...new Set([swingId, speakerByTarget.get(firstTarget), speakerByTarget.get(secondTarget), firstTarget, secondTarget].filter(Boolean))],
          allianceName: '',
          voteMeta: {
            type: 'swing',
            primaryTargetId: firstTarget,
            backupTargetId: secondTarget,
            swingVoters: [swingId],
            discussionTargetIds: [firstTarget, secondTarget]
          },
          text: `${eventContestantName(swingId)} hears separate pitches against ${eventContestantName(firstTarget)} and ${eventContestantName(secondTarget)}. They reassure both sides without giving either one a firm answer, leaving the vote dependent on a final conversation.`,
          effects: [
            `${eventContestantName(swingId)} remains genuinely undecided`,
            'Both plans still need another reliable vote'
          ],
          stage: 'preVote',
          episode: state.episodeNumber
        });
      }
    }

    return events.slice(0, Math.max(1, maxEvents));
  }

  function buildGeneralPreVoteFallbackEvent() {
    const pool = votePool().filter(id => state.activeIds.includes(id) && state.contestantById.has(id));
    if (pool.length < 2) return null;
    const pairs = [];
    for (let firstIndex = 0; firstIndex < pool.length; firstIndex += 1) {
      for (let secondIndex = firstIndex + 1; secondIndex < pool.length; secondIndex += 1) {
        const firstId = pool[firstIndex];
        const secondId = pool[secondIndex];
        pairs.push({
          firstId,
          secondId,
          score: relationshipAverage(firstId, secondId) * 4
            + (currentTrust(firstId, secondId) + currentTrust(secondId, firstId)) * .20
            + Math.random() * 8
        });
      }
    }
    const pair = pairs.sort((first, second) => second.score - first.score)[0];
    if (!pair) return null;
    adjustRuntime(pair.firstId, 'emotionalPressure', -1);
    adjustRuntime(pair.secondId, 'emotionalPressure', -1);
    return {
      id: `preVote-${state.episodeNumber}-${Date.now()}-general-fallback`,
      templateId: 'dynamic-general-pre-vote-fallback',
      category: 'Around Camp',
      subcategory: 'Campfire Nerves',
      title: 'A Quiet Moment Before Ceremony',
      participants: [pair.firstId, pair.secondId],
      allianceName: '',
      voteMeta: null,
      text: `${eventContestantName(pair.firstId)} and ${eventContestantName(pair.secondId)} step away from the strategy talk for a few minutes. They discuss the challenge, the pressure of the ceremony, and how strange the camp feels when everybody is quietly counting votes.`,
      effects: ['Both contestants release a little pre-ceremony tension'],
      stage: 'preVote',
      episode: state.episodeNumber
    };
  }

  function discussedVoteTargetIds() {
    const eligible = new Set(eligibleVoteTargets());
    const ids = [];
    (state.episodeEvents.preVote || []).forEach(event => {
      const meta = event.voteMeta || {};
      [meta.primaryTargetId, meta.backupTargetId, meta.decoyTargetId, ...(meta.discussionTargetIds || []), ...(meta.pairTargetIds || [])]
        .filter(id => eligible.has(id))
        .forEach(id => { if (!ids.includes(id)) ids.push(id); });
    });
    return ids;
  }

  function generateEventBatch(stage) {
    if (!state.seasonStarted) return;
    if (state.episodeEvents[stage]?.length) {
      showToast('These events have already been generated.');
      return;
    }
    if (stage === 'preVote' && !state.challengeRevealed) {
      showToast('Run the challenge before generating pre-vote events.');
      return;
    }
    if (stage === 'preChallenge' && state.challengeResult) {
      showToast('The challenge has already been locked and cannot be resimulated.');
      return;
    }
    state.eventSnapshots[stage] = state.autoSimulating ? null : captureRuntimeSnapshot();

    if (stage === 'preVote' && state.episodeOutcome?.cancelVote) {
      const twistEvents = consumeTwistEvents(stage);
      if (!twistEvents.length && state.episodeOutcome.departures?.length) {
        const names = state.episodeOutcome.departures.map(item => contestantDisplayName(item.id));
        twistEvents.push(makeTwistEvent({
          stage: 'preVote',
          category: 'Departure',
          title: 'The Ceremony Is Cancelled',
          participants: state.episodeOutcome.departures.map(item => item.id),
          text: `${joinContestantNames(state.episodeOutcome.departures.map(item => item.id))} ${names.length === 1 ? 'has' : 'have'} already left the competition, so Chris cancels the scheduled vote.`,
          effects: ['No regular vote will take place tonight.']
        }));
      }
      twistEvents.forEach(event => state.eventHistory.push(event));
      state.episodeEvents.preVote = twistEvents;
      state.voteResult = null;
      state.voteRevealIndex = 0;
      state.voteCeremonyFinished = false;
      resetVoteCeremonyInterface();
      recordSectionCheckpoint('afterPreVote');
      if (!state.autoSimulating) {
        renderEventBatch(stage);
        renderSeasonOverview();
            renderEpisodeSummary();
        if (elements.continueToVoteBtn) elements.continueToVoteBtn.disabled = twistEvents.length === 0;
        if (elements.generatePreVoteEventsBtn) elements.generatePreVoteEventsBtn.hidden = twistEvents.length > 0;
        if (state.merged && !state.isHistoricalView) syncCurrentEpisodeRecord();
      }
      return;
    }

    if (stage === 'preVote') {
      prepareVoteLandscape(true);
      resolveNarrativePromisesBeforeVote();
    }

    if (stage === 'preChallenge') {
      state.challengeResult = null;
      state.challengeSnapshot = null;
      state.challengeRevealed = false;
      state.episodeEvents.preVote = [];
      state.eventSnapshots.preVote = null;
      state.sectionCheckpoints.afterPreChallenge = null;
      state.sectionCheckpoints.afterChallenge = null;
      state.sectionCheckpoints.afterPreVote = null;
      state.voteResult = null;
      state.votePlans = new Map();
      state.voteLandscape = null;
      state.voteRevealIndex = 0;
      state.voteCeremonyFinished = false;
      resetVoteCeremonyInterface();
      if (elements.continueToPreVoteBtn) elements.continueToPreVoteBtn.disabled = true;
      if (elements.generatePreVoteEventsBtn) elements.generatePreVoteEventsBtn.disabled = true;
      if (elements.continueToVoteBtn) elements.continueToVoteBtn.disabled = true;
      if (elements.challengeReveal) elements.challengeReveal.hidden = true;
      if (elements.runChallengeBtn) {
        elements.runChallengeBtn.hidden = false;
        elements.runChallengeBtn.disabled = true;
      }
    }

    const count = eventCountForCast(state.activeIds.length, stage);
    activeEditorialContext = buildEpisodeEditorialContext(stage, count);
    const usage = new Map();
    const usedTemplateIds = new Set();
    const categoryCounts = new Map();
    const usedPairs = new Map();
    const generated = [];

    const appendDynamicEvent = event => {
      if (!event || generated.length >= count) return false;
      if (!editorialIntensityAllowed(event, activeEditorialContext)) return false;
      const participants = [...new Set((event.participants || []).filter(id => state.activeIds.includes(id) && state.contestantById.has(id)))];
      if (participants.length < 2) return false;
      event.participants = participants;
      participants.forEach(id => usage.set(id, (usage.get(id) || 0) + 1));
      const pair = primaryPair(participants);
      if (pair) usedPairs.set(pair, (usedPairs.get(pair) || 0) + 1);
      usedTemplateIds.add(event.templateId);
      categoryCounts.set(event.category, (categoryCounts.get(event.category) || 0) + 1);
      recordEditorialExposure(participants, event, event.voteMeta || null);
      generated.push(event);
      state.eventHistory.push(event);
      return true;
    };

    const appendCandidate = candidate => {
      if (!candidate || generated.length >= count) return false;
      const { template, participants } = candidate;
      if (!editorialIntensityAllowed(template, activeEditorialContext)) return false;
      if (!eventParticipantsAreValid(template, participants)) return false;
      participants.forEach(id => usage.set(id, (usage.get(id) || 0) + 1));
      const pair = primaryPair(participants);
      if (pair) usedPairs.set(pair, (usedPairs.get(pair) || 0) + 1);
      usedTemplateIds.add(template.id);
      categoryCounts.set(template.category, (categoryCounts.get(template.category) || 0) + 1);
      const voteMeta = participants.voteMeta ? JSON.parse(JSON.stringify(participants.voteMeta)) : null;
      const effects = applyEventEffects(template, participants, stage, voteMeta);
      const relatedAlliance = ['Alliance Formation', 'Alliance Maintenance', 'Alliance Tension and Collapse'].includes(template.category)
        ? existingAllianceFor(participants)
        : null;
      const event = {
        id: `${stage}-${state.episodeNumber}-${Date.now()}-${generated.length}`,
        templateId: template.id,
        category: template.category,
        subcategory: template.subcategory,
        title: renderEventTemplateText(template.title, participants),
        participants: [...participants],
        allianceName: relatedAlliance?.name || '',
        voteMeta,
        text: renderEventText(template, participants),
        effects,
        stage,
        episode: state.episodeNumber
      };
      recordEditorialExposure(participants, template, voteMeta);
      generated.push(event);
      state.eventHistory.push(event);
      return true;
    };

    const narrativeOpportunityEvent = buildNarrativeOpportunityEvent(stage, usage);
    if (narrativeOpportunityEvent) appendDynamicEvent(narrativeOpportunityEvent);

    if (stage === 'preVote') {
      const strategicLimit = Math.min(4, Math.max(2, Math.round(count * .35)));
      buildVoteScrambleEvents(strategicLimit).forEach(appendDynamicEvent);
    }

    if (stage === 'preVote' && generated.length < count) {
      let generalAdded = false;
      for (let attempt = 0; attempt < 5 && generated.length < count; attempt += 1) {
        if (appendCandidate(chooseGeneralPreVoteCandidate(usage, usedTemplateIds, categoryCounts, usedPairs))) {
          generalAdded = true;
          break;
        }
      }
      if (!generalAdded && generated.length < count) appendDynamicEvent(buildGeneralPreVoteFallbackEvent());
    }

    const activeAllianceCount = state.alliances.filter(alliance => alliance.active).length;
    const desiredAllianceCount = Math.max(3, Math.min(10, Math.ceil(state.activeIds.length / 2.25)));
    const allianceShortage = Math.max(0, desiredAllianceCount - activeAllianceCount);
    const allianceFormationChance = clampRange(
      (stage === 'preChallenge' ? .34 : .18) + allianceShortage * .055,
      .16,
      stage === 'preChallenge' ? .68 : .42
    );
    if (generated.length < count && Math.random() < allianceFormationChance) {
      for (let attempt = 0; attempt < 7 && generated.length < count; attempt += 1) {
        if (appendCandidate(chooseAllianceFormationCandidate(stage, usage, usedTemplateIds, usedPairs))) break;
      }
    }

    let attempts = 0;
    while (generated.length < count && attempts < count * 14) {
      if (activeEditorialContext) {
        activeEditorialContext.remainingSlots = count - generated.length;
        activeEditorialContext.forceFocusId = editorialUrgentFocusId(activeEditorialContext);
      }
      const shouldForcePlan = stage === 'preVote' && !generated.some(event => event.category === 'Voting Preparation');
      const candidate = state.autoSimulating
        ? chooseFastAutoEventCandidate(stage, usage, usedTemplateIds, categoryCounts, usedPairs)
        : shouldForcePlan
          ? (chooseForcedVotingPreparationCandidate(stage, usage, usedTemplateIds, usedPairs)
            || chooseEventCandidate(stage, usage, usedTemplateIds, categoryCounts, usedPairs))
          : chooseEventCandidate(stage, usage, usedTemplateIds, categoryCounts, usedPairs);
      attempts += 1;
      appendCandidate(candidate);
    }

    const twistEvents = consumeTwistEvents(stage);
    twistEvents.forEach(event => state.eventHistory.push(event));
    state.episodeEvents[stage] = [...twistEvents, ...generated];
    activeEditorialContext = null;
    if (stage === 'preVote') {
      state.voteResult = null;
      state.voteRevealIndex = 0;
      state.voteCeremonyFinished = false;
      resetVoteCeremonyInterface();
    }
    recordSectionCheckpoint(stage === 'preChallenge' ? 'afterPreChallenge' : 'afterPreVote');
    if (!state.autoSimulating) {
      renderEventBatch(stage);
      renderSeasonOverview();
        renderEpisodeSummary();
      if (stage === 'preChallenge') {
        if (elements.continueToChallengeBtn) elements.continueToChallengeBtn.disabled = state.episodeEvents[stage].length === 0;
        if (elements.generatePreChallengeEventsBtn) elements.generatePreChallengeEventsBtn.hidden = state.episodeEvents[stage].length > 0;
        renderChallengeBoard();
      } else {
        if (elements.continueToVoteBtn) elements.continueToVoteBtn.disabled = state.episodeEvents[stage].length === 0;
        if (elements.generatePreVoteEventsBtn) elements.generatePreVoteEventsBtn.hidden = state.episodeEvents[stage].length > 0;
      }
      if (state.merged && !state.isHistoricalView) syncCurrentEpisodeRecord();
    }
  }

  function createParticipantPortrait(id) {
    const contestant = eventContestantRecord(id);
    const wrap = document.createElement('span');
    wrap.className = 'event-participant';
    if (teamPhaseActive()) {
      const team = teamForContestant(id);
      const teamData = team ? teamOption(team.name) : null;
      if (teamData?.color) {
        wrap.classList.add('has-team-color');
        wrap.style.setProperty('--participant-team-color', teamData.color);
      }
    }
    const image = document.createElement('img');
    image.alt = contestant?.fullName || contestant?.nickname || 'Contestant';
    image.title = contestant?.fullName || contestant?.nickname || 'Contestant';
    if (contestant) setImageWithFallback(image, contestant);
    const name = document.createElement('span');
    name.textContent = contestant?.nickname || contestant?.fullName || 'Unnamed';
    wrap.append(image, name);
    return wrap;
  }

  function ensureSentence(text) {
    const clean = String(text || '').trim();
    if (!clean) return '';
    return /[.!?]$/.test(clean) ? clean : `${clean}.`;
  }

  function naturalizeEffect(effect, event) {
    const text = String(effect || '').trim();
    if (!text) return '';
    let match;
    if ((match = text.match(/^(.+?) & (.+?): relationship ([+-]\d+)$/))) {
      return Number(match[3]) > 0
        ? `${match[1]} and ${match[2]} have improved their relationship.`
        : `${match[1]} and ${match[2]}'s relationship has worsened.`;
    }
    if ((match = text.match(/^(.+?) → (.+?): relationship ([+-]\d+)$/))) {
      return Number(match[3]) > 0
        ? `${match[1]} feels closer to ${match[2]}.`
        : `${match[1]} feels less positively toward ${match[2]}.`;
    }
    if ((match = text.match(/^(.+?): cohesion ([+-]\d+)$/))) {
      return Number(match[2]) > 0 ? `${match[1]} have become more united.` : `${match[1]}'s unity has weakened.`;
    }
    if ((match = text.match(/^(.+?): morale ([+-]\d+)$/))) {
      return Number(match[2]) > 0 ? `${match[1]}'s morale has improved.` : `${match[1]}'s morale has fallen.`;
    }
    if ((match = text.match(/^(.+?): morale improved$/i))) return `${match[1]}'s morale has improved.`;
    if ((match = text.match(/^(.+?): pressure (-?\d+)$/i))) return Number(match[2]) < 0 ? `${match[1]} feels less emotionally pressured.` : `${match[1]} feels more emotionally pressured.`;
    if ((match = text.match(/^(.+?): isolation \+(\d+)$/i))) return `${match[1]} feels more isolated from the other contestants.`;
    if ((match = text.match(/^(.+?): confidence ([+-]\d+)$/i))) return Number(match[2]) > 0 ? `${match[1]} has become more confident.` : `${match[1]}'s confidence has taken a hit.`;
    if ((match = text.match(/^(.+?): strategic influence \+(\d+)$/i))) return `${match[1]} has gained more strategic influence.`;
    if ((match = text.match(/^(.+?): influence \+(\d+)$/i))) return `${match[1]} has gained more influence over the game.`;
    if ((match = text.match(/^(.+?): quit risk -(\d+)$/i))) return `${match[1]} is now less likely to quit.`;
    if ((match = text.match(/^(.+?): quit risk increased$/i))) return `${match[1]} is now more likely to consider quitting.`;
    if ((match = text.match(/^(.+?): (.+?) reputation increased$/i))) return `${match[1]}'s reputation as ${match[2]} has become more established.`;
    if ((match = text.match(/^New (\d+)-person alliance$/i))) {
      if (event.allianceName) return '';
      const names = event.participants.map(id => state.contestantById.get(id)?.nickname || 'Contestant');
      const list = names.length > 2 ? `${names.slice(0, -1).join(', ')}, and ${names.at(-1)}` : names.join(' and ');
      return `${list} have formed a new alliance.`;
    }
    if ((match = text.match(/^Alliance strength (\d+)$/i))) {
      const subject = event.allianceName ? `${event.allianceName} begins` : 'The new alliance begins';
      return Number(match[1]) >= 65 ? `${subject} on strong footing.` : `${subject} as a cautious strategic agreement.`;
    }
    if ((match = text.match(/^Alliance strength ([+-]\d+)$/i))) {
      const subject = event.allianceName || 'The alliance';
      return Number(match[1]) > 0 ? `${subject} has become more stable.` : `${subject} has become less stable.`;
    }
    if ((match = text.match(/^Withdrawal stage (\d+)\/3$/i))) return Number(match[1]) >= 3 ? 'Their withdrawal has reached a critical stage.' : 'They have become more socially withdrawn.';

    const replacements = new Map([
      ['Mutual trust improved', 'They now trust each other more.'],
      ['Trust dropped sharply', 'Their trust in one another has been badly damaged.'],
      ['A grudge formed', 'The conflict has created a lasting grudge.'],
      ['Irritation increased', 'The incident has increased the irritation between them.'],
      ['The friendship holds, but irritation rises', 'Their friendship holds, but the disagreement leaves some irritation behind.'],
      ['Alliance tension eased', event.allianceName ? `${event.allianceName}'s members are less suspicious of one another.` : 'The alliance members are less suspicious of one another.'],
      ['Alliance collapsed', event.allianceName ? `${event.allianceName} has completely fallen apart.` : 'The alliance has completely fallen apart.'],
      ['Vote commitment increased', 'The voters involved are now more committed to the plan.'],
      ['Strong competitor reputation grew', 'The other contestants increasingly see them as a strong competitor.'],
      ['Weak-link pressure increased', 'The other contestants are more likely to view them as the weak link.'],
      ['Fatigue increased', 'The contestants involved have become more fatigued.'],
      ['Morale improved', 'The incident has improved their morale.'],
      ['Morale decreased', 'The incident has lowered their morale.'],
      ['A support intervention helped', 'The support they received has made quitting less likely.'],
      ['A final intervention may still happen', event.participants[1]
        ? `They are at critical risk of quitting, though ${eventContestantName(event.participants[1])} may still intervene.`
        : 'They are at critical risk of quitting, though someone may still intervene.']
    ]);
    if (replacements.has(text)) return replacements.get(text);
    if (/gained vote pressure$/i.test(text)) return ensureSentence(text.replace(/gained vote pressure$/i, 'is now under greater voting pressure'));
    if (/became a possible target$/i.test(text)) return ensureSentence(text.replace(/became a possible target$/i, 'is now being considered as a possible target'));
    if (/believed the story$/i.test(text)) return ensureSentence(text.replace(/believed the story$/i, 'believed the story, allowing the manipulation to succeed'));
    if (/saw through it$/i.test(text)) return ensureSentence(text.replace(/saw through it$/i, 'saw through the manipulation'));
    if (/remains in the competition$/i.test(text)) return ensureSentence(text);
    if (/formally quit the season$/i.test(text)) return ensureSentence(text);
    if (/is at critical quit risk$/i.test(text)) return ensureSentence(text);
    return ensureSentence(text.replace(/\s*[+-]\d+\b/g, '').replace(/\s{2,}/g, ' ').trim());
  }

  function repairGenericEventNames(text, participantIds) {
    const names = [...new Set((participantIds || []).map(eventContestantName).filter(Boolean))];
    if (!names.length) return String(text || '').replace(/\bContestant\b/g, 'another camper');
    let index = 0;
    return String(text || '').replace(/\bContestant\b/g, () => {
      const name = names[index % names.length];
      index += 1;
      return name;
    });
  }

  function createEventTeamRosterGrid(teamRosters) {
    const grid = document.createElement('div');
    grid.className = 'event-team-roster-grid';
    grid.style.setProperty('--event-team-count', String(Math.max(1, teamRosters.length)));
    teamRosters.forEach(team => {
      const data = teamOption(team.name);
      const card = document.createElement('article');
      card.className = 'season-team-card event-team-roster-card';
      card.style.setProperty('--team-color', data.color);

      const head = document.createElement('div');
      head.className = 'season-team-card-head';
      const emblem = document.createElement('img');
      emblem.className = 'season-team-emblem';
      emblem.alt = `${team.name} emblem`;
      setTeamEmblemWithFallback(emblem, data);
      const title = document.createElement('h3');
      title.textContent = team.name;
      head.append(emblem, title);

      const members = document.createElement('div');
      members.className = 'season-team-members';
      (team.members || []).forEach(id => {
        const contestant = state.contestantById.get(id);
        if (!contestant) return;
        const member = document.createElement('div');
        member.className = 'season-team-member';
        const image = document.createElement('img');
        image.alt = contestant.fullName || contestant.nickname || 'Contestant';
        setImageWithFallback(image, contestant);
        const name = document.createElement('span');
        name.textContent = contestant.nickname || contestant.fullName || 'Unnamed';
        member.append(image, name);
        members.append(member);
      });
      card.append(head, members);
      grid.append(card);
    });
    return grid;
  }

  function createEventCard(event) {
    const meta = EVENT_CATEGORY_META[event.category] || { short: event.category, tone: 'camp' };
    const card = document.createElement('article');
    card.className = `camp-event-card event-tone-${meta.tone}`;

    const head = document.createElement('div');
    head.className = 'camp-event-card-head';
    const badge = document.createElement('span');
    badge.className = 'camp-event-category';
    badge.textContent = event.category;
    const title = document.createElement('h3');
    appendBoldEventNames(title, repairGenericEventNames(event.title, event.participants), event.participants);
    head.append(badge, title);

    const participants = document.createElement('div');
    participants.className = 'event-participants';
    event.participants.forEach(id => participants.append(createParticipantPortrait(id)));

    const advantage = document.createElement('div');
    advantage.className = 'event-advantage-row';
    advantage.hidden = !event.advantageImage;
    if (event.advantageImage) {
      const advantageImage = document.createElement('img');
      advantageImage.className = 'event-advantage-image';
      advantageImage.alt = event.advantageLabel || 'Secret advantage';
      setStaticImageFallback(advantageImage, [event.advantageImage, `../${event.advantageImage}`]);
      const advantageCopy = document.createElement('div');
      advantageCopy.className = 'event-advantage-copy';
      const advantageTitle = document.createElement('strong');
      advantageTitle.textContent = event.advantageLabel || 'Secret Advantage';
      const advantageNote = document.createElement('span');
      advantageNote.textContent = 'Possession remains secret from the other contestants.';
      advantageCopy.append(advantageTitle, advantageNote);
      advantage.append(advantageImage, advantageCopy);
    }

    const story = document.createElement('p');
    story.className = 'camp-event-story';
    appendBoldEventNames(story, repairGenericEventNames(event.text, event.participants), event.participants);

    const outcome = document.createElement('p');
    outcome.className = 'camp-event-outcome';
    if (event.category === 'Alliance Formation' && event.allianceName) {
      const names = event.participants.map(id => state.contestantById.get(id)?.nickname || state.contestantById.get(id)?.fullName || 'Contestant');
      const list = names.length > 2 ? `${names.slice(0, -1).join(', ')}, and ${names.at(-1)}` : names.join(' and ');
      outcome.append(document.createTextNode(`${list} have formed `));
      const allianceName = document.createElement('strong');
      allianceName.className = 'event-alliance-name';
      allianceName.textContent = event.allianceName;
      outcome.append(allianceName, document.createTextNode('. '));
    }
    const outcomeText = event.effects
      .map(effect => repairGenericEventNames(effect, event.participants))
      .map(effect => naturalizeEffect(effect, event))
      .filter(Boolean)
      .join(' ');
    if (outcomeText) outcome.append(document.createTextNode(outcomeText));
    const teamRosters = Array.isArray(event.teamRosters) ? event.teamRosters.filter(team => team?.name) : [];
    const rosterGrid = teamRosters.length ? createEventTeamRosterGrid(teamRosters) : null;
    if (!outcome.textContent.trim() && !rosterGrid) outcome.textContent = 'The scene changes how the contestants involved view one another.';

    card.append(head, participants, advantage, story);
    if (rosterGrid) card.append(rosterGrid);
    if (outcome.textContent.trim()) card.append(outcome);
    return card;
  }

  function renderEventBatch(stage) {
    const events = state.episodeEvents[stage] || [];
    const list = stage === 'preChallenge' ? elements.preChallengeEventList : elements.preVoteEventList;
    const empty = stage === 'preChallenge' ? elements.preChallengeEventEmpty : elements.preVoteEventEmpty;
    const count = stage === 'preChallenge' ? elements.preChallengeEventCount : elements.preVoteEventCount;
    if (!list) return;
    list.replaceChildren();
    events.forEach(event => list.append(createEventCard(event)));
    if (empty) empty.hidden = events.length > 0;
    if (count) {
      if (events.length) count.textContent = `${events.length} event${events.length === 1 ? '' : 's'}`;
      else if (stage === 'preVote' && !state.challengeResult) count.textContent = 'Waiting for challenge';
      else count.textContent = 'Not generated';
    }
    const generateButton = stage === 'preChallenge'
      ? elements.generatePreChallengeEventsBtn
      : elements.generatePreVoteEventsBtn;
    if (generateButton) generateButton.hidden = events.length > 0;
  }

  function currentChallengeData() {
    if (state.currentChallenge === RETURN_CHALLENGE.id) return RETURN_CHALLENGE;
    if (FINALE_CHALLENGE_BY_ID.has(state.currentChallenge)) return FINALE_CHALLENGE_BY_ID.get(state.currentChallenge);
    const library = state.merged ? INDIVIDUAL_CHALLENGE_BY_ID : TEAM_CHALLENGE_BY_ID;
    return library.get(state.currentChallenge) || null;
  }

  function challengeSkillSignature(challenge) {
    const ranked = Object.entries(challenge?.skills || {})
      .filter(([, weight]) => Number(weight) > 0)
      .sort((first, second) => Number(second[1]) - Number(first[1]) || first[0].localeCompare(second[0]));
    return ranked.slice(0, 2).map(([key]) => key).join('+') || 'mixed';
  }

  function challengeRotationWeight(challenge, library, usedIds) {
    const recent = [...usedIds].slice(-3).reverse()
      .map(id => library.find(item => item.id === id))
      .filter(Boolean);
    const signature = challengeSkillSignature(challenge);
    let weight = 1;

    recent.forEach((previous, index) => {
      const previousSignature = challengeSkillSignature(previous);
      const previousPrimary = previousSignature.split('+')[0];
      const primary = signature.split('+')[0];
      if (signature === previousSignature) weight *= index === 0 ? .10 : index === 1 ? .35 : .65;
      else if (primary === previousPrimary) weight *= index === 0 ? .25 : index === 1 ? .55 : .78;
    });

    const recentVolatilities = recent.slice(0, 2).map(item => item.volatility);
    if (challenge.volatility === 'chaotic' && !recentVolatilities.includes('chaotic')) weight *= 1.18;
    if (challenge.volatility === 'controlled' && recentVolatilities.every(value => value === 'controlled')) weight *= .55;
    return Math.max(.05, weight);
  }

  function selectFinalRaceChallenge() {
    const existing = FINALE_CHALLENGE_BY_ID.get(state.currentChallenge);
    if (existing && existing.id !== 'finale-final-four-showdown') return existing;
    const challenge = FINALE_RACE_CHALLENGES[randomInteger(0, FINALE_RACE_CHALLENGES.length - 1)]
      || FINALE_RACE_CHALLENGES[0];
    state.currentChallenge = challenge?.id || '';
    return challenge || null;
  }

  function selectChallengeForEpisode() {
    if (state.episodeType === 'return-challenge') {
      state.currentChallenge = RETURN_CHALLENGE.id;
      return RETURN_CHALLENGE;
    }
    if (currentChallengeData()) return currentChallengeData();
    if (state.episodeType === 'finale-race') {
      return selectFinalRaceChallenge();
    }
    if (state.episodeType === 'final-four-showdown') {
      state.currentChallenge = 'finale-final-four-showdown';
      return FINALE_CHALLENGE_BY_ID.get(state.currentChallenge);
    }
    const library = state.merged ? INDIVIDUAL_CHALLENGES : TEAM_CHALLENGES;
    const usedKey = state.merged ? 'usedIndividualChallengeIds' : 'usedChallengeIds';
    let available = library.filter(challenge => !state[usedKey].includes(challenge.id));
    if (!available.length) {
      state[usedKey] = [];
      available = [...library];
    }
    const challenge = weightedChoice(
      available,
      item => challengeRotationWeight(item, library, state[usedKey])
    ) || available[randomInteger(0, available.length - 1)];
    state.currentChallenge = challenge.id;
    state[usedKey].push(challenge.id);
    return challenge;
  }

  function displaySkillName(key) {
    return ALL_SKILLS.find(([skillKey]) => skillKey === key)?.[1]
      || key.charAt(0).toUpperCase() + key.slice(1);
  }

  function renderChallengeIntroduction() {
    const challenge = selectChallengeForEpisode();
    if (!challenge) return;
    if (elements.challengeEyebrow) {
      elements.challengeEyebrow.textContent = state.episodeType === 'return-challenge'
        ? 'Comeback challenge'
        : state.episodeType === 'finale-race'
          ? 'The final challenge'
        : state.episodeType === 'final-four-showdown'
          ? 'Final four elimination challenge'
          : state.merged ? 'Today’s individual challenge' : 'Today’s team challenge';
    }
    if (elements.challengeName) elements.challengeName.textContent = challenge.name;
    if (elements.challengeIntroduction) elements.challengeIntroduction.textContent = `“${challenge.introduction}”`;
    if (elements.challengeHostImage && !elements.challengeHostImage.dataset.fallbackBound) {
      elements.challengeHostImage.dataset.fallbackBound = 'true';
      const candidates = ['images/chris.webp', '../images/chris.webp'];
      let candidateIndex = 0;
      elements.challengeHostImage.onerror = () => {
        candidateIndex += 1;
        if (candidateIndex < candidates.length) elements.challengeHostImage.src = candidates[candidateIndex];
        else elements.challengeHostImage.onerror = null;
      };
      elements.challengeHostImage.src = candidates[0];
    }
  }

  function scaleHundredToFifteen(value) {
    return clampRange(1 + clampRange(value, 0, 100) * 14 / 100, 1, 15);
  }

  function average(values, fallback = 8) {
    const valid = values.filter(value => Number.isFinite(Number(value))).map(Number);
    return valid.length ? valid.reduce((sum, value) => sum + value, 0) / valid.length : fallback;
  }

  function challengeSkillFit(id, challenge) {
    const skills = effectiveSkillsFor(id);
    const entries = Object.entries(challenge.skills || {}).filter(([, weight]) => Number(weight) > 0);
    if (!entries.length) return DEFAULT_STAT;

    const specificityPower = state.merged ? 1.32 : 1.22;
    const adjusted = entries.map(([key, weight]) => [key, Math.pow(Number(weight), specificityPower)]);
    const totalWeight = adjusted.reduce((sum, [, weight]) => sum + weight, 0) || 1;
    return adjusted.reduce(
      (total, [key, weight]) => total + clampRange(skills[key] ?? DEFAULT_STAT, 1, 15) * (weight / totalWeight),
      0
    );
  }

  function challengeCondition(id) {
    const runtime = runtimeFor(id);
    const hidden = effectiveHiddenFor(id);
    const morale = scaleHundredToFifteen(runtime.morale);
    const restedness = scaleHundredToFifteen(100 - runtime.fatigue);
    const confidence = scaleHundredToFifteen(runtime.confidence);
    const pressureCalm = scaleHundredToFifteen(100 - runtime.emotionalPressure);
    const emotionalStability = clampRange(hidden.emotionalStability ?? DEFAULT_STAT, 1, 15);
    const staticComposure = clampRange(hidden.composure ?? DEFAULT_STAT, 1, 15);
    const pressureResistance = clampRange(hidden.pressureResistance ?? DEFAULT_STAT, 1, 15);
    const motivation = clampRange(hidden.motivation ?? DEFAULT_STAT, 1, 15);
    const enthusiasm = clampRange(hidden.enthusiasm ?? DEFAULT_STAT, 1, 15);
    const composure = emotionalStability * .34 + staticComposure * .32 + pressureResistance * .20 + pressureCalm * .14;
    const drive = motivation * .65 + enthusiasm * .35;
    const health = scaleHundredToFifteen(runtime.health ?? 100);
    return clampRange(
      morale * .27
      + restedness * .26
      + confidence * .14
      + composure * .15
      + health * .10
      + drive * .08,
      1,
      15
    );
  }

  function challengeTeamContext(id) {
    if (state.merged) return 8;
    const team = teamForContestant(id);
    if (!team) return 8;
    const teammates = team.members.filter(otherId => otherId !== id && state.activeIds.includes(otherId));
    const teamRuntime = teamRuntimeFor(team.name);
    const relationshipScore = teammates.length
      ? average(teammates.map(otherId => currentRelationship(id, otherId)), 0)
      : 0;
    const trustScore = teammates.length
      ? average(teammates.map(otherId => currentTrust(id, otherId)), 45)
      : 45;
    const irritationScore = teammates.length
      ? average(teammates.map(otherId => getDirectional(state.irritation, id, otherId)), 0)
      : 0;
    const cohesion = scaleHundredToFifteen(teamRuntime.cohesion);
    const teamMorale = scaleHundredToFifteen(teamRuntime.morale);
    const relationships = clampRange(1 + ((relationshipScore + 10) / 20) * 14, 1, 15);
    const trust = scaleHundredToFifteen(trustScore);
    const cooperation = scaleHundredToFifteen(100 - irritationScore);
    return clampRange(
      cohesion * .40
      + teamMorale * .10
      + relationships * .25
      + trust * .15
      + cooperation * .10,
      1,
      15
    );
  }

  function rollChallengeLuck(volatility = 'standard', id = '') {
    let raw;
    if (volatility === 'chaotic') raw = randomInteger(1, 15);
    else if (volatility === 'controlled') {
      raw = clampRange(1 + Math.round(((Math.random() + Math.random() + Math.random()) / 3) * 14), 1, 15);
    } else raw = clampRange(1 + Math.round((Math.random() + Math.random()) * 7), 1, 15);

    if (!id) return raw;
    const consistency = clampRange(currentHidden(id, 'consistency'), 1, 15);
    const pullTowardAverage = clampRange((consistency - 8) * .045, -.26, .30);
    return clampRange(8 + (raw - 8) * (1 - pullTowardAverage), 1, 15);
  }

  function challengeComponentWeights(volatility = 'standard') {
    if (volatility === 'controlled') return { skills: .58, condition: .15, context: .07, luck: .20 };
    if (volatility === 'chaotic') return { skills: .45, condition: .12, context: .06, luck: .37 };
    return { skills: .52, condition: .14, context: .07, luck: .27 };
  }

  function challengeSwingRange(volatility = 'standard') {
    if (volatility === 'chaotic') return [1.20, 2.65];
    if (volatility === 'controlled') return [.65, 1.45];
    return [.90, 2.10];
  }

  function rollChallengePerformanceSwing(id, challenge) {
    const runtime = runtimeFor(id);
    const hidden = effectiveHiddenFor(id);
    const adaptability = clampRange(hidden.adaptability ?? DEFAULT_STAT, 1, 15);
    const recovery = clampRange(hidden.recovery ?? DEFAULT_STAT, 1, 15);
    const stability = clampRange(hidden.emotionalStability ?? DEFAULT_STAT, 1, 15);
    const consistency = clampRange(hidden.consistency ?? DEFAULT_STAT, 1, 15);
    const pressureResistance = clampRange(hidden.pressureResistance ?? DEFAULT_STAT, 1, 15);
    const composure = clampRange(hidden.composure ?? DEFAULT_STAT, 1, 15);
    const volatility = challenge.volatility || 'standard';
    const breakoutBase = volatility === 'chaotic' ? .065 : volatility === 'controlled' ? .025 : .042;
    const collapseBase = volatility === 'chaotic' ? .105 : volatility === 'controlled' ? .042 : .072;
    const underdogLift = Math.max(0, 45 - runtime.confidence) * .00028;
    const overconfidenceRisk = Math.max(0, runtime.confidence - 74) * .00058;
    const consistencyScale = clampRange(1 - (consistency - 8) * .055, .62, 1.38);
    const breakoutChance = clampRange(
      (breakoutBase + (adaptability - 8) * .003 + (recovery - 8) * .002 + underdogLift) * consistencyScale,
      .010,
      .120
    );
    const collapseChance = clampRange(
      (collapseBase
      + (8 - stability) * .003
      + Math.max(0, runtime.emotionalPressure - 22) * .00034
      + Math.max(0, runtime.fatigue - 14) * .00028
      + overconfidenceRisk
      - (pressureResistance - 8) * .0025
      - (composure - 8) * .0018) * consistencyScale,
      .018,
      .155
    );
    const roll = Math.random();
    const [minimum, maximum] = challengeSwingRange(volatility);
    const magnitude = minimum + Math.random() * (maximum - minimum);

    if (roll < breakoutChance) {
      return { type: 'breakout', modifier: magnitude, chance: breakoutChance };
    }
    if (roll < breakoutChance + collapseChance) {
      return { type: 'collapse', modifier: -magnitude, chance: collapseChance };
    }
    return { type: 'normal', modifier: 0, chance: 1 - breakoutChance - collapseChance };
  }

  function challengeHiddenFit(id, challenge) {
    const traits = traitsFor(id);
    const source = `${challenge?.name || ''} ${challenge?.introduction || ''}`.toLowerCase();
    let modifier = 0;

    if (/gross|disgust|food|eat|mud|slime|garbage|toilet|vomit|stink|filth/.test(source)) {
      modifier += (traits.grossTolerance - 5.5) * .10;
    }
    if (/dodge|reflex|catch|avoid|sprint|race|chase|projectile|paintball|ball/.test(source)) {
      modifier += (traits.reactions - 5.5) * .075;
    }
    if (/build|invent|design|improv|talent|perform|create|construct|puzzle|solve/.test(source)) {
      modifier += (traits.creativity - 5.5) * .075;
    }
    if (/danger|risk|trap|choice|route|strategy|maze|navigate/.test(source) || challenge?.volatility === 'chaotic') {
      modifier += (traits.riskCalculation - 5.5) * .060;
    }
    if (/fear|scare|horror|height|cliff|shark|animal|night/.test(source)) {
      modifier += (traits.pressureResistance - 5.5) * .045;
    }

    return clampRange(modifier, -.85, .85);
  }

  function scoreChallengeContestant(id, challenge) {
    const skillFit = challengeSkillFit(id, challenge);
    const condition = challengeCondition(id);
    const teamContext = challengeTeamContext(id);
    const luck = rollChallengeLuck(challenge.volatility, id);
    const weights = challengeComponentWeights(challenge.volatility);
    const hiddenFit = challengeHiddenFit(id, challenge);
    const expectedScore = clampRange(
      skillFit * weights.skills
      + condition * weights.condition
      + teamContext * weights.context
      + luck * weights.luck
      + hiddenFit,
      1,
      15
    );
    const swing = rollChallengePerformanceSwing(id, challenge);
    const score = clampRange(expectedScore + swing.modifier, 1, 15);
    return {
      score,
      expectedScore,
      normalized: clampRange(((score - 1) / 14) * 100, 0, 100),
      skillFit,
      condition,
      teamContext,
      luck,
      hiddenFit,
      swingType: swing.type,
      swingModifier: swing.modifier
    };
  }

  function averageTop(values, count) {
    return average([...values].sort((first, second) => second - first).slice(0, Math.max(1, count)));
  }

  function averageBottom(values, count) {
    return average([...values].sort((first, second) => first - second).slice(0, Math.max(1, count)));
  }

  function aggregateTeamChallengeScore(challenge, details) {
    const scores = details.map(detail => detail.score);
    const teamAverage = average(scores);
    const topTwo = averageTop(scores, Math.min(2, scores.length));
    const bottomTwo = averageBottom(scores, Math.min(2, scores.length));
    if (challenge.resolutionMode === 'weakest-link') {
      return teamAverage * .60 + bottomTwo * .30 + topTwo * .10;
    }
    if (challenge.resolutionMode === 'star') {
      return teamAverage * .40 + averageTop(scores, Math.min(3, scores.length)) * .60;
    }
    if (challenge.resolutionMode === 'last-standing') {
      return Math.max(...scores) * .70 + teamAverage * .30;
    }
    if (challenge.resolutionMode === 'combat') {
      const topHalf = averageTop(scores, Math.max(1, Math.ceil(scores.length / 2)));
      const tacticalExecution = average(details.map(detail => detail.teamContext));
      return teamAverage * .50 + topHalf * .30 + tacticalExecution * .20;
    }
    return teamAverage * .75 + topTwo * .15 + bottomTwo * .10;
  }

  function dominantChallengeSkill(challenge) {
    return Object.entries(challenge?.skills || {})
      .sort((first, second) => Number(second[1]) - Number(first[1]))[0]?.[0] || 'teamwork';
  }

  function challengeSkillMoment(challenge) {
    const phrases = {
      strength: 'the heaviest section',
      speed: 'the fastest stretch',
      endurance: 'the longest stretch',
      agility: 'the most technical obstacle',
      intelligence: 'the central puzzle',
      teamwork: 'the decisive handoff',
      strategy: 'the tactical turning point',
      loyalty: 'the cooperation test',
      honesty: 'the pressure decision',
      aggression: 'the most confrontational section'
    };
    return phrases[dominantChallengeSkill(challenge)] || 'the decisive section';
  }

  function challengeModeMoment(challenge, tone) {
    const positive = {
      'weakest-link': 'the team notices a struggling member early and reorganizes before the delay spreads',
      star: 'their featured performer lands the one moment the challenge depends on',
      'last-standing': 'their final remaining camper steadies themselves at exactly the right time',
      combat: 'a risky tactical call catches the other side completely off guard',
      standard: 'a clean piece of coordination turns a small opening into a lead'
    };
    const negative = {
      'weakest-link': 'one struggling member falls behind and the rest of the team cannot recover the lost time',
      star: 'their featured performer misses the key moment and forces everyone else to improvise',
      'last-standing': 'their strongest remaining camper makes one costly late mistake',
      combat: 'an aggressive tactical move backfires and exposes the whole team',
      standard: 'a small coordination mistake grows into a full-team delay'
    };
    const bank = tone === 'positive' ? positive : negative;
    return bank[challenge?.resolutionMode] || bank.standard;
  }

  function teamCircumstanceChance(volatility = 'standard') {
    if (volatility === 'controlled') return .12;
    if (volatility === 'chaotic') return .34;
    return .22;
  }

  function teamCircumstanceMagnitude(volatility = 'standard') {
    const range = volatility === 'chaotic' ? [1.05, 2.25]
      : volatility === 'controlled' ? [.55, 1.10]
        : [.75, 1.65];
    return range[0] + Math.random() * (range[1] - range[0]);
  }

  function renderChallengeSpecificMoment(challenge, tone, participantIds = []) {
    const bank = Array.isArray(challenge?.comments?.[tone]) ? challenge.comments[tone] : [];
    const specificBank = bank.slice(0, Math.min(5, bank.length));
    if (!specificBank.length) return '';
    const template = specificBank[randomInteger(0, specificBank.length - 1)];
    const usableIds = participantIds.filter(id => state.contestantById.has(id));
    const fallbackId = usableIds[0] || state.activeIds.find(id => state.contestantById.has(id));
    const replacements = {};
    ['A', 'B', 'C'].forEach((letter, index) => {
      const id = usableIds[index % Math.max(1, usableIds.length)] || fallbackId;
      replacements[letter] = id ? contestantDisplayName(id) : 'a contestant';
    });
    return String(template).replace(/\[([ABC])\]/g, (_, letter) => replacements[letter] || replacements.A);
  }

  function buildTeamChallengeCircumstance(teamName, challenge, tone) {
    const team = state.teams.find(entry => entry.name === teamName);
    const members = shuffled((team?.members || []).filter(id => state.activeIds.includes(id)));
    const specificMoment = renderChallengeSpecificMoment(challenge, tone, members);
    if (specificMoment) return specificMoment;

    const challengeName = challenge?.name || 'the challenge';
    const skillMoment = challengeSkillMoment(challenge);
    const modeMoment = challengeModeMoment(challenge, tone);
    const positive = [
      `${teamName} find a cleaner route through ${skillMoment} in ${challengeName}, and the saved time becomes decisive.`,
      `During ${challengeName}, ${modeMoment}.`,
      `${teamName} stay composed through ${skillMoment}, turning an ordinary run into a late surge.`
    ];
    const negative = [
      `${teamName} lose control of ${skillMoment} in ${challengeName}, and the mistake costs them crucial time.`,
      `During ${challengeName}, ${modeMoment}.`,
      `${teamName} look competitive until ${skillMoment} goes wrong and their run begins to unravel.`
    ];
    const options = tone === 'positive' ? positive : negative;
    return options[randomInteger(0, options.length - 1)];
  }

  function rollSharedTeamChallengeCircumstance(teamEntries, challenge) {
    if (!teamEntries.length || Math.random() >= teamCircumstanceChance(challenge?.volatility)) return null;
    const tone = Math.random() < .66 ? 'negative' : 'positive';
    const selected = weightedChoice(teamEntries, entry => {
      const context = Number(entry.averageContext || 8);
      if (tone === 'negative') return Math.max(2, 18 + (10 - context) * 3 + Math.random() * 7);
      return Math.max(2, 15 + context * 2 + Math.random() * 7);
    }) || teamEntries[randomInteger(0, teamEntries.length - 1)];
    const magnitude = teamCircumstanceMagnitude(challenge?.volatility);
    return {
      teamName: selected.name,
      tone,
      modifier: tone === 'positive' ? magnitude : -magnitude,
      text: buildTeamChallengeCircumstance(selected.name, challenge, tone)
    };
  }

  function closeFinishFavoredProbability(gap, threshold = 1.45) {
    if (gap >= threshold) return 1;
    return clampRange(.50 + (gap / threshold) * .42, .50, .92);
  }

  function resolveCloseFinish(favored, challenger, scoreFor, mode = 'winner') {
    if (!favored || !challenger) {
      return { selected: favored || challenger, wasClose: false, upset: false, favoredProbability: 1, gap: 0 };
    }
    const gap = Math.max(0, Number(scoreFor(favored)) - Number(scoreFor(challenger)));
    const favoredProbability = closeFinishFavoredProbability(gap);
    const wasClose = favoredProbability < 1;
    const favoredSelected = !wasClose || Math.random() < favoredProbability;
    return {
      selected: favoredSelected ? favored : challenger,
      wasClose,
      upset: wasClose && !favoredSelected,
      favoredProbability,
      gap,
      mode
    };
  }

  function challengeCommentLetters(text) {
    return [...new Set([...String(text).matchAll(/\[([ABC])\]/g)].map(match => match[1]))];
  }

  function challengeCommentPlaceholderCount(text) {
    return Math.max(1, challengeCommentLetters(text).length);
  }

  function challengeHighlightTeammates(subjectId, tone, needed, performanceDetails) {
    const team = state.merged ? null : teamForContestant(subjectId);
    const candidates = (state.merged ? state.activeIds : (team?.members || []))
      .filter(id => id !== subjectId && state.activeIds.includes(id));
    if (tone === 'positive') {
      candidates.sort((first, second) => performanceDetails[second].score - performanceDetails[first].score);
    } else if (tone === 'negative') {
      candidates.sort((first, second) =>
        relationshipAverage(subjectId, first) - relationshipAverage(subjectId, second)
        || performanceDetails[first].score - performanceDetails[second].score
      );
    } else {
      candidates.sort((first, second) =>
        Math.abs(performanceDetails[first].score - performanceDetails[subjectId].score)
        - Math.abs(performanceDetails[second].score - performanceDetails[subjectId].score)
      );
    }

    const selected = [];
    if (tone === 'negative' && needed >= 2 && candidates.length >= 2) {
      selected.push(candidates[0]);
      const strongest = [...candidates]
        .filter(id => id !== selected[0])
        .sort((first, second) => performanceDetails[second].score - performanceDetails[first].score)[0];
      if (strongest) selected.push(strongest);
    } else {
      selected.push(...candidates.slice(0, needed));
    }

    if (selected.length < needed) {
      const fallbacks = state.activeIds.filter(id => id !== subjectId && !selected.includes(id));
      selected.push(...fallbacks.slice(0, needed - selected.length));
    }
    return selected.slice(0, needed);
  }

  function selectChallengeComment(challenge, tone, subjectId, performanceDetails, usedComments) {
    const teammates = (state.merged
      ? state.activeIds
      : (teamForContestant(subjectId)?.members || []))
      .filter(id => id !== subjectId && state.activeIds.includes(id));
    let candidates = challenge.comments[tone].filter(comment =>
      !usedComments.has(comment)
      && challengeCommentPlaceholderCount(comment) - 1 <= teammates.length
    );
    if (!candidates.length) candidates = challenge.comments[tone].filter(comment => !usedComments.has(comment));
    if (!candidates.length) candidates = [...challenge.comments[tone]];
    const comment = candidates[randomInteger(0, candidates.length - 1)];
    usedComments.add(comment);
    const letters = challengeCommentLetters(comment);
    const supportingLetters = letters.filter(letter => letter !== 'A');
    const supporting = challengeHighlightTeammates(subjectId, tone, supportingLetters.length, performanceDetails);
    const participantIds = [subjectId, ...supporting];
    const contestantName = id => {
      const contestant = state.contestantById.get(id);
      return contestant?.nickname || contestant?.fullName || 'Contestant';
    };
    const replacements = { A: contestantName(subjectId) };
    supportingLetters.forEach((letter, index) => {
      if (supporting[index]) replacements[letter] = contestantName(supporting[index]);
    });
    let rendered = comment;
    Object.entries(replacements).forEach(([letter, name]) => {
      rendered = rendered.replace(new RegExp(`\\[${letter}\\]`, 'g'), name);
    });
    rendered = rendered.replace(/\[([ABC])\]/g, (_, letter) => {
      if (letter === 'A') return contestantName(subjectId);
      const fallback = supporting.find(Boolean) || teammates[0] || subjectId;
      return contestantName(fallback);
    });
    return { tone, subjectId, participantIds, text: rendered, template: comment };
  }

  function selectChallengeHighlights(challenge, performanceDetails) {
    const ranked = state.activeIds
      .map(id => ({ id, score: performanceDetails[id].score }))
      .sort((first, second) => second.score - first.score);
    const usedComments = new Set();

    if (ranked.length <= 5) {
      return ranked.map((entry, index) => {
        const tone = index === 0
          ? 'positive'
          : index === ranked.length - 1
            ? 'negative'
            : 'neutral';
        return selectChallengeComment(challenge, tone, entry.id, performanceDetails, usedComments);
      });
    }

    const positiveIds = ranked.slice(0, 2).map(entry => entry.id);
    const negativeIds = ranked.slice(-2).reverse().map(entry => entry.id);
    const excluded = new Set([...positiveIds, ...negativeIds]);
    const median = average(ranked.map(entry => entry.score));
    const neutralIds = ranked
      .filter(entry => !excluded.has(entry.id))
      .sort((first, second) => Math.abs(first.score - median) - Math.abs(second.score - median))
      .slice(0, 2)
      .map(entry => entry.id);
    return [
      ...positiveIds.map(id => selectChallengeComment(challenge, 'positive', id, performanceDetails, usedComments)),
      ...neutralIds.map(id => selectChallengeComment(challenge, 'neutral', id, performanceDetails, usedComments)),
      ...negativeIds.map(id => selectChallengeComment(challenge, 'negative', id, performanceDetails, usedComments))
    ];
  }

  function prepareChallengeResult() {
    if (state.challengeResult || !state.seasonStarted || !state.episodeEvents.preChallenge.length) return state.challengeResult;
    const challenge = selectChallengeForEpisode();
    const performanceDetails = {};
    const performances = {};
    state.activeIds.forEach(id => {
      const detail = scoreChallengeContestant(id, challenge);
      performanceDetails[id] = detail;
      performances[id] = detail.normalized;
    });

    if (state.merged) {
      const expectedRanking = state.activeIds
        .map(id => ({ id, score: performanceDetails[id].score, tieBreaker: Math.random() }))
        .sort((first, second) => second.score - first.score || second.tieBreaker - first.tieBreaker);
      const finish = resolveCloseFinish(expectedRanking[0], expectedRanking[1], entry => entry.score);
      const winningEntry = finish.selected || expectedRanking[0];
      const individualWinner = winningEntry?.id || state.activeIds[0];
      const rankedIndividuals = [
        winningEntry,
        ...expectedRanking.filter(entry => entry?.id !== winningEntry?.id)
      ].filter(Boolean);
      const highlights = selectChallengeHighlights(challenge, performanceDetails);
      if (finish.upset) {
        const winnerHighlight = highlights.find(highlight => highlight.subjectId === individualWinner);
        if (winnerHighlight) {
          winnerHighlight.tone = 'positive';
          winnerHighlight.text = `${contestantDisplayName(individualWinner)} keeps the run close, then steals the win in the final seconds of a genuine photo finish.`;
          winnerHighlight.template = winnerHighlight.text;
        }
      }
      state.challengeSnapshot = captureRuntimeSnapshot();
      state.challengeResult = {
        challengeId: challenge.id,
        challengeSignature: challengeSkillSignature(challenge),
        merged: true,
        individualWinner,
        expectedWinner: expectedRanking[0]?.id || individualWinner,
        winner: individualWinner,
        winners: [individualWinner],
        loser: null,
        teamScores: [],
        performances,
        performanceDetails,
        rankedIds: rankedIndividuals.map(entry => entry.id),
        closeFinish: finish,
        highlights,
        resultType: state.episodeType === 'finale-race'
          ? 'season-winning final race'
          : state.episodeType === 'final-four-showdown'
            ? 'final four showdown'
            : finish.wasClose
              ? (finish.upset ? 'photo-finish upset' : 'photo finish')
              : 'individual immunity',
        revealed: false,
        effectsApplied: false
      };
      state.challengeRevealed = false;
      if (elements.generatePreChallengeEventsBtn) {
        elements.generatePreChallengeEventsBtn.disabled = true;
        elements.generatePreChallengeEventsBtn.hidden = true;
      }
      if (!state.autoSimulating) {
        renderChallengeIntroduction();
        renderChallengeBoard();
      }
      return state.challengeResult;
    }

    let teamScores = state.teams
      .map(team => {
        const memberIds = team.members.filter(id => state.activeIds.includes(id));
        const details = memberIds.map(id => performanceDetails[id]);
        const baseScore15 = aggregateTeamChallengeScore(challenge, details);
        return {
          name: team.name,
          memberIds,
          baseScore15,
          averageContext: average(details.map(detail => detail.teamContext), 8),
          score15: baseScore15,
          score: 0,
          incident: null,
          tieBreaker: Math.random()
        };
      })
      .filter(team => team.memberIds.length > 0);

    const sharedCircumstance = rollSharedTeamChallengeCircumstance(teamScores, challenge);
    teamScores.forEach(team => {
      if (sharedCircumstance?.teamName === team.name) team.incident = { ...sharedCircumstance };
      team.score15 = clampRange(team.baseScore15 + (team.incident?.modifier || 0), 1, 15);
      team.score = clampRange(((team.score15 - 1) / 14) * 100, 0, 100);
    });
    const expectedRanking = [...teamScores]
      .sort((first, second) => second.score15 - first.score15 || second.tieBreaker - first.tieBreaker);

    let loser;
    let winningEntries;
    let closeFinish;

    if (expectedRanking.length <= 2) {
      closeFinish = resolveCloseFinish(expectedRanking[0], expectedRanking[1], entry => entry.score15);
      const winner = closeFinish.selected || expectedRanking[0];
      loser = expectedRanking.find(entry => entry !== winner) || expectedRanking.at(-1);
      winningEntries = [winner].filter(Boolean);
    } else {
      const expectedLoser = expectedRanking.at(-1);
      const challenger = expectedRanking.at(-2);
      const gap = Math.max(0, challenger.score15 - expectedLoser.score15);
      const favoredProbability = closeFinishFavoredProbability(gap);
      const wasClose = favoredProbability < 1;
      const expectedLoserSelected = !wasClose || Math.random() < favoredProbability;
      loser = expectedLoserSelected ? expectedLoser : challenger;
      closeFinish = {
        selected: loser,
        wasClose,
        upset: wasClose && !expectedLoserSelected,
        favoredProbability,
        gap,
        mode: 'loser'
      };
      winningEntries = expectedRanking.filter(team => team !== loser);
    }

    winningEntries.sort((first, second) => second.score15 - first.score15 || second.tieBreaker - first.tieBreaker);
    teamScores = [...winningEntries, loser].filter(Boolean);
    const winners = winningEntries.map(team => team.name);
    const closestWinner = winningEntries.at(-1) || teamScores[0];
    const margin = Math.abs(Number(closestWinner?.score15 || 0) - Number(loser?.score15 || 0));
    const resultType = closeFinish?.upset
      ? 'photo-finish upset'
      : margin < .30
        ? 'photo finish'
        : margin < .85
          ? 'close result'
          : margin < 1.75
            ? 'clear win'
            : 'complete blowout';
    const highlights = selectChallengeHighlights(challenge, performanceDetails);
    state.challengeSnapshot = captureRuntimeSnapshot();
    state.challengeResult = {
      challengeId: challenge.id,
      challengeSignature: challengeSkillSignature(challenge),
      winner: winners[0],
      winners,
      loser: loser?.name || '',
      expectedWinner: expectedRanking[0]?.name || winners[0],
      expectedLoser: expectedRanking.at(-1)?.name || loser?.name || '',
      teamScores,
      performances,
      performanceDetails,
      closeFinish,
      highlights,
      resultType,
      challengeCircumstance: sharedCircumstance,
      teamReactions: {},
      revealed: false,
      effectsApplied: false
    };
    state.challengeRevealed = false;
    if (elements.generatePreChallengeEventsBtn) {
      elements.generatePreChallengeEventsBtn.disabled = true;
      elements.generatePreChallengeEventsBtn.hidden = true;
    }
    if (!state.autoSimulating) {
      renderChallengeIntroduction();
      renderChallengeBoard();
    }
    return state.challengeResult;
  }

  function challengeFatigueRange(challenge) {
    const enduranceWeight = Number(challenge.skills.endurance || 0);
    if (enduranceWeight >= .40) return [10, 15];
    if (enduranceWeight >= .25) return [7, 12];
    return [5, 9];
  }

  function applyChallengeInteractionEffect(highlight) {
    const [firstId, secondId] = highlight.participantIds;
    if (!firstId || !secondId) return;
    const source = highlight.template.toLowerCase();
    if (highlight.tone === 'positive' && /coordinat|cover each other|helps? |guid|clear jobs|divide the work|cooperat|communication|recover lost time|fixes?/.test(source)) {
      adjustDirectional(state.directionalRelationships, firstId, secondId, 1, -10, 10);
      adjustDirectional(state.directionalRelationships, secondId, firstId, 1, -10, 10);
      adjustDirectional(state.trust, firstId, secondId, 4, 0, 100);
      adjustDirectional(state.trust, secondId, firstId, 4, 0, 100);
      adjustSeasonSkill(firstId, 'loyalty', .05);
      adjustSeasonSkill(secondId, 'loyalty', .05);
    }
    if (highlight.tone === 'negative' && /argu|blam|refuses? help|terrible instructions|criticiz|shouting|fight|drags?/.test(source)) {
      adjustDirectional(state.directionalRelationships, firstId, secondId, -1, -10, 10);
      adjustDirectional(state.directionalRelationships, secondId, firstId, -1, -10, 10);
      adjustDirectional(state.irritation, firstId, secondId, 8, 0, 100);
      adjustDirectional(state.irritation, secondId, firstId, 8, 0, 100);
      adjustDirectional(state.trust, firstId, secondId, -3, 0, 100);
      adjustDirectional(state.trust, secondId, firstId, -3, 0, 100);
      adjustSeasonSkill(firstId, 'aggression', .07);
      adjustSeasonSkill(secondId, 'aggression', .07);
      adjustSeasonSkill(firstId, 'loyalty', -.03);
      adjustSeasonSkill(secondId, 'loyalty', -.03);
    }
  }

  function nudgeToward(value, target, amount) {
    const current = Number(value);
    if (!Number.isFinite(current) || current === target) return target;
    if (current < target) return Math.min(target, current + amount);
    return Math.max(target, current - amount);
  }

  function softenChallengeMomentum() {
    state.activeIds.forEach(id => {
      const runtime = runtimeFor(id);
      const hidden = effectiveHiddenFor(id);
      const confidenceTarget = clampRange(50 + (Number(hidden.confidence ?? DEFAULT_STAT) - 8) * 4, 28, 72);
      const pressureTarget = clampRange(
        18
        + (Number(hidden.pressure ?? DEFAULT_STAT) - 8) * 2.2
        - (Number(hidden.pressureResistance ?? DEFAULT_STAT) - 8) * 1.2,
        5,
        35
      );
      runtime.morale = nudgeToward(runtime.morale, 50, .75);
      runtime.confidence = nudgeToward(runtime.confidence, confidenceTarget, .75);
      runtime.emotionalPressure = nudgeToward(runtime.emotionalPressure, pressureTarget, .60);
    });
    state.teams.forEach(team => {
      const runtime = teamRuntimeFor(team.name);
      runtime.morale = nudgeToward(runtime.morale, 50, .85);
      runtime.cohesion = nudgeToward(runtime.cohesion, 50, .55);
    });
  }

  function chooseLosingTeamReaction(team) {
    const runtime = teamRuntimeFor(team.name);
    const members = team.members.filter(id => state.activeIds.includes(id));
    const averagePressure = members.length
      ? average(members.map(id => runtimeFor(id).emotionalPressure), 18)
      : 18;
    return weightedChoice([
      { type: 'collapse', label: 'The loss causes another argument.' },
      { type: 'frustration', label: 'The team is frustrated, but does not completely fall apart.' },
      { type: 'wake-up', label: 'The loss becomes a wake-up call.' },
      { type: 'rally', label: 'The underdogs regroup and leave more determined.' }
    ], reaction => {
      if (reaction.type === 'collapse') return 18 + Math.max(0, 48 - runtime.cohesion) * .45 + averagePressure * .10;
      if (reaction.type === 'frustration') return 25 + averagePressure * .08;
      if (reaction.type === 'wake-up') return 30 + Math.max(0, 58 - runtime.morale) * .30;
      return 24 + Math.max(0, 55 - runtime.morale) * .35;
    });
  }

  function applyLosingTeamReaction(team, reaction) {
    const members = team.members.filter(id => state.activeIds.includes(id));
    if (reaction.type === 'collapse') {
      adjustTeam(team.name, 'morale', -3);
      adjustTeam(team.name, 'cohesion', -2);
      members.forEach(id => {
        adjustRuntime(id, 'morale', -2);
        adjustRuntime(id, 'emotionalPressure', 3);
      });
      return;
    }
    if (reaction.type === 'frustration') {
      adjustTeam(team.name, 'morale', -2);
      members.forEach(id => adjustRuntime(id, 'emotionalPressure', 2));
      return;
    }
    if (reaction.type === 'wake-up') {
      adjustTeam(team.name, 'morale', 1);
      adjustTeam(team.name, 'cohesion', 1);
      members.forEach(id => {
        adjustRuntime(id, 'confidence', 1);
        adjustRuntime(id, 'emotionalPressure', -1);
      });
      return;
    }
    adjustTeam(team.name, 'morale', 2);
    adjustTeam(team.name, 'cohesion', 1);
    members.forEach(id => {
      adjustRuntime(id, 'morale', 1);
      adjustRuntime(id, 'confidence', 1);
    });
  }

  function applyChallengeEffects() {
    const result = state.challengeResult;
    if (!result || result.effectsApplied) return;
    const challenge = currentChallengeData();
    const [fatigueMinimum, fatigueMaximum] = challengeFatigueRange(challenge);
    softenChallengeMomentum();
    state.activeIds.forEach(id => adjustRuntime(id, 'fatigue', randomInteger(fatigueMinimum, fatigueMaximum)));

    if (result.merged) {
      const winnerId = result.individualWinner || result.winner;
      if (winnerId) {
        adjustRuntime(winnerId, 'morale', 2);
        adjustRuntime(winnerId, 'confidence', 3);
        adjustRuntime(winnerId, 'strategicInfluence', 1);
        adjustRuntime(winnerId, 'fatigue', 2);
        addReputation(winnerId, 'Strong Competitor', 1);
        adjustSeasonHidden(winnerId, 'threat', .18);
        adjustSeasonHidden(winnerId, 'motivation', .08);
        if (Number(challenge.skills?.strategy || 0) >= .15) adjustSeasonSkill(winnerId, 'strategy', .06);
      }
    } else {
      const winningTeamNames = Array.isArray(result.winners) && result.winners.length
        ? result.winners
        : [result.winner].filter(Boolean);
      state.teams.forEach(team => {
        if (winningTeamNames.includes(team.name)) {
          adjustTeam(team.name, 'morale', 2);
          adjustTeam(team.name, 'cohesion', 1);
          team.members.filter(id => state.activeIds.includes(id)).forEach(id => {
            adjustRuntime(id, 'morale', 1);
            adjustRuntime(id, 'confidence', .5);
            adjustRuntime(id, 'fatigue', 1);
          });
        } else if (team.name === result.loser) {
          const reaction = chooseLosingTeamReaction(team);
          result.teamReactions ||= {};
          result.teamReactions[team.name] = reaction;
          applyLosingTeamReaction(team, reaction);
        }
      });
    }

    result.highlights.forEach(highlight => {
      if (highlight.tone === 'positive') {
        adjustRuntime(highlight.subjectId, 'confidence', 2);
        adjustSeasonHidden(highlight.subjectId, 'threat', .08);
        adjustSeasonHidden(highlight.subjectId, 'motivation', .05);
        if (Number(challenge.skills?.strategy || 0) >= .18) adjustSeasonSkill(highlight.subjectId, 'strategy', .05);
        adjustRuntime(highlight.subjectId, 'morale', 1);
        adjustRuntime(highlight.subjectId, 'socialVisibility', 2);
        addReputation(highlight.subjectId, 'Strong Competitor', 1);
      } else if (highlight.tone === 'negative') {
        adjustRuntime(highlight.subjectId, 'confidence', -2);
        adjustSeasonHidden(highlight.subjectId, 'threat', -.05);
        adjustSeasonHidden(highlight.subjectId, 'motivation', -.04);
        adjustRuntime(highlight.subjectId, 'emotionalPressure', 2);
        adjustRuntime(highlight.subjectId, 'socialVisibility', 2);
        addReputation(highlight.subjectId, 'Weak Link', 1);
      } else {
        adjustRuntime(highlight.subjectId, 'confidence', .5);
      }
      applyChallengeInteractionEffect(highlight);
    });

    result.effectsApplied = true;
    recordSectionCheckpoint('afterChallenge');
  }

  function runChallenge() {
    if (!state.seasonStarted || !state.episodeEvents.preChallenge.length) {
      showToast('Generate the before-challenge events first.');
      return;
    }
    const result = prepareChallengeResult();
    if (!result || state.challengeRevealed) return;

    const alreadySimulated = Boolean(result.effectsApplied);
    state.challengeRevealed = true;
    result.revealed = true;
    if (!alreadySimulated) applyChallengeEffects();

    if (!alreadySimulated) {
      state.episodeEvents.preVote = [];
      state.eventSnapshots.preVote = null;
      state.sectionCheckpoints.afterPreVote = null;
      state.voteResult = null;
      state.voteRevealIndex = 0;
      state.voteCeremonyFinished = false;
      resetVoteCeremonyInterface();
      if (elements.generatePreVoteEventsBtn) {
        elements.generatePreVoteEventsBtn.disabled = false;
        elements.generatePreVoteEventsBtn.hidden = false;
      }
      if (elements.continueToVoteBtn) elements.continueToVoteBtn.disabled = true;
      if (elements.preVoteEventCount) elements.preVoteEventCount.textContent = 'Not generated';
      renderEventBatch('preVote');
    }

    if (elements.runChallengeBtn) elements.runChallengeBtn.hidden = true;
    if (elements.continueToPreVoteBtn) elements.continueToPreVoteBtn.disabled = false;
    renderChallengeBoard();
    renderSeasonOverview();
    renderEpisodeSummary();
    syncCurrentEpisodeRecord();
    if (state.episodeType === 'finale-race') {
      focusFinaleMoment('.challenge-individual-winner-card');
      launchFinaleConfetti();
    }
  }

  function createChallengePortrait(id) {
    const contestant = state.contestantById.get(id);
    const wrap = document.createElement('span');
    wrap.className = 'challenge-participant';
    const team = teamForCurrentEpisodeContestant(id);
    const teamData = team ? teamOption(team.name) : null;
    if (teamData?.color) wrap.style.setProperty('--challenge-team-color', teamData.color);
    const image = document.createElement('img');
    image.alt = contestant?.fullName || contestant?.nickname || 'Contestant';
    image.title = contestant?.fullName || contestant?.nickname || 'Contestant';
    if (contestant) setImageWithFallback(image, contestant);
    const name = document.createElement('span');
    name.textContent = contestant?.nickname || contestant?.fullName || 'Contestant';
    wrap.append(image, name);
    return wrap;
  }

  function renderChallengeHighlights() {
    if (!elements.challengeHighlights) return;
    elements.challengeHighlights.replaceChildren();
    if (!state.challengeRevealed || !state.challengeResult) return;
    const labels = {
      positive: 'Challenge High',
      neutral: 'Held Their Own',
      negative: 'Challenge Low'
    };
    state.challengeResult.highlights.forEach(highlight => {
      const card = document.createElement('article');
      card.className = `challenge-highlight-card is-${highlight.tone}`;
      const subjectId = highlight.subjectId || highlight.participantIds[0];
      const portrait = createChallengePortrait(subjectId);
      portrait.classList.add('is-highlight-subject');
      const copy = document.createElement('div');
      copy.className = 'challenge-highlight-copy';
      const label = document.createElement('span');
      label.className = 'challenge-highlight-label';
      const swingType = state.challengeResult.performanceDetails?.[subjectId]?.swingType;
      label.textContent = swingType === 'breakout'
        ? 'Breakout Performance'
        : swingType === 'collapse'
          ? 'Challenge Collapse'
          : labels[highlight.tone];
      const text = document.createElement('p');
      text.textContent = highlight.text;
      copy.append(label, text);
      card.append(portrait, copy);
      elements.challengeHighlights.append(card);
    });
  }

  function individualWinnerCircumstance(result, challenge, winnerId) {
    const winnerDetail = result?.performanceDetails?.[winnerId];
    if (winnerDetail?.swingType === 'breakout') {
      return renderChallengeSpecificMoment(challenge, 'positive', [winnerId])
        || `${contestantDisplayName(winnerId)} produces an unexpected breakout during ${challenge?.name || 'the challenge'} and peaks at exactly the right moment.`;
    }
    const expectedWinnerId = result?.expectedWinner;
    const expectedDetail = result?.performanceDetails?.[expectedWinnerId];
    if (expectedWinnerId && expectedWinnerId !== winnerId && expectedDetail?.swingType === 'collapse') {
      const collapseMoment = renderChallengeSpecificMoment(challenge, 'negative', [expectedWinnerId, winnerId]);
      return collapseMoment
        ? `${collapseMoment} ${contestantDisplayName(winnerId)} capitalizes and takes immunity.`
        : `${contestantDisplayName(expectedWinnerId)} unexpectedly falters during ${challenge?.name || 'the challenge'}, and ${contestantDisplayName(winnerId)} takes advantage.`;
    }
    if (result?.closeFinish?.wasClose && (result.closeFinish.upset || Number(result.closeFinish.gap || 0) < .45)) {
      return result.closeFinish.upset
        ? `${contestantDisplayName(winnerId)} steals the result in the final moments of a genuine photo finish.`
        : `${contestantDisplayName(winnerId)} holds on through a genuine photo finish.`;
    }
    return '';
  }

  function teamWinnerCircumstance(result, challenge, winnerName) {
    const winnerEntry = (result?.teamScores || []).find(team => team.name === winnerName);
    if (winnerEntry?.incident?.tone === 'positive') return winnerEntry.incident.text;
    if (winnerEntry?.incident?.tone === 'negative') {
      return `${winnerEntry.incident.text} Even so, ${winnerName} recover before the finish and still take immunity.`;
    }
    const loserEntry = (result?.teamScores || []).find(team => team.name === result?.loser);
    if (loserEntry?.incident?.tone === 'negative') {
      return `${loserEntry.incident.text} ${winnerName} stay steady and take immunity.`;
    }
    if (loserEntry?.incident?.tone === 'positive') {
      return `${loserEntry.incident.text} ${winnerName} still outperform them when the challenge is decided.`;
    }
    if (result?.closeFinish?.wasClose && (result.closeFinish.upset || Number(result.closeFinish.gap || 0) < .45) && winnerName === result?.winners?.[0]) {
      return result.closeFinish.upset
        ? `${winnerName} overturn the expected order in the final moments of ${challenge?.name || 'the challenge'}.`
        : `${winnerName} survive a genuine photo finish in ${challenge?.name || 'the challenge'}.`;
    }
    return '';
  }

  function appendWinnerCircumstance(copy, text) {
    if (!copy || !text) return;
    const note = document.createElement('p');
    note.className = 'challenge-winner-circumstance';
    note.textContent = text;
    copy.append(note);
  }


  function updateChallengeResultLayout() {
    if (!elements.challengeTeamBoard) return;
    const board = elements.challengeTeamBoard;
    const hasPrimaryWinnerCard = Boolean(board.querySelector('.challenge-individual-winner-card, .challenge-team-card.is-winner'));
    const hasSecondaryResult = Boolean(board.querySelector('.challenge-automatic-loser-card, .special-outcome-stack'));
    board.classList.toggle('has-stacked-results', hasPrimaryWinnerCard && hasSecondaryResult);
  }

  function appendChallengeSpecialOutcomes() {
    if (!elements.challengeTeamBoard || !state.challengeRevealed) return;
    const departures = (state.episodeOutcome?.departures || []).filter(departure => ['challenge-elimination', 'medical'].includes(departure.reason));
    if (departures.length) {
      const stack = document.createElement('div');
      stack.className = 'special-outcome-stack';
      departures.forEach(departure => {
        const card = document.createElement('article');
        card.className = `special-outcome-card is-${departure.reason === 'challenge-elimination' ? 'challenge' : departure.reason}`;
        card.append(ceremonyPortrait(departure.id, 'is-eliminated'));
        const copy = document.createElement('div');
        copy.className = 'special-outcome-copy';
        const label = document.createElement('span');
        label.textContent = departureDisplayLabel(departure.reason);
        const name = document.createElement('strong');
        name.textContent = contestantDisplayName(departure.id);
        const detail = document.createElement('p');
        detail.textContent = departure.detail || 'This contestant leaves without a regular vote.';
        copy.append(label, name, detail);
        card.append(copy);
        stack.append(card);
      });
      elements.challengeTeamBoard.append(stack);
    }
  }

  function renderChallengeExile() {
    const area = elements.challengeExileArea;
    if (!area) return;
    area.replaceChildren();
    const exile = state.episodeOutcome?.exile;
    area.hidden = !state.challengeRevealed || !exile?.id;
    if (area.hidden) return;

    const intro = document.createElement('article');
    intro.className = 'challenge-exile-intro-card';
    const copy = document.createElement('div');
    const label = document.createElement('span');
    label.textContent = 'EXILE DECISION';
    const title = document.createElement('strong');
    title.textContent = `${exile.selectedBy} Must Choose`;
    const detail = document.createElement('p');
    detail.textContent = `${exile.selectedBy} won immunity and the McLean Spa Hotel. Before ${exile.fromTeam} votes, the winners must choose one of its members to spend the night on Boney Island.`;
    copy.append(label, title, detail);
    intro.append(copy);
    area.append(intro);

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'secondary-btn challenge-exile-votes-btn';
    button.textContent = exile.votesShown ? 'Hide Votes' : 'Show Votes';
    button.addEventListener('click', () => {
      exile.votesShown = !exile.votesShown;
      renderChallengeExile();
      applyEpisodeControlState();
      syncCurrentEpisodeRecord();
      if (exile.votesShown) focusCeremonyElement(elements.challengeExileArea);
    });
    area.append(button);

    if (!exile.votesShown) return;
    const heading = document.createElement('h3');
    heading.textContent = 'The Winning Team Votes';
    const list = document.createElement('div');
    list.className = 'vote-breakdown-list challenge-exile-vote-list';
    (exile.ballots || []).forEach(ballot => list.append(createVoteBreakdownRow(ballot)));
    area.append(heading, list);

    const result = document.createElement('article');
    result.className = 'challenge-exile-result-card';
    result.append(ceremonyPortrait(exile.id));
    const resultCopy = document.createElement('div');
    const resultLabel = document.createElement('span');
    resultLabel.textContent = 'SENT TO EXILE';
    const resultName = document.createElement('strong');
    resultName.textContent = contestantDisplayName(exile.id);
    const resultDetail = document.createElement('p');
    resultDetail.textContent = `${contestantDisplayName(exile.id)} is safe from tonight's ceremony, cannot vote, and will return before the next challenge.`;
    resultCopy.append(resultLabel, resultName, resultDetail);
    result.append(resultCopy);
    area.append(result);
  }

  function renderChallengeBoard() {
    renderChallengeIntroduction();
    if (elements.challengeReveal) {
      elements.challengeReveal.hidden = !state.challengeRevealed;
      elements.challengeReveal.classList.toggle('is-finale-result-only', state.episodeType === 'finale-race');
    }
    if (elements.runChallengeBtn) {
      elements.runChallengeBtn.hidden = state.challengeRevealed;
      elements.runChallengeBtn.disabled = !state.episodeEvents.preChallenge.length || !state.challengeResult;
    }
    renderChallengeHighlights();
    if (!elements.challengeTeamBoard) return;
    elements.challengeTeamBoard.replaceChildren();
    elements.challengeTeamBoard.classList.remove('has-multiple-winners', 'has-showdown-results', 'has-dual-result-cards', 'has-stacked-results');

    if (!state.challengeRevealed || !state.challengeResult) {
      if (elements.challengeExileArea) elements.challengeExileArea.hidden = true;
      return;
    }

    if (state.challengeResult.merged) {
      const winnerId = state.challengeResult.individualWinner || state.challengeResult.winner;
      const card = document.createElement('article');
      card.className = 'challenge-individual-winner-card';
      const portrait = createChallengePortrait(winnerId);
      portrait.classList.add('is-individual-winner');
      const copy = document.createElement('div');
      const title = document.createElement('h3');
      title.textContent = contestantDisplayName(winnerId);
      const description = document.createElement('span');
      description.textContent = state.episodeType === 'return-challenge'
        ? 'has won the return challenge and is back in the game!'
        : state.episodeType === 'finale-race'
          ? 'has won the final race and the entire season!'
          : state.episodeType === 'final-four-showdown'
            ? 'has won the showdown and the sole elimination vote!'
            : 'has won individual immunity!';
      copy.append(title, description);
      appendWinnerCircumstance(
        copy,
        individualWinnerCircumstance(state.challengeResult, currentChallengeData(), winnerId)
      );
      card.append(portrait, copy);
      elements.challengeTeamBoard.append(card);

      if (state.episodeType === 'final-four-showdown' && state.automaticEliminatedId) {
        elements.challengeTeamBoard.classList.add('has-showdown-results', 'has-dual-result-cards');
        const loserCard = document.createElement('article');
        loserCard.className = 'challenge-automatic-loser-card';
        const loserPortrait = createChallengePortrait(state.automaticEliminatedId);
        const loserCopy = document.createElement('div');
        const loserName = document.createElement('h3');
        loserName.textContent = contestantDisplayName(state.automaticEliminatedId);
        const loserText = document.createElement('span');
        loserText.textContent = 'finished last and is automatically eliminated.';
        loserCopy.append(loserName, loserText);
        loserCard.append(loserPortrait, loserCopy);
        elements.challengeTeamBoard.append(loserCard);
      }
      appendChallengeSpecialOutcomes();
      updateChallengeResultLayout();
      renderChallengeExile();
      return;
    }

    const winnerNames = Array.isArray(state.challengeResult.winners) && state.challengeResult.winners.length
      ? state.challengeResult.winners
      : [state.challengeResult.winner].filter(Boolean);
    const winningTeams = winnerNames
      .map(name => (state.statusSnapshot || []).find(item => item.name === name)
        || state.teams.find(item => item.name === name)
        || (state.challengeResult.teamScores || []).find(item => item.name === name)
        || { name, members: [] })
      .filter(team => team?.name);
    elements.challengeTeamBoard.classList.toggle('has-multiple-winners', winningTeams.length > 1);
    winningTeams.forEach(winningTeam => {
      const data = teamOption(winningTeam.name);
      const card = document.createElement('article');
      card.className = 'challenge-team-card is-winner';
      card.style.setProperty('--team-color', data.color);
      const emblem = document.createElement('img');
      emblem.alt = `${winningTeam.name} emblem`;
      setTeamEmblemWithFallback(emblem, data);
      const copy = document.createElement('div');
      const title = document.createElement('h3');
      title.textContent = winningTeam.name;
      const description = document.createElement('span');
      description.textContent = 'have won immunity!';
      copy.append(title, description);
      appendWinnerCircumstance(
        copy,
        teamWinnerCircumstance(state.challengeResult, currentChallengeData(), winningTeam.name)
      );
      card.append(emblem, copy);
      elements.challengeTeamBoard.append(card);
    });
    appendChallengeSpecialOutcomes();
    updateChallengeResultLayout();
    renderChallengeExile();
  }

  function contestantDisplayName(id) {
    const contestant = state.contestantById.get(id);
    return contestant?.nickname || contestant?.fullName || 'Contestant';
  }

  function joinContestantNames(ids) {
    const names = ids.map(contestantDisplayName);
    if (names.length <= 1) return names[0] || 'the tied contestants';
    if (names.length === 2) return `${names[0]} and ${names[1]}`;
    return `${names.slice(0, -1).join(', ')}, and ${names.at(-1)}`;
  }

  function votePool() {
    if (!state.challengeRevealed || !state.challengeResult) return [];
    const exiledId = state.episodeOutcome?.exile?.id || '';
    if (state.challengeResult.merged) return state.activeIds.filter(id => id !== exiledId);
    if (!state.challengeResult.loser) return [];
    const losingTeam = state.teams.find(team => team.name === state.challengeResult.loser);
    return (losingTeam?.members || []).filter(id => state.activeIds.includes(id) && id !== exiledId);
  }

  function eligibleVoteTargets() {
    const pool = votePool();
    if (!state.challengeResult?.merged) return pool;
    const immuneId = state.challengeResult.individualWinner || state.challengeResult.winner;
    return pool.filter(id => id !== immuneId);
  }

  function reputationStrength(id, label) {
    return Number(runtimeFor(id).reputations?.[label] || 0);
  }

  function publicTargetHeat(targetId, pool, excludingVoter = '') {
    const voters = pool.filter(id => id !== targetId && id !== excludingVoter);
    if (!voters.length) return 0;
    return average(voters.map(voterId =>
      getDirectional(state.targetPriority, voterId, targetId) * .62
      + getDirectional(state.voteCommitment, voterId, targetId) * .38
    ), 0);
  }

  function activeAllianceMemberships(id, pool) {
    return state.alliances.filter(alliance => {
      if (!alliance.active || !alliance.members.includes(id)) return false;
      return alliance.members.filter(memberId => pool.includes(memberId)).length >= 2;
    });
  }

  function allianceVoteFactors(voterId, targetId, pool) {
    let pressure = 0;
    let protection = 0;
    activeAllianceMemberships(voterId, pool).forEach(alliance => {
      const activeMembers = alliance.members.filter(id => pool.includes(id));
      const loyalty = Number(alliance.memberLoyalty?.[voterId] ?? 50);
      if (activeMembers.includes(targetId)) {
        const promiseProtection = hasNarrativePromise(voterId, targetId, 'loyalty-promise') ? 8 : 0;
        protection = Math.max(
          protection,
          alliance.strength * .18 + loyalty * .12 - alliance.tension * .08 + promiseProtection
        );
        return;
      }
      const otherMembers = activeMembers.filter(id => id !== voterId);
      const sharedInterest = otherMembers.length
        ? average(otherMembers.map(id =>
          getDirectional(state.targetPriority, id, targetId) * .62
          + getDirectional(state.voteCommitment, id, targetId) * .38
        ), 0)
        : 0;
      const promisePressure = otherMembers.some(id => hasNarrativePromise(voterId, id, 'loyalty-promise')) ? 5 : 0;
      pressure = Math.max(
        pressure,
        alliance.strength * .34 + loyalty * .22 + sharedInterest * .44 - alliance.tension * .12 + promisePressure
      );
    });
    return {
      pressure: clampRange(pressure, 0, 100),
      protection: clampRange(protection, 0, 32)
    };
  }

  function challengeLiability(targetId) {
    const performance = Number(state.challengeResult?.performances?.[targetId] ?? 50);
    const wasLowlight = state.challengeResult?.highlights?.some(highlight =>
      highlight.subjectId === targetId && highlight.tone === 'negative'
    );
    return clampRange(
      (100 - performance) * .72
      + reputationStrength(targetId, 'Weak Link') * 8
      + (wasLowlight ? 16 : 0),
      0,
      100
    );
  }

  function strategicThreat(targetId, pool) {
    const traits = traitsFor(targetId);
    const runtime = runtimeFor(targetId);
    const performance = Number(state.challengeResult?.performances?.[targetId] ?? 50);
    const alliancePower = activeAllianceMemberships(targetId, pool).reduce(
      (maximum, alliance) => Math.max(maximum, alliance.strength),
      0
    );
    const closeBonds = pool.filter(id =>
      id !== targetId && currentRelationship(targetId, id) >= 3
    ).length;
    const socialReach = pool.length > 1 ? closeBonds / (pool.length - 1) * 100 : 0;
    return clampRange(
      performance * .22
      + traits.strategy * 10 * .23
      + runtime.strategicInfluence * .16
      + runtime.socialVisibility * .10
      + alliancePower * .18
      + socialReach * .11
      + reputationStrength(targetId, 'Strong Competitor') * 5
      + (traits.threat - 5.5) * 4.4
      + (traits.intimidation - 5.5) * 1.7
      - (traits.threatManagement - 5.5) * 3.5
      - (traits.subtlety - 5.5) * 1.4,
      0,
      100
    );
  }

  function socialIsolationScore(targetId, pool) {
    const runtime = runtimeFor(targetId);
    const otherIds = pool.filter(id => id !== targetId);
    const relation = otherIds.length
      ? average(otherIds.map(id => currentRelationship(targetId, id)), 0)
      : 0;
    const relationshipIsolation = clampRange((2 - relation) * 12.5, 0, 55);
    const alliancePenalty = activeAllianceMemberships(targetId, pool).length ? 0 : 20;
    return clampRange(
      runtime.isolation * .48 + relationshipIsolation + alliancePenalty
      + reputationStrength(targetId, 'Outsider') * 5,
      0,
      100
    );
  }

  function selfPreservationScore(voterId, targetId, pool) {
    const otherVoters = pool.filter(id => id !== voterId);
    const voterDanger = publicTargetHeat(voterId, pool, voterId);
    const consensus = publicTargetHeat(targetId, pool, voterId);
    const pressure = runtimeFor(voterId).emotionalPressure;
    return clampRange(
      consensus * (.48 + voterDanger / 260)
      + voterDanger * .27
      + pressure * .12
      + (otherVoters.length <= 2 ? 5 : 0),
      0,
      100
    );
  }

  function voteTargetScore(voterId, targetId, pool, options = {}) {
    const traits = traitsFor(voterId);
    const relationship = currentRelationship(voterId, targetId);
    const irritation = getDirectional(state.irritation, voterId, targetId);
    const grudge = currentGrudge(voterId, targetId);
    const plan = votePlanFor(voterId);
    const directionalCommitment = getDirectional(state.voteCommitment, voterId, targetId);
    const personalIntent = clampRange(
      getDirectional(state.targetPriority, voterId, targetId) * .48
      + directionalCommitment * .52
      + (plan.actualTarget === targetId ? (plan.commitment || 0) * .25 : 0),
      0,
      100
    );
    const hostility = clampRange(
      Math.max(0, -relationship) * 6
      + irritation * .20
      + grudge * .16,
      0,
      100
    );
    const alliance = allianceVoteFactors(voterId, targetId, pool);
    const planIndependence = hasNarrativePlan(voterId, 'self-preservation') ? .86 : 1;
    const independenceScale = clampRange((1 - (traits.independence - 5) * .045) * planIndependence, .62, 1.18);
    const alliancePressure = clampRange(alliance.pressure * independenceScale, 0, 100);
    const liability = challengeLiability(targetId);
    const disruption = teamDisruptionScore(targetId, pool);
    const threat = strategicThreat(targetId, pool);
    const suspicion = getDirectional(state.suspicion, voterId, targetId);
    const isolation = socialIsolationScore(targetId, pool);
    const selfPreservation = selfPreservationScore(voterId, targetId, pool);

    const components = {
      personalIntent: personalIntent * .25,
      alliancePressure: alliancePressure * .18,
      challengeLiability: liability * .16,
      teamDisruption: disruption * .13,
      strategicThreat: threat * .09,
      suspicion: suspicion * .06,
      isolation: isolation * .05,
      selfPreservation: selfPreservation * .05,
      hostility: hostility * .03
    };

    let score = Object.values(components).reduce((sum, value) => sum + value, 0);
    const protection = personalProtectionScore(voterId, targetId, pool);
    score -= protection;
    score += (traits.strategy - 5) * (threat - 50) * .020;
    score += Math.max(0, traits.aggression - 7) * (grudge + irritation) * .010;
    score += (traits.socialAwareness - 5) * (publicTargetHeat(targetId, pool, voterId) - 50) * .012;
    if (options.revote && options.previousTargetId === targetId) score += 8;

    const reasonKey = Object.entries(components).sort((a, b) => b[1] - a[1])[0]?.[0] || 'personalIntent';
    return {
      targetId,
      score: clampRange(score, 0, 100),
      reasonKey,
      components,
      protection: clampRange(protection, 0, 72)
    };
  }

  function committedVoteTarget(voterId, eligibleTargets, details) {
    const plan = votePlanFor(voterId);
    const plannedTarget = eligibleTargets.includes(plan.actualTarget) ? plan.actualTarget : '';
    const plannedCommitment = plannedTarget
      ? Math.max(plan.commitment || 0, getDirectional(state.voteCommitment, voterId, plannedTarget))
      : 0;
    if (plannedTarget && plannedCommitment >= 92) return plannedTarget;

    const ranked = eligibleTargets.map(targetId => ({
      targetId,
      commitment: Math.max(
        getDirectional(state.voteCommitment, voterId, targetId),
        plan.actualTarget === targetId ? plan.commitment || 0 : 0
      ),
      detail: details.find(item => item.targetId === targetId)
    })).sort((first, second) => second.commitment - first.commitment);
    const choice = ranked[0];
    const preparedContingency = ['backup-target', 'contingency-target', 'emergency-target', 'contingency-plan']
      .some(key => hasNarrativePlan(voterId, key));
    const minimumCommitment = preparedContingency ? 40 : 46;
    if (!choice || choice.commitment < minimumCommitment) return '';
    const topScore = Math.max(...details.map(item => item.score));
    const scoreTolerance = preparedContingency ? 21 : 16;
    if (choice.detail.score < topScore - scoreTolerance && choice.commitment < 80) return '';
    let followChance = choice.commitment >= 82 ? .92
      : choice.commitment >= 70 ? .86
        : choice.commitment >= 58 ? .75
          : .60;
    const traits = traitsFor(voterId);
    followChance += Math.max(0, traits.loyalty - 5) * .008;
    followChance -= Math.max(0, traits.deception - 7) * .010;
    if (preparedContingency) followChance += .06;
    const activeVotePromise = runtimeFor(voterId).promises.some(promise =>
      promise.active !== false
      && promise.key === 'vote-stability-promise'
      && state.activeIds.includes(promise.toId)
      && (!Number.isFinite(Number(promise.expiresEpisode)) || state.episodeNumber <= Number(promise.expiresEpisode))
    );
    if (activeVotePromise) followChance += .07;
    return Math.random() < clampRange(followChance, .52, .97) ? choice.targetId : '';
  }

  function castBallot(voterId, eligibleTargets, pool, options = {}) {
    if (!eligibleTargets.length) return null;
    if (eligibleTargets.length === 1) {
      const detail = voteTargetScore(voterId, eligibleTargets[0], pool, options);
      return { voterId, targetId: eligibleTargets[0], score: detail.score, reasonKey: detail.reasonKey };
    }
    const details = eligibleTargets.map(targetId => voteTargetScore(voterId, targetId, pool, options));
    const committedTarget = committedVoteTarget(voterId, eligibleTargets, details);
    if (committedTarget) {
      const detail = details.find(item => item.targetId === committedTarget);
      return { voterId, targetId: committedTarget, score: detail.score, reasonKey: detail.reasonKey };
    }
    const topScore = Math.max(...details.map(item => item.score));
    let realistic = details.filter(item => item.score >= topScore - 16);
    const plan = votePlanFor(voterId);
    if (plan.actualTarget && eligibleTargets.includes(plan.actualTarget) && (plan.commitment || 0) >= 35) {
      const plannedDetail = details.find(item => item.targetId === plan.actualTarget);
      if (plannedDetail && !realistic.includes(plannedDetail)) realistic.push(plannedDetail);
    }
    if (!realistic.length) realistic = [details.sort((a, b) => b.score - a.score)[0]];
    const selected = weightedChoice(realistic, item => Math.exp((item.score - topScore) / 8));
    return {
      voterId,
      targetId: selected.targetId,
      score: selected.score,
      reasonKey: selected.reasonKey
    };
  }

  function tallyBallots(ballots, candidateIds) {
    const tally = Object.fromEntries(candidateIds.map(id => [id, 0]));
    ballots.filter(Boolean).forEach(ballot => {
      const targetIds = Array.isArray(ballot.targetIds) ? ballot.targetIds : [ballot.targetId].filter(Boolean);
      const cancelledTargetIds = new Set(ballot.cancelledTargetIds || []);
      targetIds.forEach(targetId => {
        if (!cancelledTargetIds.has(targetId) && Object.prototype.hasOwnProperty.call(tally, targetId)) tally[targetId] += 1;
      });
    });
    return tally;
  }

  function idsWithHighestVotes(tally) {
    const entries = Object.entries(tally);
    if (!entries.length) return [];
    const highest = Math.max(...entries.map(([, votes]) => Number(votes)));
    return entries.filter(([, votes]) => Number(votes) === highest).map(([id]) => id);
  }

  function suspenseSafeOrder(pool, excludedIds, tally) {
    const excluded = new Set(excludedIds);
    const groups = new Map();
    pool.filter(id => !excluded.has(id)).forEach(id => {
      const votes = Number(tally[id] || 0);
      if (!groups.has(votes)) groups.set(votes, []);
      groups.get(votes).push(id);
    });
    const order = [...groups.keys()]
      .sort((first, second) => first - second)
      .flatMap(votes => shuffled(groups.get(votes)));
    if (state.merged) {
      const immuneId = state.challengeResult?.individualWinner || state.challengeResult?.winner;
      const immuneIndex = order.indexOf(immuneId);
      if (immuneIndex > 0) order.unshift(order.splice(immuneIndex, 1)[0]);
    }
    return order;
  }

  function buildRevote(initialTiedIds, pool, initialBallots) {
    const voters = pool.filter(id => !initialTiedIds.includes(id));
    const previousVoteByVoter = new Map(initialBallots.map(ballot => [ballot.voterId, ballot.targetId]));
    const ballots = voters.map(voterId => castBallot(
      voterId,
      initialTiedIds,
      pool,
      { revote: true, previousTargetId: previousVoteByVoter.get(voterId) || '' }
    )).filter(Boolean);
    const tally = tallyBallots(ballots, initialTiedIds);
    const revoteTop = idsWithHighestVotes(tally);
    let eliminatedId = revoteTop[0] || initialTiedIds[0];
    let tieBroken = false;
    const tiebreaker = {};
    if (revoteTop.length > 1) {
      tieBroken = true;
      eliminatedId = shuffled(revoteTop)[0];
      tiebreaker.method = 'chris-random';
      tiebreaker.candidates = [...revoteTop];
      tiebreaker.selectedId = eliminatedId;
    }
    return {
      voters,
      ballots,
      tally,
      eliminatedId,
      safeIds: initialTiedIds.filter(id => id !== eliminatedId),
      tieBroken,
      tiebreaker
    };
  }

  function randomSendoff(name) {
    const phrases = [
      `${name}, time for you to pack it up. See ya.`,
      `Welp, there we have it. ${name}, adios.`,
      `${name}, your camp vacation is officially over. Scram.`,
      `No marshmallow for you, ${name}. Better luck somewhere else.`,
      `${name}, the Boat of Losers is honking. Try not to keep it waiting.`,
      `${name}, you’ve been voted off. Please exit before Chef volunteers to help.`,
      `${name}, that was your final campfire. The gift shop is conveniently located nowhere near here.`,
      `${name}, your team has spoken—and apparently they had a lot to say. Bye!`,
      `${name}, grab your bags, your bruises, and whatever dignity you have left.`,
      `${name}, congratulations! You’ve won an all-expenses-unpaid trip off the island.`,
      `${name}, the votes are in, the marshmallows are gone, and so are you.`,
      `${name}, your summer at Camp Wawanakwa has been officially cancelled.`,
      `${name}, Chef already packed your stuff. He may have used a wood chipper.`,
      `${name}, you came, you competed, and now you’re blocking the dock. Move it.`,
      `${name}, the good news is you survived camp. The bad news is you didn’t survive the vote.`,
      `${name}, your cabin bunk is about to become valuable real estate.`,
      `${name}, please report to the Boat of Losers before it becomes the Swim of Losers.`,
      `${name}, no immunity, no marshmallow, no more camera time. Rough night.`,
      `${name}, your fellow campers have lovingly selected you to leave immediately.`,
      `${name}, looks like your strategy just took a one-way boat ride.`,
      `${name}, this island is dangerous, humiliating, and completely done with you.`,
      `${name}, thanks for playing. By “thanks,” I mean please get off my set.`,
      `${name}, the campfire ceremony is over—and so is your season.`,
      `${name}, you’re out. Try not to make the Boat of Losers any sadder than it already is.`,
      `${name}, your adventure ends here. Your therapy bills, however, are just beginning.`,
      `${name}, one minute you’re a camper, the next you’re boat cargo. Funny how that works.`,
      `${name}, the island has voted, and unlike you, the island is staying.`,
      `${name}, you can keep the memories. Production already sold the footage.`,
      `${name}, your elimination is final, dramatic, and great for our ratings.`,
      `${name}, it’s time to leave camp and return to a world with actual health regulations.`
    ];
    return phrases[randomInteger(0, phrases.length - 1)];
  }

  function mergedJuryIds(finalists = [], extraIds = []) {
    const finalistSet = new Set(finalists);
    const mergeEliminations = state.episodes
      .filter(record => record.merged)
      .slice()
      .sort((first, second) => first.number - second.number)
      .flatMap(episodeEliminatedIds);
    const eligibleExtras = extraIds.filter(id =>
      state.episodes.some(record => record.merged && episodeEliminatedIds(record).includes(id))
    );
    return [...new Set([...mergeEliminations, ...eligibleExtras].filter(id =>
      id && state.contestantById.has(id) && !finalistSet.has(id)
    ))];
  }

